local function Died()
	if not __Vals.already_ded then
		__Vals.already_ded = true
		-- if the character died in the middle of a scene - the scene stops
		if MD_.Re_Bots[Character].Scene_Config.Stop_Scene then
			MD_.Re_Bots[Character].Scene_Config:Stop_Scene()
		end

		MD_.FF:PlaySound(Human_Head,"EN_Dead_002",{PlayOnRemove=true})
		MD_.FF:PlaySound(Human_Head,"EN_Dead_001",{PlayOnRemove=true})
		MD_.FF:PlaySound(Human_Head,"Player_Ragdoll",{PlayOnRemove=true})
		MD_.FF:RagdollMode("Add",Character)
		local TS = LOCAL_MD_.Meta_Elements.Died
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS=TS,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Jumping,TS=TS,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Auto_Rotate,TS=TS,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS=TS,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.SwordAttack,TS=TS,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.GunUsing,TS=TS,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.FloorThrowYourself,TS=TS,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.MMMAAAASSSVVV,TS=TS,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.NoHeadRotation,TS=TS,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Holding,TS=TS,NN=nil,FF=nil})	
		if LOCAL_MD_.Facial_Config then
			LOCAL_MD_.Facial_Config:FuckingDie()
		end
		check__switch({BB=true,TM=Anim_Config,TS=TS,NN="Custom_Animation_Process",FF=nil})
		Anim_Config:Restart_Current_Animation()
		Anim_Config:AllStopAnimation(0)
		_G.Remotes_Respawn:Fire()
	end
end
Humanoid.Died:connect(Died)

