local function grab(RayCastResults)
	__Vals.HoldingDebounce = true
	__Vals.CLIMB_ROLE = false
	
	local BASE_PART = RayCastResults.Instance
	local BASE_NORMAL = RayCastResults.Normal
	local BASE_POSITION = RayCastResults.Position
	local F_CF,F_SZ = MD_.FF:FlipToVector(BASE_PART, Vector3.new(0,1,0))
	local WELDER_MAIN,body_gyro,body_pos,_run_service_grab,PartGyro,WELD_LEDGE_ANIMATOR
	local _connection_animation = {}
	local Direction= Human_Root.CFrame.lookVector
	local oldtick_can_move = tick() +.25
	local TS = {Name="Grab__" .. tick()}
	
	--█░█ █ ▀█▀ █▄▄ █▀█ ▀▄▀   █▀▄ █▀▀ ▀█▀ █▀▀ █▀▀ ▀█▀ █▀█ █▀█
	--█▀█ █ ░█░ █▄█ █▄█ █░█   █▄▀ ██▄ ░█░ ██▄ █▄▄ ░█░ █▄█ █▀▄
	
	do
		local czxc = F_CF:PointToObjectSpace(BASE_POSITION)
		local pos = F_CF * CFrame.new(czxc.X,0,czxc.Z)
		for i,v in pairs (MD_.FF:hitbox_detector({CFrame=pos*CFrame.new(0,(F_SZ.Y/2)+.25,0);Size=Vector3.new(2,.25,2)},1,false)) do
			if v.CanCollide and v~=BASE_PART and not v:IsDescendantOf(Character) then
				check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Holding,TS=TS,NN=nil,FF=nil})
				__Vals.HoldingDebounce = false
				delay(.25,function()
					check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Holding,TS=TS,NN=nil,FF=nil})
				end)
				return	
			end
		end
	end
	
	local newinstance2 = __LA(Humanoid.Animator, LOCAL_MD_.Anim_Config.Animations.Holding_Idle.Animation) newinstance2:Play()
	local newinstance = __LA(Humanoid.Animator, LOCAL_MD_.Anim_Config.Animations.Holding_Right.Animation)
	local animation_flip = "RESET"
	
	local function SWITCH(state)
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.Auto_Rotate,TS=TS,NN=nil,FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Anim_Config,TS=TS,NN="Custom_Animation_Process",FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.NoTorsoRotation,TS=TS,NN=nil,FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.MMMAAAASSSVVV,TS=TS,NN=nil,FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.GunUsing,TS=TS,NN=nil,FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.SwordAttack,TS=TS,NN=nil,FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS=TS,NN=nil,FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.Jumping,TS=TS,NN=nil,FF=nil})
		check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.FloorThrowYourself,TS=TS,NN=nil,FF=nil})
	end SWITCH(true) 
	
	--local function ghostpart(cframe,size)
	--	local insta = BASE_PART:Clone()
	--	insta.Parent = workspace.Camera
	--	insta.CanCollide = false
	--	insta.Anchored = true
	--	insta.CFrame = cframe
	--	insta.Size = size + Vector3.new(1,1,1)
	--	insta.Transparency = .5
	--	insta.Color = Color3.fromRGB(255,0,0)
	--	return insta
	--end
	--local insta_block = ghostpart(F_CF,F_SZ)
	
	PartGyro= INST("Part",Character)
	PartGyro.CanCollide = false
	PartGyro.Size = VE3()
	PartGyro.Transparency=1
	PartGyro.CFrame=Human_Root.CFrame
	PartGyro.Name="__HOLDING__PartGyro"
	MD_.FF:Weld(PartGyro,Human_Root)
	
	--█▀▀ █▀▀ █▀█ ▄▀█ █▀▄▀█ █▀▀   █▀█ █ █▀█
	--█▄▄ █▀░ █▀▄ █▀█ █░▀░█ ██▄   █▀▄ █ █▀▀
	do
		WELD_LEDGE_ANIMATOR = INST("Part",Character)
		WELD_LEDGE_ANIMATOR.CanCollide = false
		WELD_LEDGE_ANIMATOR.Size = VE3(1,1,1)*0
		WELD_LEDGE_ANIMATOR.Transparency=1
		
		--
		local czxc = F_CF:PointToObjectSpace(BASE_POSITION)
		local pos = F_CF * CFrame.new(czxc.X,0,czxc.Z) -- safe
		local MATRIX_UP_VECTOR,MATRIX_LOOK_VECTOR = F_CF.UpVector,BASE_NORMAL.Unit
		local NEXT_CF = CFrame.fromMatrix(pos.p,-MATRIX_LOOK_VECTOR:Cross(MATRIX_UP_VECTOR),MATRIX_UP_VECTOR,MATRIX_LOOK_VECTOR) + (BASE_NORMAL*1) + (F_CF.UpVector*((F_SZ.Y/2)-2.25))
		WELD_LEDGE_ANIMATOR.CFrame = NEXT_CF
		--
		WELD_LEDGE_ANIMATOR.Name="__HOLDING__LEDGE"
		WELDER_MAIN = MD_.FF:Weld(WELD_LEDGE_ANIMATOR,BASE_PART)
		WELDER_MAIN.Parent = WELD_LEDGE_ANIMATOR
	end
	--
	
	--█▄▄ █▀█ █▀▄ █▄█   █ █▄░█ █▀ ▀█▀ ▄▀█ █▄░█ █▀▀ █▀▀ █▀
	--█▄█ █▄█ █▄▀ ░█░   █ █░▀█ ▄█ ░█░ █▀█ █░▀█ █▄▄ ██▄ ▄█
	
	do
		body_gyro = INST("BodyGyro",PartGyro)
		body_gyro.MaxTorque=VE3(1,1,1)*999999
		body_gyro.D=100
		--
		body_pos = INST("BodyPosition",PartGyro)
		body_pos.Position = WELD_LEDGE_ANIMATOR.CFrame.p
		body_pos.MaxForce = VE3(1,1,1)*999999
		body_pos.P=5
		body_pos.D=65
		_Services.Tween:Create(body_pos,TWEEN_IN(.25,Enum.EasingStyle.Sine,Enum.EasingDirection.Out,0,false,0),{P=2555}):Play()
	end

	--█░█ █▄░█ █░█ █▀█ █░░ █▀▄
	--█▄█ █░▀█ █▀█ █▄█ █▄▄ █▄▀
	
	local function Finish(jump)
		_run_service_grab:Disconnect()
		body_pos.Position = Human_Root.CFrame.p
		SWITCH(nil) 
	--	insta_block:Destroy()
		WELD_LEDGE_ANIMATOR:Destroy()
		PartGyro:Destroy()
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Holding,TS=TS,NN=nil,FF=nil})
		__Vals.HoldingDebounce = false
		delay(.25,function()
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Holding,TS=TS,NN=nil,FF=nil})
		end)

		newinstance:Stop(.2)
		newinstance2:Stop(.2)

		LOCAL_MD_.Anim_Config:AllStopAnimation(0)
		LOCAL_MD_.Anim_Config:Restart_Current_Animation()
		
		for _,v in pairs (_connection_animation) do v:Disconnect() end
		
		__Vals.CanDoubleJump=tick()
		__Vals.Can_Throw_Yourself=true
		__Vals.Can_Throw_Yourself_Knocked_Out=true
		
		if jump then
			LOCAL_MD_.FF:Jump_Action({allow_double_jump=true;double=true})
		end
		
	end

	--▄▀█ █▄░█ █ █▀▄▀█ ▄▀█ ▀█▀ █ █▀█ █▄░█
	--█▀█ █░▀█ █ █░▀░█ █▀█ ░█░ █ █▄█ █░▀█
	
	LOCAL_MD_.Anim_Config:AllStopAnimation(.15)
	newinstance:Play(.15)
	newinstance:AdjustSpeed(2)
	MD_.FF:PlaySound(Human_Head,{"Player_Holding_Wall_002","Player_Holding_Wall_001"},{PlayOnRemove=true})
	
	local function install_step_sound()
		for _,v in pairs (_connection_animation) do v:Disconnect() end
		table.insert(_connection_animation,newinstance:GetMarkerReachedSignal("ESPECIAL"):Connect(function(value)
			if value == "FOOT" then
				MD_.FF:PlaySound(Character.HumanoidRootPart,"Player_Holding_Wall_Step",{PlayOnRemove=true;PlaybackSpeed=(((M_RAN()*65)%50)/100) + .8})
			end
		end))
	end
	--█░░ █▀█ █▀█ █▀█
	--█▄▄ █▄█ █▄█ █▀▀
	
	local rollGoal = 0
	_run_service_grab = _Services.Run.RenderStepped:Connect(function(t, dt)
		if oldtick_can_move - tick() < 0 then
			rollGoal = MD_.FF:Lerp(rollGoal,(Humanoid.MoveDirection:Cross(__Vals.Human_Root_Look).Y)/3,.1)
			WELDER_MAIN.C0 = WELDER_MAIN.C0 + Vector3.new(-rollGoal*.5,0,0)
			
			if rollGoal < 0 then
				if animation_flip ~= "LEFT" then
					animation_flip = "LEFT"
					newinstance:Stop(.2)
					newinstance = __LA(Humanoid.Animator, LOCAL_MD_.Anim_Config.Animations.Holding_Left.Animation)
					newinstance:Play(.1)
					install_step_sound()
				end
			elseif animation_flip ~= "RIGHT" then
				animation_flip = "RIGHT"
				newinstance:Stop(.2)
				newinstance = __LA(Humanoid.Animator, LOCAL_MD_.Anim_Config.Animations.Holding_Right.Animation)
				newinstance:Play(.1)
				install_step_sound()
			end
			
			newinstance:AdjustSpeed(math.abs(rollGoal)*10)
			
			local RayCastResults = MD_.FF:CastUntilHitSimple(Human_Root.CFrame.p,Human_Root.CFrame.p+(Human_Root.CFrame.lookVector*5),RayParamsPlatform)
			if (WELD_LEDGE_ANIMATOR.Position-Human_Root.Position).magnitude > 5 or RayCastResults.Instance ~= BASE_PART then
				Finish()
			end
		end
		
		Humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
		
		body_pos.Position = WELD_LEDGE_ANIMATOR.CFrame.p
		body_gyro.CFrame = WELD_LEDGE_ANIMATOR.CFrame * CFrame.Angles(math.rad(-20),0,0)

		if __Vals.CLIMB_ROLE or MD_.FF:not_empty__switch(LOCAL_MD_.Meta_Elements.Holding.LockSwitch) then
			Finish(__Vals.CLIMB_ROLE)
		end
	end)
	
end

_Services.Run.Heartbeat:Connect(function()
	do -- platform
		local RayCastResults = MD_.FF:CastUntilHitSimple(Human_Root.CFrame.p,Human_Root.CFrame.p-Vector3.new(0,6,0),RayParamsPlatform)

		if RayCastResults and RayCastResults.Instance then
			local hit2 = RayCastResults.Instance

			if (__Vals.LastPart and __Vals.LastPart:IsDescendantOf(_Services.Workspace) and __Vals.LastPart == hit2 ) or
				(__Vals.LastPartForever and __Vals.LastPartForever:IsDescendantOf(_Services.Workspace))
			then
				local USEPART = __Vals.LastPart or __Vals.LastPartForever
				__Vals.LastCFrame = __Vals.LastCFrame or USEPART.CFrame

				local Rel = USEPART.CFrame * __Vals.LastCFrame:inverse()

				Human_Root.CFrame = Rel * Human_Root.CFrame
				Camera.CFrame = Rel * Camera.CFrame
				__Vals.LastCFrame = USEPART.CFrame
			else
				__Vals.LastPart = nil
				__Vals.LastCFrame = nil
				__Vals.LastPartForever = nil
			end

			if hit2 then
				if hit2.Parent:FindFirstChild("Platform_System_Movement") or hit2:FindFirstChild("Platform_System_Movement") then
					__Vals.LastPart = hit2
				elseif hit2.Parent:FindFirstChild("Platform_System_Movement_Forver") then 
					if __Vals.LastPartForever and __Vals.LastPartForever ~= hit2 then
						__Vals.LastPartForever = nil
					elseif not __Vals.LastPartForever then
						__Vals.LastPartForever = hit2
					end
				end
			end
		else
			__Vals.LastPart = nil
			__Vals.LastCFrame = nil
		end
	end
	if Anim_Config.States.Falling and not __Vals.HoldingDebounce and not MD_.FF:not_empty__switch(LOCAL_MD_.Meta_Elements.Holding.LockSwitch) and Human_Root.Velocity.Y <= 0  then -- ledge
		local RayCastResults = MD_.FF:CastUntilHitSimple(Human_Root.CFrame.p,Human_Root.CFrame.p+(Human_Root.CFrame.lookVector*5),RayParamsPlatform)
		if RayCastResults and RayCastResults.Instance and RayCastResults.Normal.unit:Dot(Vector3.new(0,1,0)) < math.rad(20) and RayCastResults.Instance:FindFirstChild("Holding_System_Movement") then
			local part = RayCastResults.Instance
			local MainVector,MainSize = MD_.FF:GetDotFrom(part,Vector3.new(0,1,0))
			MainSize/=2
			local POS = part.CFrame +(MainVector*(MainSize-2)) -- top pint
			if Human_Head.Position.Y >= POS.Y then
				grab(RayCastResults)
			end
		end
	end
end)

--█████████████████████████████████████████████████████████████████
--█▄▄▄─▄█▄─██─▄█▄─▀█▀─▄█▄─▄▄─████▀▄─██─▄▄▄─█─▄─▄─█▄─▄█─▄▄─█▄─▀█▄─▄█
--█─▄█─███─██─███─█▄█─███─▄▄▄████─▀─██─███▀███─████─██─██─██─█▄▀─██
--▀▄▄▄▀▀▀▀▄▄▄▄▀▀▄▄▄▀▄▄▄▀▄▄▄▀▀▀▀▀▄▄▀▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀

function LOCAL_MD_.FF:Jump_Action(T)
	local T = T or {}
	__Vals.JumpExtra = 10
	Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
		
	if T.back then -- ehhhhhhhh, i forgot how this shit works :,v
		Human_Root.Velocity=Vector3.new(0,79,0)+(Human_Root.CFrame.lookVector*-35)
	else
		if T.alternative then
			local BodyVelocity = Instance.new("BodyVelocity",Human_Root)
			BodyVelocity.MaxForce=Vector3.new(0,999999,0)
			BodyVelocity.Velocity=Vector3.new(0,30,0)
			Human_Root.Velocity=Vector3.new(0,30,0)+(Human_Root.CFrame.lookVector*95)
			_Services.Debris:AddItem(BodyVelocity,.05)
		else
			local BodyVelocity = Instance.new("BodyVelocity",Human_Root)
			BodyVelocity.MaxForce=Vector3.new(0,999999,0)
			BodyVelocity.Velocity=Vector3.new(0,38,0)
			_Services.Debris:AddItem(BodyVelocity,.05)
		end
	end
	if not LOCAL_MD_.HurtTickCooldown and LOCAL_MD_.Facial_Config then -- if hurts, cant change expression
		LOCAL_MD_.Facial_Config:jump_call_event()
	end

	if T.back then
		MD_.FF:PlaySound(Human_Root,"Player_Wall_Jump_001",{PlayOnRemove=true})
		Anim_Config:PlayAnimation("BackJumpAnim",true,0.1)
		local clone_ = particle_backjump.emitter:Clone()
		clone_.Parent = particle_backjump
		clone_.Enabled=true
		delay(.4,function()
			clone_.Enabled=false
		end)
		_Services.Debris:AddItem(clone_,3)
		__Vals.CanDoubleJump=nil
	elseif ((Anim_Config.States.Falling and not __Vals.FreeLandedJump) or T.double) then	
		Anim_Config:PlayAnimation("DoubleJumpAnim",true,0.1)
		if T.allow_double_jump then
			__Vals.CanDoubleJump=tick()+.1
		else
			__Vals.CanDoubleJump=nil
		end
		local clone_ = particle_jump.emitter:Clone()
		clone_.Parent = particle_jump
		clone_.Enabled=true
		delay(.2,function()
			clone_.Enabled=false
		end)
		_Services.Debris:AddItem(clone_,3)
		
		MD_.FF:PlaySound(Human_Head,"Player_Jump2",{PlayOnRemove=true})
	elseif not Anim_Config.States.Falling then
		if T.alternative then
			Anim_Config:PlayAnimation("JumpAlternativeAnim",true,0.1)
		else
			Anim_Config:PlayAnimation("JumpAnim",true)
		end
		MD_.FF:CreatedParticle("Jumping",(Human_Root.CFrame*CFrame.new(0,-1,0)).p,{DebrisTime=1;ParticleTime=.1})
		MD_.FF:PlaySound(Human_Head,"Player_Jump",{PlayOnRemove=true})
		__Vals.CanDoubleJump=tick()+.1
		__Vals.Can_Throw_Yourself=true
	end

	__Vals.FreeLandedJump = false
end

