function LOCAL_MD_.FF:Scene_Updated_Meta(state)
	local TS = MD_.Meta_Elements.Scenes_PLAY
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.Jumping,TS=TS,NN=nil,FF=nil})
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.Auto_Rotate,TS=TS,NN=nil,FF=nil})
	check__switch({BB=state,TM=Anim_Config,TS=TS,NN="Custom_Animation_Process",FF=nil})
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS=TS,NN=nil,FF=nil})	
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.SwordAttack,TS=TS,NN=nil,FF=nil})	
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.GunUsing,TS=TS,NN=nil,FF=nil})	
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.FloorThrowYourself,TS=TS,NN=nil,FF=nil})	
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.MMMAAAASSSVVV,TS=TS,NN=nil,FF=nil})
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.Free_Camera,TS=TS,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.Invisible_Anim,TS=TS,NN=nil,FF=LOCAL_MD_.FF.Invisible_Anim})
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.FirstPerson,TS=TS,NN=nil,FF=nil})
	check__switch({BB=state,TM=LOCAL_MD_.Meta_Elements.Holding,TS=TS,NN=nil,FF=nil})
	Anim_Config:Restart_Current_Animation()
end

