--Input List
local List_KeyCodes={
	[Enum.KeyCode.T]=function(state)
		if state ~= "ON" then return end
		LOCAL_MD_.FF:FirstPerson("Both")
	end,
	[Enum.KeyCode.LeftShift]=function(state)
		LOCAL_MD_.LeftShift_state = state
	end,
	[Enum.KeyCode.V]=function(state)
		if state ~= "ON" then return end
		LOCAL_MD_.FF:MMMAAAASSSVVV()
	end,
	[Enum.KeyCode.R]=function(state)
		if state ~= "ON" then return end
		LOCAL_MD_.FF:Switch_Weapon()
	end,
	[Enum.KeyCode.P]=function(state)
		if state ~= "ON" then return end
		MainUI.Enabled = not MainUI.Enabled
	end,
	[Enum.KeyCode.F]=function(state)
		if state ~= "ON" then return end
		LOCAL_MD_.Health = 5
		LOCAL_MD_.FF:CheckHealth()
	end,
	[Enum.KeyCode.G]=function(state)
		if state ~= "ON" then return end
		LOCAL_MD_.Health -= 1
		LOCAL_MD_.FF:CheckHealth()
	end,
	[Enum.UserInputType.MouseButton1]=function(state,gameProcessed)
		if state == "ON" then
			LOCAL_MD_.ClickMouseButton1=true
			if gameProcessed then return end
			if LOCAL_MD_.Current_Weapon == "Melee" then
				LOCAL_MD_.FF:SwordAttack()
			else
				LOCAL_MD_.FF:Shoot()
			end
		elseif state == "OFF" then
			LOCAL_MD_.ClickMouseButton1=false
		end
	end,
	[Enum.KeyCode.C]=function(state)
		if state ~= "ON" then return end
		if Anim_Config.WalkingAnim and not Anim_Config.States.Falling and not Anim_Config.States.Jumping then
			LOCAL_MD_.FF:FloorThrow()
		else
			LOCAL_MD_.FF:Throw()
		end
	end,
	[Enum.KeyCode.Space]=function(state)
		if state ~= "ON" then return end
		__Vals.CLIMB_ROLE=true
		__Vals.Throw_Jump_Bool=true
		if not not_empty__switch(LOCAL_MD_.Meta_Elements.Jumping.LockSwitch) then
			if (__Vals.CanDoubleJump and __Vals.CanDoubleJump - tick() < 0 and not not_empty__switch(LOCAL_MD_.Meta_Elements.DoubleJumping.LockSwitch)) or not Anim_Config.States.Falling or __Vals.FreeLandedJump then
				local Stamina_Return 
				if LOCAL_MD_.StaminaAmount >= 10 then
					Stamina_Return = true
				else
					LOCAL_MD_.FF:Stamina_Required(10)
				end
				if (Stamina_Return or __Vals.FreeLandedJump)  then
					if not __Vals.FreeLandedJump then
						LOCAL_MD_.FF:Stamina_Removed(10)
					end
					LOCAL_MD_.FF:Jump_Action()
				end
			end
		end
	end,
}

--██████████████████████████████████████████████████████████████████████████████████████████████████████
--█▄─▄█▄─▀█▄─▄█▄─▄▄─█▄─██─▄█─▄─▄─███─▄▄▄─█─▄▄─█▄─▀█▄─▄█▄─▀█▄─▄█▄─▄▄─█─▄▄▄─█─▄─▄─█▄─▄█─▄▄─█▄─▀█▄─▄█─▄▄▄▄█
--██─███─█▄▀─███─▄▄▄██─██─████─█████─███▀█─██─██─█▄▀─███─█▄▀─███─▄█▀█─███▀███─████─██─██─██─█▄▀─██▄▄▄▄─█
