_Services.UserInput.InputEnded:connect(function(input, gameProcessed)
	if List_KeyCodes[input.KeyCode] then List_KeyCodes[input.KeyCode]("OFF",gameProcessed) end
	if List_KeyCodes[input.UserInputType] then List_KeyCodes[input.UserInputType]("OFF",gameProcessed) end
end)

_Services.UserInput.InputBegan:connect(function(input, gameProcessed)
	if List_KeyCodes[input.KeyCode] then List_KeyCodes[input.KeyCode]("ON",gameProcessed) end
	if List_KeyCodes[input.UserInputType] then List_KeyCodes[input.UserInputType]("ON",gameProcessed) end
end)
