-- Update Notice
spawn(function()
	local data_table = _G.Remotes_RequestGameVersion:Invoke()
	-- Get Assets Version --
	local LocalPicture = Instance.new("ImageLabel") 
	LocalPicture.Image = "rbxasset://Install/" .. data_table.AssetsVersion .. ".png"
	local function setThumb(contentId, status)
		if Enum.AssetFetchStatus.Success == status then
			Current_Assets_Version = data_table.AssetsVersion
		else
			Current_Assets_Version = "Unknow"
		end
	end
	_Services.ContentProvider:PreloadAsync({LocalPicture},setThumb)
	repeat wait() until Current_Assets_Version 
	--

	local GameInfo = _G.Game_UI.GameInfo:Clone()
	GameInfo.Parent = Player.PlayerGui
	GameInfo.assets_version_label.Text = "Assets Version " .. Current_Assets_Version
	GameInfo.game_version_label.Text = "Game Version " .. Current_Game_Version

	local function ClipBoard (button,text)
		MD_.FF:animated_hover("Style_1",button,{SFX="UI_Hover_001"})	
		button.MouseButton1Click:connect(function()
			text:CaptureFocus()
		end)
	end

	local BadColor = COR_RGB(255, 20, 24)
	local CorrectColor = COR_RGB(55, 255, 0)

	--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘
	--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘
	if Current_Game_Version ~= data_table.GameVersion or Current_Assets_Version ~= data_table.AssetsVersion then
		local FR = GameInfo.Frame
		MD_.FF:animated_hover("Style_1",FR.close_button,{SFX="UI_Hover_001"})	
		FR.close_button.MouseButton1Click:connect(function()
			
			FR:Destroy()
			GameInfo:Destroy()
		end)
		FR.Visible = true
		-- assets version
		FR.assets_currentversion.Text 	= "Current Assets Version : [ " 		.. data_table.AssetsVersion .. " ]"
		FR.assets_urversion.Text 		= "Your Assets Version : [ " 		.. Current_Assets_Version .. " ]"
		FR.assets_url.Text = data_table.AssetsURl
		--◘◘--◘◘--◘◘--◘◘--◘◘
		if Current_Assets_Version == data_table.AssetsVersion then
			FR.assets_urversion.TextColor3=CorrectColor
			FR.assets_upto.Visible = true
