			local Message = "Current Game Version : [ __Version__ ] you are up to date! "
			FR.game_upto.Text = Message:gsub("__Version__",data_table.GameVersion)
		else
			FR.game_urversion.TextColor3=BadColor
			ClipBoard (FR.game_button,FR.game_url)
		end
		--
	else
