SRC[6633]=[=[local module = {}
local PP = script.Parent
local MainPlatform = PP:WaitForChild("MainPlatform")
local runservice = game:GetService("RunService")
local tweenservice = game:GetService("TweenService")
local Settings = PP.Settings

local PointsList = {}
for _,point in pairs (PP.PointsFolder:GetChildren()) do
	local PosValue = point:FindFirstChild("Pos")
	PointsList[PosValue.Value] = point.CFrame
	point:Destroy()
end
MainPlatform.CFrame = PointsList[1]
local timing_div = Settings:GetAttribute("timing_div")
local EasingStyle = Settings:GetAttribute("EasingStyle")
local EasingDirection = Settings:GetAttribute("EasingDirection")

spawn(function()
	while runservice.RenderStepped:wait() and PP and PP:IsDescendantOf(game) do
		for _,next_point in pairs (PointsList) do
			local magnitude = (MainPlatform.Position-next_point.p).magnitude/timing_div
			local TweenInstance = tweenservice:Create(MainPlatform,TweenInfo.new(magnitude,Enum.EasingStyle[EasingStyle],Enum.EasingDirection[EasingDirection],0,false,0),{CFrame=next_point})
			TweenInstance:Play()
			TweenInstance.Completed:wait()
		end
	end
end)
return module
