--▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒--
--♦♥--MEMORY LIBRARY--♦♥--
local INST 		= Instance.new
local NRAY 		= Ray.new
local RAPM		= RaycastParams.new
local PHYSIPRO 	= PhysicalProperties.new
local VE3 		= Vector3.new
local UDI2		= UDim2.new
local CFN 		= CFrame.new
local TWEEN_IN	= TweenInfo.new
local CFA 		= CFrame.Angles
local M_COS		= math.cos
local M_SIN		= math.sin
local M_RAD		= math.rad
local M_RAN 	= math.random
local M_FLOOR 	= math.floor
local M_SQRT 	= math.sqrt
local M_MA 		= math.max
local M_MI 		= math.min
local M_CL		= math.clamp
local M_ABS		= math.abs
local S_SUB 	= string.sub
local S_FND 	= string.find
local CO_CRE	= coroutine.create
local CO_RES	= coroutine.resume
local NUMSEQ	= NumberSequence.new
local TA_RE 	= table.remove
local TA_IN 	= table.insert
local TA_SO 	= table.sort
local COR_RGB 	= Color3.fromRGB
--♦♥--♦♥--♦♥--♦♥--♦♥--♦♥--
--▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒--

--██████████████████████████████████████
--█▄─█─▄██▀▄─██▄─▄███▄─██─▄█▄─▄▄─█─▄▄▄▄█
--██▄▀▄███─▀─███─██▀██─██─███─▄█▀█▄▄▄▄─█
--▀▀▀▄▀▀▀▄▄▀▄▄▀▄▄▄▄▄▀▀▄▄▄▄▀▀▄▄▄▄▄▀▄▄▄▄▄▀

local module = {}
local MD_ = _G._MD
local LOCAL_MD_ = require(script.Parent:FindFirstChild("__LIBRARY"))
local __Vals = LOCAL_MD_.__Vals
--████████████████
local Player = _G.Player
local Character = script.Parent.Parent
--████████████████
local Humanoid = Character:FindFirstChild("Humanoid")
local Human_Root = Character:FindFirstChild("HumanoidRootPart")
local Human_Torso = Character:FindFirstChild("Torso")
local Human_TorsoLower = Character:FindFirstChild("TorsoLower")
--████████████████
local particle_throw = Human_Torso:FindFirstChild("particle_throw")
local particle_roll = Human_Torso:FindFirstChild("particle_roll")
local particle_stars = Human_Torso:FindFirstChild("particle_stars")
--████████████████
local Motor_Root = Human_Root:FindFirstChild("Root")
--████████████████

local camera_connections,last_connections = {},{}

local sound_play_list={
	["Whoosh_1"]=function()
		MD_.FF:PlaySound(Human_Root,"Other_Whoosh_1",{PlayOnRemove=true;PlaybackSpeed=M_RAN(1250,1750)/1000})
	end,
}

local not_empty__switch = function (...) return MD_.FF:not_empty__switch(...) end
local check__switch = function (...) return MD_.FF:check__switch(...) end

-- Ray Params save

local RayParams = RAPM()
RayParams.FilterType = Enum.RaycastFilterType.Blacklist
RayParams.FilterDescendantsInstances = {Character}

--█████████████████████████████████████████████████████████████████
--█▄─▄▄─█▄─▄▄▀█▄─▄▄─█▄─▄▄─███─▄▄▄─██▀▄─██▄─▀█▀─▄█▄─▄▄─█▄─▄▄▀██▀▄─██
--██─▄████─▄─▄██─▄█▀██─▄█▀███─███▀██─▀─███─█▄█─███─▄█▀██─▄─▄██─▀─██
--▀▄▄▄▀▀▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄▀▄▄▀▄▄▄▀▄▄▄▀▄▄▄▄▄▀▄▄▀▄▄▀▄▄▀▄▄▀

function module:Update_Free_Camera()
	module:FirstPerson("OFF")
	if not_empty__switch(LOCAL_MD_.Meta_Elements.Free_Camera.LockSwitch) and not not_empty__switch(LOCAL_MD_.Meta_Elements.Anti_Free_Camera.LockSwitch) then	
		
		if not __Vals.Free_Mode_Activated then
			__Vals.Free_Mode_Activated = true _G.__VFREE = true
			---
			local rotation_offset = CFA(0,0,0)
			local rotation_z = CFA(0,0,0)
			local position = workspace.CurrentCamera.CFrame
			local Camera = workspace.CurrentCamera
			
			local nVec = {
				[Enum.KeyCode.A] = function() return -Camera.CFrame.RightVector end,
				[Enum.KeyCode.D] = function() return Camera.CFrame.RightVector end,
				[Enum.KeyCode.S] = function() return -Camera.CFrame.LookVector end,
				[Enum.KeyCode.W] = function() return Camera.CFrame.LookVector end,
				[Enum.KeyCode.Q] = function() return -Camera.CFrame.UpVector end,
				[Enum.KeyCode.E] = function() return Camera.CFrame.UpVector end
			}
			workspace.CurrentCamera.CameraType = Enum.CameraType.Scriptable
			workspace.CurrentCamera.CameraSubject = nil

			local UISTable,Vec = {},{}
			
			local tick_changed 
			local max_speed = .5
			local speed = max_speed

			function UISTable.InputBegan(input)
				if nVec[input.KeyCode] then
					Vec[input.KeyCode] = nVec[input.KeyCode]
				elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
					tick_changed = true
					_Services.UserInput.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
				elseif input.KeyCode == Enum.KeyCode.LeftShift then
					speed = 0.07
				end
			end
			
			local function Limit_vector_y(vector,min,max)
				local _view = CFN(VE3(),vector)
				local rX, rY, rZ = _view:ToOrientation()
				local limX = M_CL(math.deg(rX),min,max)
				local new_vector = CFN(_view.p) * CFrame.fromOrientation(M_RAD(limX), rY, rZ)
				return new_vector.LookVector
			end
			
			function UISTable.InputChanged(input,g)
				if not _Services.UserInput:GetFocusedTextBox() and not g then
					if input.UserInputType == Enum.UserInputType.MouseMovement then
						local YRR = M_RAD(5)+M_COS(M_ABS(Camera.CFrame.LookVector.Y*(math.pi/2.1)))
						rotation_offset = rotation_offset:Lerp(CFrame.Angles(0, (math.rad(-input.Delta.X)*.85)*YRR, 0) * CFrame.Angles(-math.rad(input.Delta.Y)*.85, 0, 0),.2)
					elseif input.UserInputType == Enum.UserInputType.MouseWheel then
						position += Camera.CFrame.lookVector * (5*input.Position.Z)
					end
				end
			end

			function UISTable.InputEnded(input)
				if nVec[input.KeyCode] then
					Vec[input.KeyCode] = nil
				elseif input.UserInputType == Enum.UserInputType.MouseButton2 then		
					_Services.UserInput.MouseBehavior = Enum.MouseBehavior.Default
					tick_changed = nil
				elseif input.KeyCode == Enum.KeyCode.LeftShift then
					speed = max_speed
				end
			end

			for k, fn in pairs(UISTable) do
				TA_IN(last_connections,_Services.UserInput[k]:Connect(fn))
			end
			
			local current_position = position
			
			local function DefaultCam(dt)
				if not _Services.UserInput:GetFocusedTextBox() then
					--position
					local plus = VE3() for _, v in pairs(Vec) do plus += v()*speed end position += (plus)
					current_position = current_position:Lerp(position,.1)
					--look
					local LookCamera = CFN(workspace.CurrentCamera.CFrame.p,workspace.CurrentCamera.CFrame.p+(workspace.CurrentCamera.CFrame.LookVector*555))*rotation_offset
					
					if not tick_changed then
						rotation_z = rotation_z:Lerp(CFA(0,0,M_RAD(LOCAL_MD_.Z_ANGLE)),.1)
					else
						rotation_z = rotation_z:Lerp(CFA(0,0,0),.1)
					end
					workspace.CurrentCamera.CFrame = CFN (current_position.p,current_position.p+(Limit_vector_y(LookCamera.lookVector,-80,80) *255)) *rotation_z
					--set
					rotation_offset = rotation_offset:Lerp(CFA(0,0,0),.17)
				end
			end
			
			_Services.Run:BindToRenderStep("Step_Render_Camera", Enum.RenderPriority.Camera.Value, DefaultCam)
		end	
	elseif __Vals.Free_Mode_Activated then
		__Vals.Free_Mode_Activated = false _G.__VFREE = false
		_Services.Run:UnbindFromRenderStep("Step_Render_Camera")
		for i,v in pairs(camera_connections) do v:Disconnect() v=nil end
		for i,v in pairs(last_connections) do v:Disconnect() v=nil end
		_Services.UserInput.MouseBehavior = Enum.MouseBehavior.Default
		workspace.CurrentCamera.CameraSubject = LOCAL_MD_.CameraPart
		workspace.CurrentCamera.CameraType = Enum.CameraType.Custom
	end
end 

--█████████████████████████████▀█████████████████████████████████████████████████████
--█▄─▄─▀█▄─▄▄─█▄─▄█▄─▀█▄─▄█─▄▄▄▄███▄─▄█▄─▀█▄─▄█▄─█─▄█▄─▄█─▄▄▄▄█▄─▄█▄─▄─▀█▄─▄███▄─▄▄─█
--██─▄─▀██─▄█▀██─███─█▄▀─██─██▄─████─███─█▄▀─███▄▀▄███─██▄▄▄▄─██─███─▄─▀██─██▀██─▄█▀█
--▀▄▄▄▄▀▀▄▄▄▄▄▀▄▄▄▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀▀▀▄▄▄▀▄▄▄▀▀▄▄▀▀▀▄▀▀▀▄▄▄▀▄▄▄▄▄▀▄▄▄▀▄▄▄▄▀▀▄▄▄▄▄▀▄▄▄▄▄▀

function module:Invisible_Anim()
	Human_Root.CFrame = CFN(Human_Root.CFrame.p)
	local CustomTag={Name="Invisible_Anim"}
	if not_empty__switch(LOCAL_MD_.Meta_Elements.Invisible_Anim.LockSwitch) then
		MD_.FAKE_PARTS_PLAYERS_TEMPORAL.Parent = _Services.Lighting
		Humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead,false)
		Motor_Root.Enabled = false
		Human_TorsoLower.Anchored = true
		Human_TorsoLower.CFrame = CFN(Human_TorsoLower.CFrame.p) + VE3(0,250,0)

		Humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead,false)
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag,NN=nil,FF=nil})
	else
		Human_TorsoLower.Anchored = false
		Motor_Root.Enabled = true
		MD_.FAKE_PARTS_PLAYERS_TEMPORAL.Parent = _Services.Workspace
		local CustomTag2={Name="Invisible_Anim" .. tick()}
		Humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead,true)
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag2,NN=nil,FF=nil})
		delay(.25,function() check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag2,NN=nil,FF=nil}) end)
		check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag,NN=nil,FF=nil})
	end
	for i,v in pairs(Character:GetDescendants()) do
		if v:IsA("BasePart") then
			v.Velocity = VE3()
		end
	end
end

--████████████████████████████████████████████████████████████████████
--█▄─▄▄─█▄─▄█▄─▄▄▀█─▄▄▄▄█─▄─▄─███▄─▄▄─█▄─▄▄─█▄─▄▄▀█─▄▄▄▄█─▄▄─█▄─▀█▄─▄█
--██─▄████─███─▄─▄█▄▄▄▄─███─██████─▄▄▄██─▄█▀██─▄─▄█▄▄▄▄─█─██─██─█▄▀─██
--▀▄▄▄▀▀▀▄▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▀▄▄▄▀▀▀▄▄▄▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀

function module:FirstPerson(types)

	if LOCAL_MD_.FirstPerson == "ON" and (types == "OFF" or types == "Both") then
		LOCAL_MD_.FirstPerson = "Null"
		Player.CameraMode = Enum.CameraMode.Classic
		check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.CharacterVisible,TS=LOCAL_MD_.Meta_Elements.FirstPerson,NN=nil,FF=nil})

		local CustomTag2 = {Name="FirstPerson" .. tick()}
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag2,NN=nil,FF=nil})
		delay(.5,function()
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag2,NN=nil,FF=nil})
		end)

		LOCAL_MD_.FF:Update_Character()
		LOCAL_MD_.FirstPerson = "OFF"
	elseif LOCAL_MD_.FirstPerson == "OFF" and (types == "ON" or types == "Both") and not not_empty__switch(LOCAL_MD_.Meta_Elements.FirstPerson.LockSwitch) then
		LOCAL_MD_.FirstPerson = "Null"
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.CharacterVisible,TS=LOCAL_MD_.Meta_Elements.FirstPerson,NN=nil,FF=nil})

		local CustomTag2 = {Name="FirstPerson" .. tick()}
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag2,NN=nil,FF=nil})
		delay(.5,function()
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Lock_Bounce_Toggle,TS=CustomTag2,NN=nil,FF=nil})
		end)

		Player.CameraMode = Enum.CameraMode.LockFirstPerson
		LOCAL_MD_.FF:Update_Character()
		LOCAL_MD_.FirstPerson = "ON"
	end
end 

