--Roll Floor
function module:FloorThrow()
	local Stamina_Return 
	-- required stamina events
	if LOCAL_MD_.StaminaAmount >= 10 then Stamina_Return = true else LOCAL_MD_.FF:Stamina_Required(10) end
	
	if Stamina_Return and not LOCAL_MD_.Anim_Config.States.Jumping and not LOCAL_MD_.Anim_Config.States.Falling and not __Vals.Body_FloorJump and not not_empty__switch(LOCAL_MD_.Meta_Elements.FloorThrowYourself.LockSwitch) and not not_empty__switch(LOCAL_MD_.Meta_Elements.Anchored_State.LockSwitch) then
		__Vals.Body_FloorJump=true
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Jumping,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Auto_Rotate,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Anim_Config,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN="Custom_Animation_Process",FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.SwordAttack,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.GunUsing,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.MMMAAAASSSVVV,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})	
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.NoHeadRotation,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Holding,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})

		spawn(function()
			local knocked_out,keep_movement,PartGyro,clone_particle_throw
			local CameraCF = Human_Root.CFrame

			do -- verify after making move
				local directions_for_raycast = {
					Forward={vector=CameraCF.lookVector*5};
					right={vector=(CameraCF.lookVector*5)+(CameraCF.rightVector*1.5)};
					left={vector=(CameraCF.lookVector*5)+(CameraCF.rightVector*-1.5)};
					right_2={vector=(CameraCF.lookVector*4)+(CameraCF.rightVector*2)};
					left_2={vector=(CameraCF.lookVector*4)+(CameraCF.rightVector*-2)};
				}

				for _,v in pairs (directions_for_raycast) do
				--	MD_.FF:fake_part_detail(COR_RGB(255, 238, 0),CFN(Human_Root.CFrame.p+v.vector),VE3(1,1,1),2)
					local RayCastResults=MD_.FF:CastUntilHitSimple(Human_Root.CFrame.p,Human_Root.CFrame.p+v.vector,RayParams)
					if RayCastResults and RayCastResults.Instance then
						knocked_out = true
						break
					end
				end
			end

			if not knocked_out then
				keep_movement = true
				Humanoid:ChangeState(Enum.HumanoidStateType.Physics)
				local Direction = (CameraCF.lookVector*85*VE3(1,0,1))
				Human_Root.Velocity = Direction
				LOCAL_MD_.Anim_Config:AllStopAnimation(.15)
				MD_.FF:PlaySound(Human_Root,"Player_FloorJump1",{PlayOnRemove=true})
				LOCAL_MD_.Anim_Config.Animations.RollAnim:Play()
				LOCAL_MD_.Anim_Config.Animations.RollAnim:AdjustSpeed(2)
				--
				clone_particle_throw = particle_throw:Clone()
				clone_particle_throw.Parent = workspace.Terrain
				clone_particle_throw.emitter.Enabled=true	
				local atan2 = math.atan2(CameraCF.lookVector.X,CameraCF.lookVector.Z)
				clone_particle_throw.WorldOrientation=VE3(0,math.deg(atan2),0)
				clone_particle_throw.WorldPosition=particle_throw.WorldPosition
				delay(.2,function()
					clone_particle_throw.emitter.Enabled=false
				end)
				_Services.Debris:AddItem(clone_particle_throw,3)
				--

				PartGyro= INST("Part",Character)
				PartGyro.CanCollide = false
				PartGyro.Size = VE3()
				PartGyro.Transparency=1
				PartGyro.CFrame=Human_Root.CFrame
				PartGyro.Name="__PartGyro"
				MD_.FF:Weld(PartGyro,Human_Root)

				local body_gyro = INST("BodyGyro",PartGyro)
				body_gyro.CFrame = CFN(Human_Root.CFrame.p,Human_Root.CFrame.p+(Direction*25))
				body_gyro.MaxTorque=VE3(1,1,1)*9999e99999
				body_gyro.D=100

				local time_roll = tick()+.35
				local time_after_forces = tick()+.1
				
				local directions_for_raycast = {
					Forward={vector=CameraCF.lookVector*4};
					right={vector=(CameraCF.lookVector*3.75)+(CameraCF.rightVector*1.5)};
					left={vector=(CameraCF.lookVector*3.75)+(CameraCF.rightVector*-1.5)};
				}

				spawn(function()
					while __Vals.Body_FloorJump and _Services.Run.RenderStepped:wait() do
						if clone_particle_throw and clone_particle_throw:IsDescendantOf(game) then
							clone_particle_throw.WorldPosition=particle_throw.WorldPosition
						end
						
						for _,v in pairs (directions_for_raycast) do
							local RayCastResults=MD_.FF:CastUntilHitSimple(Human_Root.CFrame.p,Human_Root.CFrame.p+v.vector,RayParams)
							--
							if RayCastResults and RayCastResults.Instance then
								knocked_out = true
								local customhitbox ={
									CFrame = Human_Root.CFrame+(CameraCF.lookVector*4);
									Size=VE3(5,2.5,3);
								}
								for i,v in pairs (MD_.FF:hitbox_detector(customhitbox,1,false)) do
									if not v:IsDescendantOf(Character) then
										if v:FindFirstChild("GetBackPointEntity") then
											v.GetBackPointEntity.Value.Value = true
										end
									end
								end
								break
							end
						end

						body_gyro.CFrame = body_gyro.CFrame:Lerp(CFN(Human_Root.CFrame.p,Human_Root.CFrame.p+(Human_Root.Velocity)),M_CL(LOCAL_MD_.Current_Force/1000,0,1))
					end
				end)

				__Vals.Throw_Jump_Bool=false
				repeat _Services.Run.RenderStepped:Wait() until (LOCAL_MD_.Current_Force < 40 and time_after_forces - tick() < 0) or time_roll - tick() < 0 or knocked_out or __Vals.Throw_Jump_Bool
			end
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Jumping,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Auto_Rotate,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Anim_Config,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN="Custom_Animation_Process",FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.SwordAttack,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.GunUsing,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.MMMAAAASSSVVV,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.NoHeadRotation,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})	
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Holding,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})	
			
			if keep_movement then

				LOCAL_MD_.Anim_Config.Animations.RollAnim:AdjustSpeed(0)
				LOCAL_MD_.Anim_Config.Animations.RollAnim:Stop(.25)
				LOCAL_MD_.Anim_Config:AllStopAnimation(0)
				LOCAL_MD_.Anim_Config:Restart_Current_Animation()
				if knocked_out then
					local custom_tag = {Name="Throwx81nbdska9k" .. tick()}
					check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS= custom_tag,NN=nil,FF=nil})
					check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Holding,TS= custom_tag,NN=nil,FF=nil})
					delay(.5,function()
						check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.ThrowYourself,TS= custom_tag,NN=nil,FF=nil})
						check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Holding,TS= custom_tag,NN=nil,FF=nil})
					end)
				end
				if (__Vals.Throw_Jump_Bool or knocked_out) then
					LOCAL_MD_.Anim_Config.Animations.RollAnim:Stop(0)
					if knocked_out then

						local clone_particle_stars = particle_stars:Clone()
						clone_particle_stars.Parent = workspace.Terrain
						clone_particle_stars.emitter.Enabled=true	
						clone_particle_stars.WorldPosition=particle_stars.WorldPosition
						delay(.2,function()
							clone_particle_stars.emitter.Enabled=false
						end)

						_Services.Debris:AddItem(clone_particle_stars,2)

						MD_.FF:PlaySound(Human_Root,"Player_Floor_KnockeOut",{PlayOnRemove=true})
						local custom_tag = {Name="Throwxdasdasda81nbdska9k" .. tick()}
						check__switch({BB=true,TM=LOCAL_MD_.Anim_Config,TS=custom_tag,NN="Custom_Animation_Process",FF=nil})
						LOCAL_MD_.Anim_Config:AllStopAnimation(0)
						local local_anim = __LA(Humanoid.Animator, LOCAL_MD_.Anim_Config.AnimationsFolder.RollKnockeAnim)
						local_anim:Play(.1)

						delay(.25,function() 
							local_anim:Stop(.4) 
							Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
							check__switch({BB=nil,TM=LOCAL_MD_.Anim_Config,TS=custom_tag,NN="Custom_Animation_Process",FF=nil})
							LOCAL_MD_.Anim_Config:Restart_Current_Animation()
						end)
						Human_Root.Velocity = (CameraCF.lookVector*-45)+VE3(0,25,0)
						if LOCAL_MD_.Facial_Config then
							LOCAL_MD_.Facial_Config:ChangeFaceStyle("Ragdoll",1)
						end
					else
						local clone_ = particle_roll:Clone()
						clone_.Parent = particle_roll.Parent
						clone_.Enabled=true	
						delay(.35,function()
							clone_.Enabled=false
						end)
						_Services.Debris:AddItem(clone_,3)
						LOCAL_MD_.FF:Jump_Action({alternative=true})
					end
					LOCAL_MD_.FF:Stamina_Removed(10)
				else
					__Vals.FreeLandedJump = true
					Humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
					LOCAL_MD_.FF:Stamina_Removed(5)
				end

				check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.FloorThrowYourself,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
				if PartGyro then PartGyro:Destroy() end

				delay((knocked_out and .5) or .35,function()
					check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.FloorThrowYourself,TS=LOCAL_MD_.Meta_Elements.FloorThrowYourself,NN=nil,FF=nil})
				end)
			end

			__Vals.Body_FloorJump=false
		end)
	end
end

--Mid air
function module:Throw()
	local Stamina_Return 
	-- required stamina events
	if LOCAL_MD_.StaminaAmount >= 15 then Stamina_Return = true else LOCAL_MD_.FF:Stamina_Required(15) end

	if Stamina_Return and (LOCAL_MD_.Anim_Config.States.Jumping or LOCAL_MD_.Anim_Config.States.Falling) and not __Vals.Body_LongJump and __Vals.Can_Throw_Yourself and not not_empty__switch(LOCAL_MD_.Meta_Elements.ThrowYourself.LockSwitch) and not not_empty__switch(LOCAL_MD_.Meta_Elements.Anchored_State.LockSwitch) then
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Jumping,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Auto_Rotate,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Anim_Config,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN="Custom_Animation_Process",FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.FloorThrowYourself,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.SwordAttack,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.GunUsing,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.MMMAAAASSSVVV,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.NoHeadRotation,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Holding,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
		__Vals.Body_LongJump = true
		spawn(function()

			local knocked_out,PartGyro,clone_particle_throw,body_gyro
			local CameraCF = Human_Root.CFrame
			local Direction = (CameraCF.lookVector*65*VE3(1,0,1))

			do -- verify after making move
				local directions_for_raycast = {
					Forward={vector=CameraCF.lookVector*5};
					right={vector=(CameraCF.lookVector*5)+(CameraCF.rightVector*2)};
					left={vector=(CameraCF.lookVector*5)+(CameraCF.rightVector*-2)};
					right_2={vector=(CameraCF.lookVector*4)+(CameraCF.rightVector*2.5)};
					left_2={vector=(CameraCF.lookVector*4)+(CameraCF.rightVector*-2.5)};
				}

				for _,v in pairs (directions_for_raycast) do
					--MD_.FF:fake_part_detail(COR_RGB(255, 238, 0),CFN(Human_Root.CFrame.p+v.vector),VE3(1,1,1),2)
					local RayCastResults=MD_.FF:CastUntilHitSimple(Human_Root.CFrame.p,Human_Root.CFrame.p+v.vector,RayParams)
					if RayCastResults and RayCastResults.Instance then
						--	MD_.FF:fake_part_detail(COR_RGB(255, 238, 0),CFN(RayCastResults.Position),VE3(1,1,1),2)
						knocked_out = true
						break
					end
				end
			end

			if not knocked_out then -- all movement
				Humanoid:ChangeState(Enum.HumanoidStateType.Physics)
				Human_Root.Velocity = Direction+VE3(0,25,0)
				LOCAL_MD_.Anim_Config:AllStopAnimation(.15)
				MD_.FF:PlaySound(Human_Root,"Player_Jump3",{PlayOnRemove=true})
				LOCAL_MD_.Anim_Config.Animations.AirDiveAnim:Play()

				--
				clone_particle_throw = particle_throw:Clone()
				clone_particle_throw.Parent = workspace.Terrain
				clone_particle_throw.emitter.Enabled=true	
				local atan2 = math.atan2(CameraCF.lookVector.X,CameraCF.lookVector.Z)
				clone_particle_throw.WorldOrientation=VE3(0,math.deg(atan2),0)
				delay(.2,function()
					clone_particle_throw.emitter.Enabled=false
				end)
				_Services.Debris:AddItem(clone_particle_throw,3)
				--

				PartGyro= INST("Part",Character)
				PartGyro.CanCollide = false
				PartGyro.Size = VE3()
				PartGyro.Transparency=1
				PartGyro.CFrame=Human_Root.CFrame
				PartGyro.Name="__PartGyro"
				MD_.FF:Weld(PartGyro,Human_Root)

				body_gyro = INST("BodyGyro",PartGyro)
				body_gyro.CFrame = CFN(Human_Root.CFrame.p,Human_Root.CFrame.p+(Direction*25))
				body_gyro.MaxTorque=VE3(1,1,1)*9999e99999
				body_gyro.D=100

				local directions_for_raycast = {
					Forward={vector=CameraCF.lookVector*4};
					right={vector=(CameraCF.lookVector*4)+(CameraCF.rightVector*1)};
					left={vector=(CameraCF.lookVector*4)+(CameraCF.rightVector*-1)};
					right_2={vector=(CameraCF.lookVector*3)+(CameraCF.rightVector*2)};
					left_2={vector=(CameraCF.lookVector*3)+(CameraCF.rightVector*-2)};
				}

				spawn(function()
					while __Vals.Body_LongJump and _Services.Run.RenderStepped:wait() do
						if clone_particle_throw and clone_particle_throw:IsDescendantOf(game) then
							clone_particle_throw.WorldPosition=particle_throw.WorldPosition
						end
						for _,v in pairs (directions_for_raycast) do
							local RayCastResults=MD_.FF:CastUntilHitSimple(Human_Root.CFrame.p,Human_Root.CFrame.p+v.vector,RayParams)
							if RayCastResults and RayCastResults.Instance then
								knocked_out = true
								break
							end
						end
						if body_gyro then
							Human_Root.Velocity = Human_Root.Velocity:Lerp(Direction.Unit,.01) 
							body_gyro.CFrame = body_gyro.CFrame:Lerp(CFN(Human_Root.CFrame.p,Human_Root.CFrame.p+(Human_Root.Velocity)),M_CL(LOCAL_MD_.Current_Force/1000,0,1)) 
						end
					end
				end)
			end

			__Vals.Throw_Jump_Bool=false

			repeat wait() until LOCAL_MD_.Current_Force < 20 or __Vals.Throw_Jump_Bool or knocked_out
			--
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Jumping,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Auto_Rotate,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Anim_Config,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN="Custom_Animation_Process",FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.FloorThrowYourself,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.SwordAttack,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.GunUsing,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.MMMAAAASSSVVV,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.NoHeadRotation,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Holding,TS=LOCAL_MD_.Meta_Elements.ThrowYourself,NN=nil,FF=nil})
			
			LOCAL_MD_.Anim_Config.Animations.AirDiveAnim:Stop()
			LOCAL_MD_.Anim_Config:AllStopAnimation(0)
			LOCAL_MD_.Anim_Config:Restart_Current_Animation()
			--
			if (__Vals.Throw_Jump_Bool or knocked_out) then
				if knocked_out and __Vals.Can_Throw_Yourself_Knocked_Out then
					LOCAL_MD_.Anim_Config.Animations.AirDiveAnim:Stop(0)
					LOCAL_MD_.FF:Jump_Action({back=true})
				else
					LOCAL_MD_.FF:Jump_Action({double=true})
				end
				LOCAL_MD_.FF:Stamina_Removed(15)
			else
				LOCAL_MD_.FF:Stamina_Removed(10)
				Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
			end

			if knocked_out and __Vals.Can_Throw_Yourself_Knocked_Out then
				__Vals.Can_Throw_Yourself_Knocked_Out=false
			else
				__Vals.Can_Throw_Yourself=false
			end
			if PartGyro then PartGyro:Destroy() end
			__Vals.Body_LongJump=false
		end)
	end
end

return module
]=]
