function module:CheckHealth()
	--invisible for all hearts
	for i,v in pairs (__PC_health_bar:GetChildren()) do
		if v.Name == "Heart" then
			v.Visible = false
		end
	end
	--visible for the rest of the hearts
	local enough_hearts = LOCAL_MD_.Health
	for i,v in pairs (__PC_health_bar:GetChildren()) do
		if v.Name == "Heart" and enough_hearts > 0 then
			enough_hearts -= 1
			v.Visible = true
		end
	end
	local OldHealthBarSize = SUIP[__PC_health_bar].Size
	if LOCAL_MD_.OldHealth > LOCAL_MD_.Health then
		MD_.FF:PlaySound(Human_Root,"UI_LostHeart",{PlayOnRemove=true})
		__PC_health_bar.Size = UDI2(OldHealthBarSize.X.Scale*1.5,0,OldHealthBarSize.Y.Scale*1.5,0)
		_Services.Tween:Create(__PC_health_bar,TWEEN_IN(.5,Tween_Styles.Quad,Tween_Directions.Out,0,false,0),{Size=OldHealthBarSize}):play() 
	end
	LOCAL_MD_.OldHealth = LOCAL_MD_.Health

	LOCAL_MD_.FF:Change_Appearance()
end

