function module:Viewport_Frame_Player_Top(__SKIN,__CLOTH,__CHARISMA)
	local ViewPortFrame = __PC_PLAYER_FACE
	ViewPortFrame:ClearAllChildren()
	local WorldMode = INST("WorldModel",ViewPortFrame)
	local Rig = _Services.RepliStorage.Characters.Rig:Clone()
	Rig.Parent = WorldMode
	Rig.HumanoidRootPart.Anchored=true
	
	local facial_expresion=MD_.FF:Dress_My_Character({SKIN_NAME=__SKIN;CHARACTER=Rig;CLOTH_TYPE=__CLOTH,CHARISMA=__CHARISMA,POTRAIT_MODE=true})

	local AnimName = "DISPLAY_" .. __CLOTH
	local track = LOCAL_MD_.Anim_Config.Animations[AnimName]
	local anim = __LA(Rig.Humanoid.Animator, track.Animation) anim:play(0)
	local Camera = INST("Camera",ViewPortFrame) Camera.FieldOfView=5
	Rig.HumanoidRootPart.CFrame=CFN(0,250,0)
	
	local HAEAA = Rig.HumanoidRootPart
	if __CLOTH == "Cloth" then
		Camera.CFrame = CFN(HAEAA.CFrame.p+(HAEAA.CFrame.LookVector*47)+(HAEAA.CFrame.RightVector*15)+(HAEAA.CFrame.UpVector*10),HAEAA.CFrame.p) * CFrame.new(.25,1.15,0)
	elseif __CLOTH == "Naked_1" then
		Camera.CFrame = CFN(HAEAA.CFrame.p+(HAEAA.CFrame.LookVector*40)+(HAEAA.CFrame.RightVector*20)+(HAEAA.CFrame.UpVector*5),HAEAA.CFrame.p) * CFrame.new(.45,1.15,0)
	else
		Camera.CFrame = CFN(HAEAA.CFrame.p+(HAEAA.CFrame.LookVector*40)+(HAEAA.CFrame.RightVector*20)+(HAEAA.CFrame.UpVector*5),HAEAA.CFrame.p) * CFrame.new(.75,1.15,0)
	end
	
	local cf = CFrame.new(HAEAA.Position+(HAEAA.CFrame.LookVector*40)+(HAEAA.CFrame.RightVector*20)+(HAEAA.CFrame.UpVector*42),HAEAA.Position)
	ViewPortFrame.LightDirection = cf.LookVector
	ViewPortFrame.CurrentCamera = Camera
end

function module:Viewport_Frame_Player(ViewPortFrame,__SKIN,__CLOTH,__CHARISMA,___CAM_HEAD,___CAM_SIDE)
	ViewPortFrame:ClearAllChildren()
	local WorldMode = INST("WorldModel",ViewPortFrame)
	local Rig = _Services.RepliStorage.Characters.Rig:Clone()
	Rig.Parent = WorldMode
	Rig.HumanoidRootPart.Anchored=true
	Rig.HumanoidRootPart.CFrame=CFN(0,250,0)
	
	if __SKIN ~= "Simple" then
		local facial_expresion=MD_.FF:Dress_My_Character({SKIN_NAME=__SKIN;CHARACTER=Rig;CLOTH_TYPE=__CLOTH,POTRAIT_MODE=true})
	else
		for i,v in pairs (Rig:GetDescendants()) do
			if v:IsA("BasePart") and v.Name ~= "HumanoidRootPart" then
				v.Transparency=0
			end
		end
	end
	local Camera = INST("Camera",ViewPortFrame) Camera.FieldOfView=15
	ViewPortFrame.CurrentCamera = Camera

	local HAEAA = Rig.Head
	if ___CAM_HEAD then
		Camera.FieldOfView=10
		if ___CAM_SIDE then
			Camera.CFrame = CFN(HAEAA.CFrame.p+(HAEAA.CFrame.LookVector*10)+(HAEAA.CFrame.RightVector*-5)+(HAEAA.CFrame.UpVector*1),HAEAA.CFrame.p) 
		else
			Camera.CFrame = CFN(HAEAA.CFrame.p+(HAEAA.CFrame.LookVector*10)+(HAEAA.CFrame.RightVector*5)+(HAEAA.CFrame.UpVector*1),HAEAA.CFrame.p) 
		end			
	else
		Camera.CFrame = CFN(HAEAA.CFrame.p+(HAEAA.CFrame.LookVector*15)+(HAEAA.CFrame.RightVector*5)+(HAEAA.CFrame.UpVector*5),HAEAA.CFrame.p) +(HAEAA.CFrame.UpVector*-1)
	end
	
	ViewPortFrame.LightDirection = Camera.CFrame.LookVector
end

