-- setup animated hover UI
function module:animated_hover(...)	return MD_.FF:animated_hover(...) end

-- show amount stamina u need in UI
function module:Stamina_Required(amount)
	local warning_stamina = script.warning_stamina:Clone()
	warning_stamina.Parent = stamina_bar.ui_base
	warning_stamina.ZIndex = stamina_bar.ui_base.bar.ZIndex+1
	warning_stamina.Size =  UDI2(amount/LOCAL_MD_.StaminaAmountMax,0,1,0)
	_Services.Tween:Create(warning_stamina,TWEEN_IN(1,Tween_Styles.Sine,Tween_Directions.Out,0,false,0),{BackgroundTransparency=1}):play()
	_Services.Debris:AddItem(warning_stamina,1)
end

-- remove stamina amount u set with the UI
function module:Stamina_Removed(amount)
	if not MD_.WaveMode then return end
	local removed_stamina = script.removed_stamina:Clone()
	removed_stamina.Parent = stamina_bar.ui_base
	removed_stamina.ZIndex = stamina_bar.ui_base.bar.ZIndex-1
	removed_stamina.Size =  UDI2((LOCAL_MD_.StaminaAmount)/LOCAL_MD_.StaminaAmountMax,0,1,0)
	_Services.Tween:Create(removed_stamina,TWEEN_IN(.5,Tween_Styles.Sine,Tween_Directions.Out,0,false,0),{BackgroundTransparency=1}):play()
	_Services.Debris:AddItem(removed_stamina,.5)
	LOCAL_MD_.StaminaAmount-=amount
end

-- switch weapon with UI detail
function module:SwitchWeaponUI()
	__PC_CurrentWeapon_Melee.Visible = (LOCAL_MD_.Current_Weapon == "Melee")
	__PC_CurrentWeapon_Gun.Visible = (LOCAL_MD_.Current_Weapon == "Gun")
	local function button_effect_click_2(button)
		local oldsize = SUIP[button].Size
		button.Size=UDI2(button.Size.X.Scale/10,0,button.Size.Y.Scale/10,0)
		_Services.Tween:Create(button,TWEEN_IN(.5,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{Size=oldsize}):play()
	end
	button_effect_click_2(__PC_CurrentWeapon)
end module:SwitchWeaponUI()

