-- Create Bar slide System
function CreateBarOption(Frame,C)
	spawn(function()
		local C = C or {}

		local Mouse= __VMOUSE()
		local MyValue = C.MyValue 
		local MaxValue = C.Max or 1
		local MinValue = (C.Min) or 0
		local MaxValue_Edited = MaxValue- MinValue

		local BarContent = Frame:FindFirstChild("BarContent")
		local ScrollPoint = BarContent:FindFirstChild("ScrollPoint")
		local Least_UI = BarContent:FindFirstChild("Least")
		local Max_UI = BarContent:FindFirstChild("Max")
		local Count_UI = Frame:FindFirstChild("Count")

		local mouseHeld = false
		local fineTune = 0.05
		local changed,changed_SCREEN

		local Current_Value = MyValue
	
		ScrollPoint.Position = UDI2(Current_Value,0, .5, 0) 
		local CurrentConnections = {}

		--Update Text

		local function UpdateBar()
			local maxDistance = (Max_UI.AbsolutePosition.X / Camera.ViewportSize.X) - (Least_UI.AbsolutePosition.X / Camera.ViewportSize.X)
			local distance = (Max_UI.AbsolutePosition.X / Camera.ViewportSize.X) - (ScrollPoint.AbsolutePosition.X / Camera.ViewportSize.X)
			local finalDistance = (1 - (distance / maxDistance))+fineTune
			Current_Value = finalDistance
			Count_UI.Text = M_CL(M_FLOOR((Current_Value)*MaxValue_Edited)+MinValue,MinValue,MaxValue)
			if C.UpdateFunction then
				C.UpdateFunction(Current_Value,tonumber(Count_UI.Text))
			end
		end UpdateBar()
		
		if C.UpdateFunction then
			C.UpdateFunction(Current_Value,tonumber(Count_UI.Text))
		end
		
		--Update Pos (screen change or first time)

		local function Update_Point()
			spawn(function()
				if not changed_SCREEN then
					changed_SCREEN = tick() + .1
					repeat wait() UpdateBar() until changed_SCREEN and changed_SCREEN - tick() < 0
					changed_SCREEN = nil
					UpdateBar()
					ScrollPoint.Position = UDI2(Current_Value,0, .5, 0) 
				elseif changed_SCREEN then
					changed_SCREEN=tick()+.05
				end
			end)
		end 

		Update_Point()

		--Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
			--Update_Point()
		--end)

		LOCAL_MD_.FF:animated_hover("Ajust",ScrollPoint,{SFX="UI_Hover_001";condition_event=function() return not mouseHeld end})	

		local oldticksound 
		ScrollPoint.Boton.MouseButton1Down:Connect(function()
			if not mouseHeld then
				mouseHeld = true

				TA_IN(CurrentConnections,_Services.UserInput.InputEnded:Connect(function(input, gameProcessedEvent)
					if (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
						mouseHeld = false
						for i,v in pairs (CurrentConnections) do
							v:Disconnect()
						end
						CurrentConnections={}
					end
				end))

				if CurrentConnections.Move_Mouse then
					CurrentConnections.Move_Mouse:Disconnect()
					CurrentConnections.Move_Mouse=nil
				end

				local OldValue=Current_Value
				CurrentConnections.Move_Mouse =	Mouse.Move:Connect(function()
					if not oldticksound and OldValue ~= Current_Value then
						oldticksound = tick()+0.025
						MD_.FF:PlaySound(Frame,"UI_Snap",{PlayOnRemove=true})
					elseif oldticksound and oldticksound - tick() < 0 then
						oldticksound = nil
					end
					local Xm = Max_UI.AbsolutePosition.X
					local Xl = Least_UI.AbsolutePosition.X
					local next_udim =  UDI2(0, M_CL(Mouse.X,Xl,Xm )-(Xl), .5, 0)
					if C.tween_path then
						_Services.Tween:Create(ScrollPoint,TWEEN_IN(C.tween_path,Tween_Styles.Sine,Tween_Directions.Out,0,false,0),{Position=next_udim}):play()
						--ScrollPoint.Position = ScrollPoint.Position:Lerp(next_udim,C.tween_path) --  
					else
						ScrollPoint.Position = next_udim --  
					end
					Update_Point()
					OldValue=Current_Value
				end)
			end
		end)
	end)
end

