function UI_Settings_Setup()
	--████
	--████
	--████
	-- TOGGLES
	do
		local function button_effect_click_2(button)
			local oldsize = SUIP[button].Size
			button.Size=oldsize-UDI2(button.Size.X.Scale/1.5,0,button.Size.Y.Scale/1.5,0)
			_Services.Tween:Create(button,TWEEN_IN(.25,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{Size=oldsize}):play()
		end
		
		local function CreateButton(C)
			local Button,Condition,UpdateFunc = C.Button,C.Condition,C.UpdateFunc
			Save_UI_PROPIERTIES(SUIP,Button)
			module:animated_hover("Style_1",Button,{SFX="UI_Hover_001"})	
			local function UpdateUI() Button.BackgroundColor3 = (Condition() and COR_RGB(17, 255, 0)) or COR_RGB(255, 0, 4) end UpdateUI()
			Button.MouseButton1Click:connect(function() button_effect_click_2(Button) MD_.FF:PlaySound(Button,"UI_Button_009",{PlayOnRemove=true}) UpdateFunc() UpdateUI() end)
		end

		--CUM DETAIL
		do
			CreateButton({
				Button = __PCSETTINGSCC_values_2:FindFirstChild("Toggle_CumDe"):FindFirstChild("Button") ;
				Condition = function() return MD_.CUM_DETAILED end;
				UpdateFunc = function()
					MD_.CUM_DETAILED = not MD_.CUM_DETAILED
				end,
			})
		end
		--FACE ANIAMTIONS
		do
			CreateButton({
				Button = __PCSETTINGSCC_values_2:FindFirstChild("Toggle_Fac"):FindFirstChild("Button") ;
				Condition = function() return MD_.FACE_ANIMATED end;
				UpdateFunc = function()
					MD_.FACE_ANIMATED = not MD_.FACE_ANIMATED
				end,
			})
		end
		--MUTE BUTTON
		do
			CreateButton({
				Button = __PCSETTINGSCC_values_1:FindFirstChild("Toggle_Mute"):FindFirstChild("Button") ;
				Condition = function() return not not_empty__switch(MD_.Meta_Elements.MUSIC_UnAVAILABLE.LockSwitch) end;
				UpdateFunc = function()
					if not_empty__switch(MD_.Meta_Elements.MUSIC_UnAVAILABLE.LockSwitch) then
						check__switch({BB=nil,TM=MD_.Meta_Elements.MUSIC_UnAVAILABLE,TS=MD_.Meta_Elements.MUSIC_UnAVAILABLE,NN=nil,FF=nil}) 
					else
						check__switch({BB=true,TM=MD_.Meta_Elements.MUSIC_UnAVAILABLE,TS=MD_.Meta_Elements.MUSIC_UnAVAILABLE,NN=nil,FF=nil}) 
					end
				end,
			})
		end
		--
	end
	--████
	--████
	--████
end

