function UI_Admin_Setup()
	--████
	--████
	--████
	-- SPAWN LIST
	for _,v in pairs (MD_.AI_CONFIG) do
		local slot_mob = script._spawn_slot:Clone()
		slot_mob.Parent = __PCADMINCC_SpawnlistScrolling
		local slot_content= slot_mob.slot_content
		local RespawnButton = slot_content.toggle
