			button_effect_click_2(RespawnButton)
			MD_.FF:PlaySound(RespawnButton,"UI_AI_RESPAWN",{PlayOnRemove=true})
			_G.Remotes_ClientEvent:Fire("CreateNewEntity",v.REAL_Name,Human_Root.CFrame+(Human_Root.CFrame.lookVector*5))
		end)
	end
	TA_IN(to_grid_list,{UiGridLayout=__PCADMINCC_SpawnlistScrolling.UiGridLayout;frame_scroll=__PCADMINCC_SpawnlistScrolling;X=.9;Y=.25,Y_padding=0,X_padding=0}) 
