		--ORGY_MODE
		local TO_Orgy = __PCADMINCC_values_1:FindFirstChild("Toggle_Orgy") Save_UI_PROPIERTIES(SUIP,TO_Orgy) module:animated_hover("Style_1",TO_Orgy,{SFX="UI_Hover_001"})	
		local function Update_Orgy() TO_Orgy.BackgroundColor3 = (MD_.ORGY_MODE and COR_RGB(17, 255, 0)) or COR_RGB(255, 0, 4) end Update_Orgy()
		TO_Orgy.MouseButton1Click:connect(function()
			button_effect_click_2(TO_Orgy)
			MD_.FF:PlaySound(TO_Orgy,"UI_Button_009",{PlayOnRemove=true})
			MD_.ORGY_MODE = not MD_.ORGY_MODE
			Update_Orgy()
		end)
		--
	end
	--████
	--████
	--████
end

--███████████████████████████████████████████████████████
--█─▄▄▄▄█─█─█─▄▄─█▄─▄▄─███─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─█
--█▄▄▄▄─█─▄─█─██─██─▄▄▄███▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄█
--▀▄▄▄▄▄▀▄▀▄▀▄▄▄▄▀▄▄▄▀▀▀▀▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀

function UI_Shop_Setup()
	local CATALOG_FRAMES_TABLE,Current_CATALOG_FRAME={},nil
	for i,v in pairs (MD_.Objects_Catalog) do
		local BUTTON_NAME = v.BUTTON_NAME
		local Current_Item_Info
		local GetButtonBy =__PCS_Buttons:FindFirstChild(BUTTON_NAME):FindFirstChild("Content")
		Save_UI_PROPIERTIES(SUIP,GetButtonBy)
		module:animated_hover("Style_1",GetButtonBy,{SFX="UI_Hover_001"})	
		--████████████
		--MAKES THE CATALOG FRAME
		local CATALOG_FRAME = script:WaitForChild("SHOP_PAGE"):Clone()
		CATALOG_FRAME.Visible = false
		CATALOG_FRAME.Parent = __PC_shop_frame
		CATALOG_FRAME.Name = i .. "___CATALOG_FRAME"
		Save_UI_PROPIERTIES(SUIP,CATALOG_FRAME)
		--INFO ST
		local CATALOG_INFO_ITEM 
		if v.Type == "Melee" then
			CATALOG_INFO_ITEM = script:WaitForChild("slot_content_melee"):Clone()
		elseif v.Type == "Guns" then
			CATALOG_INFO_ITEM = script:WaitForChild("slot_content_guns"):Clone()
		elseif v.Type == "Units" then
			CATALOG_INFO_ITEM = script:WaitForChild("slot_content_units"):Clone()
		end
		CATALOG_INFO_ITEM.Parent = CATALOG_FRAME:FindFirstChild("Info")
		--
		local info_exit = CATALOG_INFO_ITEM:WaitForChild("exit")
		local info_viewportdisplay = CATALOG_INFO_ITEM:FindFirstChild("OBJECT_DISPLAY")
		local info_object_cost = CATALOG_INFO_ITEM:FindFirstChild("object_cost")
		local info_object_skill = CATALOG_INFO_ITEM:FindFirstChild("object_skill")
		local info_object_name = CATALOG_INFO_ITEM:FindFirstChild("object_name")
		local info_developer_name = CATALOG_INFO_ITEM:FindFirstChild("developer_name")
		local info_object_damage = CATALOG_INFO_ITEM:FindFirstChild("object_damage") and CATALOG_INFO_ITEM:FindFirstChild("object_damage"):FindFirstChild("amount")
		local info_object_stamina =  CATALOG_INFO_ITEM:FindFirstChild("object_stamina") and CATALOG_INFO_ITEM:FindFirstChild("object_stamina"):FindFirstChild("amount")
		local info_action = CATALOG_INFO_ITEM:FindFirstChild("action")
		module:animated_hover("Style_1",info_exit,{SFX="UI_Hover_001"})	
		--
		local CATALOG_scrolling = CATALOG_FRAME:FindFirstChild("scrolling")
		Save_UI_PROPIERTIES(SUIP,CATALOG_scrolling)
		if v.Type == "Units" then
			TA_IN(to_grid_list,{UiGridLayout=CATALOG_scrolling.UiGridLayout;frame_scroll=CATALOG_scrolling;X=.324;Y=.765,Y_padding=0.05,X_padding=0}) 
		else
			TA_IN(to_grid_list,{UiGridLayout=CATALOG_scrolling.UiGridLayout;frame_scroll=CATALOG_scrolling;X=.49;Y=.55,Y_padding=0.05,X_padding=0}) 
		end
		TA_IN(CATALOG_FRAMES_TABLE,CATALOG_FRAME)
		
		--████████████
		
		--VISIBLE CATALOG FUNCTION
		
		local function MAKE_CATALOG_VISIBLE(instant)
			Current_CATALOG_FRAME = CATALOG_FRAME
			for _,v in pairs (CATALOG_FRAMES_TABLE) do v.Visible = false end
			CATALOG_FRAME.Visible = true
			CATALOG_FRAME.Position = UDI2(0.5,0,1.5,0)
			_Services.Tween:Create(CATALOG_FRAME,TWEEN_IN((instant and 0.01) or .3,Tween_Styles.Sine,Tween_Directions.Out,0,false,0),{Position=SUIP[CATALOG_FRAME].Position}):play()
			_Services.Tween:Create(__PC_shop_frame,TWEEN_IN((instant and 0.01) or .75,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{BackgroundColor3=v.Color_Theme;BorderColor3=v.Color_Theme2}):play()
		end	if v.First then MAKE_CATALOG_VISIBLE(true) end
		
		--████████████
		
		--CONNECTIONS FOR click el coño de tu madre
		
		local function button_effect_click_2(button)
			local oldsize = SUIP[button].Size
			button.Size=oldsize-UDI2(button.Size.X.Scale/1.5,0,button.Size.Y.Scale/1.5,0)
			_Services.Tween:Create(button,TWEEN_IN(.25,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{Size=oldsize}):play()
		end
		
		GetButtonBy.MouseButton1Click:connect(function()
			if Current_CATALOG_FRAME ~= CATALOG_FRAME then
				MD_.FF:PlaySound(GetButtonBy,"UI_Button_008",{PlayOnRemove=true})
				button_effect_click_2(GetButtonBy)
				MAKE_CATALOG_VISIBLE()
			end
		end)
		
		--████████████
		
		local view_port_frame_process 

		if v.Type == "Units" then
			
			--█░█ █ █▀▀ █░█░█ █▀█ █▀█ █▀█ ▀█▀   █░█ █▄░█ █ ▀█▀
			--▀▄▀ █ ██▄ ▀▄▀▄▀ █▀▀ █▄█ █▀▄ ░█░   █▄█ █░▀█ █ ░█░
			
			view_port_frame_process = function(ViewPortFrame,item_info,st)
				local Object_Display = _Services.RepliStorage.Objects:FindFirstChild(v.FolderName):FindFirstChild(item_info.ObjectName):Clone()
				Object_Display.Parent = ViewPortFrame
				local ViewCamera = INST("Camera",ViewPortFrame)
				ViewPortFrame.CurrentCamera=ViewCamera
				ViewCamera.FieldOfView = 10
				local camera_part = Object_Display.Camera
				local LookAngleCF = CFN(VE3(),camera_part.CFrame.lookVector)*item_info.DisplayCF
				
				local Magnitude = item_info.Magnitude
				if st == "info" then Magnitude = item_info.Magnitude/2 end
				ViewCamera.CFrame = CFN(camera_part.CFrame.p+(LookAngleCF.lookVector*Magnitude),camera_part.CFrame.p)*item_info.Offset
			end
		else
	
			--█░█ █ █▀▀ █░█░█ █▀█ █▀█ █▀█ ▀█▀   █ ▀█▀ █▀▀ █▀▄▀█ █▀
			--▀▄▀ █ ██▄ ▀▄▀▄▀ █▀▀ █▄█ █▀▄ ░█░   █ ░█░ ██▄ █░▀░█ ▄█
			
			view_port_frame_process = function(ViewPortFrame,item_info)
				local Object_Display = _Services.RepliStorage.Objects:FindFirstChild(v.FolderName):FindFirstChild(item_info.ObjectName):Clone()
				local ViewCamera = INST("Camera",ViewPortFrame)
				ViewPortFrame.CurrentCamera=ViewCamera
				ViewCamera.FieldOfView = 10
				local WorldModel = INST("WorldModel",ViewPortFrame)
				Object_Display.Parent = WorldModel
				Object_Display.MainPart.Anchored = true
				Object_Display.MainPart.CFrame = CFN()
				if item_info.WorldViewMainCF then
					if workspace:FindFirstChild("CWorldViewMainCF_WEAPONS") then
						_Services.Run.RenderStepped:connect(function()
							Object_Display.MainPart.CFrame = workspace:FindFirstChild("CWorldViewMainCF_WEAPONS").Value
						end)
					end
					Object_Display.MainPart.CFrame = item_info.WorldViewMainCF
				end
				local Magnitude = item_info.Magnitude
				if workspace:FindFirstChild("CFRAME_DISPLAY_WEAPONS") then
					_Services.Run.RenderStepped:connect(function()
						local LookAngleCF = CFN(VE3(),Object_Display.MainPart.CFrame.lookVector)*workspace:FindFirstChild("CFRAME_DISPLAY_WEAPONS").Value
						ViewCamera.CFrame = CFN(Object_Display.MainPart.CFrame.p+(LookAngleCF.lookVector*Magnitude),Object_Display.MainPart.CFrame.p)*item_info.Offset
					end)
				else
					local LookAngleCF = CFN(VE3(),Object_Display.MainPart.CFrame.lookVector)*item_info.DisplayCF
					ViewCamera.CFrame = CFN(Object_Display.MainPart.CFrame.p+(LookAngleCF.lookVector*Magnitude),Object_Display.MainPart.CFrame.p)*item_info.Offset
				end
			end
		end
		
		--████████████
		local function show_info_item(item_info,detailed)
			Current_Item_Info = item_info
			if detailed then
				CATALOG_INFO_ITEM.Position=UDI2(1.5,0,.5,0)
				_Services.Tween:Create(CATALOG_INFO_ITEM,TWEEN_IN(.25,Tween_Styles.Quad,Tween_Directions.Out,0,false,0),{Position=UDI2(.5,0,.5,0)}):play()
				_Services.Tween:Create(CATALOG_scrolling,TWEEN_IN(.25,Tween_Styles.Quad,Tween_Directions.Out,0,false,0),{Size=SUIP[CATALOG_scrolling].Size+UDI2(-.4,0,0,0)}):play()
				info_viewportdisplay:ClearAllChildren()
				view_port_frame_process(info_viewportdisplay,item_info,"info")
			end

			info_object_name.Text = item_info.Display_Name
			info_developer_name.Text = item_info.Developer
			
			if info_object_damage then info_object_damage.Text = item_info.Damage end
			if info_object_stamina then info_object_stamina.Text = item_info.Stamina end	
			if info_object_skill then info_object_skill.amount.Text = item_info.Skill end
			
			if item_info.Cost == "Free" then
				info_object_cost.Text = item_info.Cost
			else
				info_object_cost.Text = item_info.Cost .. "$"
			end

			info_object_cost.Text = item_info.Cost .. "$"

			local Using_Current_OBJECT_TABLE = (v.Type == "Melee" and MD_.Current_Melee_Weapon) or (v.Type == "Guns" and MD_.Current_Gun_Weapon)

			if item_info.Own_Item and v.Type ~= "Units" then
				if Using_Current_OBJECT_TABLE == item_info.Item_Name then
					info_action.Text = "Equipped"
					info_action.BackgroundColor3=COR_RGB(169, 255, 10)
				else
					info_action.Text = "Equip"
					info_action.BackgroundColor3=COR_RGB(25, 213, 25)
				end
			else
				info_action.Text = "Buy"
				info_action.BackgroundColor3=COR_RGB(255, 136, 0)
			end
		end
		
		local function action_item()
			if Current_Item_Info then
				local OBJECT_TABLE_NAME = (v.Type == "Melee" and "Current_Melee_Weapon") or (v.Type == "Guns" and "Current_Gun_Weapon")
				if v.Type == "Units" then
					if not Current_Item_Info.Own_Item and MD_.Current_Money >= Current_Item_Info.Cost and MD_.WAVE_UNITS_COUNT < 20 then
						MD_.Current_Money-=Current_Item_Info.Cost
						MD_.FF:PlaySound(info_action,"UI_Buy",{PlayOnRemove=true})
						_G.Remotes_ClientEvent:Fire("CreateNewEntity","Human",Human_Root.CFrame+(Human_Root.CFrame.lookVector*5))
					else
						MD_.FF:PlaySound(info_action,"UI_Button_Error_001",{PlayOnRemove=true})
					end
				elseif OBJECT_TABLE_NAME then
					if not Current_Item_Info.Own_Item and MD_.Current_Money >= Current_Item_Info.Cost then
						MD_.Current_Money-=Current_Item_Info.Cost
						Current_Item_Info.Own_Item = true
						MD_.FF:PlaySound(info_action,"UI_Buy",{PlayOnRemove=true})
					elseif Current_Item_Info.Own_Item and  MD_.Current_Melee_Weapon ~= Current_Item_Info.Item_Name then
						MD_[OBJECT_TABLE_NAME] = Current_Item_Info.Item_Name
						MD_.FF:PlaySound(info_action,"UI_Equip",{PlayOnRemove=true})
					else
						MD_.FF:PlaySound(info_action,"UI_Button_Error_001",{PlayOnRemove=true})
					end
					show_info_item(Current_Item_Info)
					LOCAL_MD_.Restart_Sword_Back = true
				end
			end
		end

		local function hide_info_item()
			Current_Item_Info = nil
			info_viewportdisplay:ClearAllChildren()
			_Services.Tween:Create(CATALOG_INFO_ITEM,TWEEN_IN(.25,Tween_Styles.Quad,Tween_Directions.In,0,false,0),{Position=UDI2(1.5,0,.5,0)}):play()
			_Services.Tween:Create(CATALOG_scrolling,TWEEN_IN(.25,Tween_Styles.Quad,Tween_Directions.In,0,false,0),SUIP[CATALOG_scrolling]):play()
		end info_exit.MouseButton1Click:connect(function() MD_.FF:PlaySound(info_exit,"UI_Button_004",{PlayOnRemove=true}) hide_info_item() end)
		
		--████████████
		
		--MAKES THE LIST 
		
		for _,item_info in pairs (v.Items) do
			local SHOP_SLOT = script.SHOP_SLOT:Clone()
			SHOP_SLOT.LayoutOrder = item_info.Layout
			local slot_content = SHOP_SLOT.slot_content
			local ViewPortFrame = slot_content.OBJECT_DISPLAY
			module:animated_hover("Style_1",slot_content,{SFX="UI_Hover_002"})	
			SHOP_SLOT.Parent = CATALOG_scrolling

			slot_content.object_name.Text = item_info.Display_Name
			if item_info.Cost == "Free" then
				slot_content.object_cost.Text = item_info.Cost
			else
				slot_content.object_cost.Text = item_info.Cost .. "$"
			end
			--ViewPortFrame
			view_port_frame_process(ViewPortFrame,item_info)
			Save_UI_PROPIERTIES(SUIP,slot_content)
			slot_content.button.MouseButton1Click:connect(function()
				button_effect_click_2(slot_content)
				if Current_Item_Info ~= item_info then
					show_info_item(item_info,true)
					MD_.FF:PlaySound(slot_content,"UI_Button_002",{PlayOnRemove=true})
				else
					MD_.FF:PlaySound(slot_content,"UI_Button_Error_001",{PlayOnRemove=true})
				end
			end)
		end
		
		--████████████
		
		module:animated_hover("Style_1",info_action,{SFX="UI_Hover_002"})	

		Save_UI_PROPIERTIES(SUIP,info_action)
		
		info_action.MouseButton1Click:connect(function()
			button_effect_click_2(info_action)
			action_item()
		end)
		
		--████████████
	end
end

--██████████████████████████████████████████████████████████████████████████████
--█▄─▀█▀─▄█─▄▄─█▄─▀█▄─▄█▄─▄▄─█▄─█─▄███▄─▄▄─█▄─▄▄─█▄─▄▄─█▄─▄▄─█─▄▄▄─█─▄─▄─█─▄▄▄▄█
--██─█▄█─██─██─██─█▄▀─███─▄█▀██▄─▄█████─▄█▀██─▄████─▄████─▄█▀█─███▀███─███▄▄▄▄─█
--▀▄▄▄▀▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▀▄▄▄▄▄▀▄▄▄▀▀▀▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▄▄▄▄▄▀

function module:Money_Display(money,pos)
	local money_display = script.money_display:Clone()
	money_display.Parent = __MI_Money_amount.Parent
	money_display.Text = money .. "$"
	local MarkerAbsolute = money_display.AbsoluteSize
	local MarkerPosition, onScreen = Camera:WorldToScreenPoint(pos)
	local MarkerPositionX = MarkerPosition.X - MarkerAbsolute.X/2
	local MarkerPositionY = MarkerPosition.Y - MarkerAbsolute.Y/2
	money_display.Position = UDim2.fromOffset(MarkerPositionX,MarkerPositionY)
	
	money_display.Size = UDim2.new(0,0,0,0)
	_Services.Tween:Create(money_display,TWEEN_IN(.5,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{Size=UDim2.new(3,0,1.2,0)}):play()
	_Services.Debris:AddItem(money_display,3.5)
	MD_.FF:PlaySound(money_display,{"UI_Coins_001","UI_Coins_002","UI_Coins_003","UI_Coins_004"},{PlayOnRemove=true})
	
	delay(3,function()
		_Services.Tween:Create(money_display,TWEEN_IN(.5,Tween_Styles.Back,Tween_Directions.In,0,false,0),{Size=UDim2.new(0,0,0,0)}):play()
	end)
end

--██████████████████████████████████████████████████████████████
--█▄─█▀▀▀█─▄██▀▄─██▄─█─▄█▄─▄▄─███─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─█
--██─█─█─█─███─▀─███▄▀▄███─▄█▀███▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄█
--▀▀▄▄▄▀▄▄▄▀▀▄▄▀▄▄▀▀▀▄▀▀▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀

function UI_Wave_Setup()
	local Choosed_Map,Choosed_Difficulty
	local Started 
	local function Update_Start_Button()
		__WA__Start_Button.Avalible.Visible = not (Choosed_Map and Choosed_Difficulty and not Started)
	end Update_Start_Button()
	
	module:animated_hover("Style_1",__WA__Start_Button,{SFX="UI_Hover_001";condition_event=function() return (Choosed_Map and Choosed_Difficulty and not Started) end})	
	
	local function button_effect_click(button)
		local oldsize = SUIP[button].Size
		button.Size=oldsize+UDI2(button.Size.X.Scale/1.5,0,button.Size.Y.Scale/1.5,0)
		_Services.Tween:Create(button,TWEEN_IN(.25,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{Size=oldsize}):play()
	end
	
	local function update_current_map_show()
		if Choosed_Map then		
			_Services.Tween:Create(__WA__current_map,TWEEN_IN(.3,Tween_Styles.Quint,Tween_Directions.Out,0,false,0),{Position=SUIP[__WA__current_map].Position}):play()
		else
			local oldpos = SUIP[__WA__current_map].Position
			_Services.Tween:Create(__WA__current_map,TWEEN_IN(.3,Tween_Styles.Quad,Tween_Directions.In,0,false,0),{Position=oldpos+UDI2(0,0,-1.5,0)}):play()
		end
	end update_current_map_show()
	
	--█▀▄▀█ █▀▀█ █▀▀█ █▀▀ 
	--█─▀─█ █▄▄█ █──█ ▀▀█ 
	--▀───▀ ▀──▀ █▀▀▀ ▀▀▀
	
	local MapTABLE = {}
	-- setup icons and maps
	for _,map in pairs (_G.Modules_Maps) do
		local Map_Slot = script:FindFirstChild("MAP_SLOT"):Clone()
		Map_Slot.Parent = __WA__Scrolling
		Map_Slot.slot_content:FindFirstChild("TITTLE").Text = map.DisplayName
		Map_Slot.slot_content:FindFirstChild("ICON").Image = map.Icon
		table.insert(MapTABLE,{Info=map;UI=Map_Slot.slot_content})
	end
	
	local function update_button_map(EFFECT)
		for _,map in pairs (MapTABLE) do
			local Choosed = map.UI.Choosed
			Choosed.Visible = Choosed_Map == map.Info
			if EFFECT and Choosed.Visible then
				button_effect_click(Choosed)
				__WA__current_map.ICON.Image = map.UI.ICON.Image
				__WA__current_map.TITTLE.Text = map.UI.TITTLE.Text
				MD_.FF:PlaySound(__SC_Scene_Settings,"UI_Slide_1",{PlayOnRemove=true})
			end
		end
	end
	
	-- setup map ui function
	for _,map in pairs (MapTABLE) do
		local UI = map.UI
		Save_UI_PROPIERTIES(SUIP,UI.Choosed)
		Save_UI_PROPIERTIES(SUIP,UI)
		module:animated_hover("Style_1",UI,{SFX="UI_Hover_001"})	
		UI.Button.MouseButton1Click:connect(function()
			MD_.FF:PlaySound(__SC_Scene_Settings,"UI_Button_002",{PlayOnRemove=true})
			if Choosed_Map == map.Info then Choosed_Map = nil else Choosed_Map=map.Info end
			button_effect_click(UI)
			Update_Start_Button()
			update_button_map(true)
			update_current_map_show()
		end)
	end
	
	update_button_map()
	
	--█▀▀▄ ─▀─ █▀▀ █▀▀ ─▀─ █▀▀ █──█ █── ▀▀█▀▀ █──█ 
	--█──█ ▀█▀ █▀▀ █▀▀ ▀█▀ █── █──█ █── ──█── █▄▄█ 
	--▀▀▀─ ▀▀▀ ▀── ▀── ▀▀▀ ▀▀▀ ─▀▀▀ ▀▀▀ ──▀── ▄▄▄█
	
	local DifficultyTABLE = {{BUTTON=__WABU_Gentile};{BUTTON=__WABU_Rapist};{BUTTON=__WABU_Abuser};}
	
	local function update_button_difficulty(EFFECT)
		for _,difficulty in pairs (DifficultyTABLE) do
			local Button = difficulty.BUTTON
			Button.Choosed.Visible = Choosed_Difficulty == difficulty
			if EFFECT and Button.Choosed.Visible then
				button_effect_click(Button.Choosed)
			end
		end
	end
	
	for _,difficulty in pairs (DifficultyTABLE) do
		local Button = difficulty.BUTTON
		Save_UI_PROPIERTIES(SUIP,Button.Choosed)
		Save_UI_PROPIERTIES(SUIP,Button)
		module:animated_hover("Style_1",Button,{SFX="UI_Hover_001"})	
		Button.MouseButton1Click:connect(function()
			MD_.FF:PlaySound(__SC_Scene_Settings,"UI_Button_002",{PlayOnRemove=true})
			if Choosed_Difficulty == difficulty then Choosed_Difficulty = nil else Choosed_Difficulty=difficulty end
			button_effect_click(Button)
			Update_Start_Button()
			update_button_difficulty(true)
		end)
	end
	
	update_button_difficulty()
	
	--█▀▀ ▀▀█▀▀ █▀▀█ █▀▀█ ▀▀█▀▀ 
	--▀▀█ ──█── █▄▄█ █▄▄▀ ──█── 
	--▀▀▀ ──▀── ▀──▀ ▀─▀▀ ──▀──

	__WA__Start_Button.MouseButton1Click:connect(function()
		if (Choosed_Map and Choosed_Difficulty) and not Started then else return end  Started = true
		MD_.FF:PlaySound(__SC_Scene_Settings,"UI_Button_008",{PlayOnRemove=true})
		MD_.FF:PlaySound(__SC_Scene_Settings,"UI_StartWaveMode",{PlayOnRemove=true})
		local __ChooseMap__,__Choosed_Difficulty__ = Choosed_Map,Choosed_Difficulty
		button_effect_click(__WA__Start_Button)
		Update_Start_Button()
		LOCAL_MD_.FF:_h_i_d_e_s_t_a_t_e ()
		local Ab = __WA__Start_Button.AbsolutePosition
		local As = __WA__Start_Button.AbsoluteSize
		_____SPHERE_SCREEN.Position = UDim2.fromOffset(Ab.X+As.X/2,Ab.Y+As.Y/2)
		_____SPHERE_SCREEN.Size = UDI2(0,0,0,0)
		_____SPHERE_SCREEN.BackgroundColor3 = Color3.fromRGB(26, 61, 10)
		_____SPHERE_SCREEN.Visible = true
		__MIB_peace_button.Parent.Visible = false
		__MIB_admin_button.Parent.Visible = false
		check__switch({BB=true,TM=MD_.Meta_Elements.MUSIC_UnAVAILABLE,TS=MD_.Meta_Elements.WAVE_MODE,NN=nil,FF=nil}) 
		
		local tween = _Services.Tween:Create(_____SPHERE_SCREEN,TWEEN_IN(1.5,Tween_Styles.Linear,Tween_Directions.In,0,false,0),{Size=UDI2(6,0,6,0);BackgroundColor3 = Color3.fromRGB(0, 0, 0)})
		tween:play()
		tween.Completed:Wait()

		local function _short_screen()
			_____SPHERE_SCREEN.Position = UDim2.fromScale(.5,.5)
			local tween = _Services.Tween:Create(_____SPHERE_SCREEN,TWEEN_IN(1.5,Tween_Styles.Linear,Tween_Directions.In,0,false,0),{Size=UDI2(0,0,0,0)}) 
			tween:play()
			delay(1,function() MD_.FF:PlaySound(__SC_Scene_Settings,"UI_StartWaveMode2",{PlayOnRemove=true}) end)
			tween.Completed:Wait()
			_____SPHERE_SCREEN.Visible = false
		end
		
		_G.Remotes_ClientEvent:Fire("Start_Wave",__ChooseMap__,Character,__Choosed_Difficulty__,_short_screen)
	end)
	
	print("START WAVE MODE")
	spawn(function()
		wait(1)
