function module:Break_Scene_UI(STATUS,Scene_Config)
	if STATUS == "END" then
		_____Scene_Career.Visible = false
		for i,v in pairs (Scenes_Connections) do v:Disconnect() v=nil end Scenes_Connections={}
		for i,v in pairs (Scene_Instances) do v:Destroy() v=nil end Scene_Instances={}
		Save_CFrame_Camera = nil
		check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,TS=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
		check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Custom_FOV_Script,TS=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
	elseif STATUS == "START" then
		for i,v in pairs (Scenes_Connections) do v:Disconnect() v=nil end Scenes_Connections={}
		for i,v in pairs (Scene_Instances) do v:Destroy() v=nil end Scene_Instances={}
		_____Scene_Career.Visible = true
		if Save_CFrame_Camera then
			Camera.CFrame = Save_CFrame_Camera
			Save_CFrame_Camera = nil
		end
		check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,TS=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
		check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Custom_FOV_Script,TS=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
		
		local function SCENE_OFFSET_RETURN(cf) return cf+Vector3.new(LOCAL_MD_.SCENE_OFFSET_X,LOCAL_MD_.SCENE_OFFSET_Y,LOCAL_MD_.SCENE_OFFSET_Z) end
		local __LOCK__CFRAME,__FOCUS__POSITION,__VIBRATION__MODE
		local random1,random2 = M_RAN(),M_RAN()
		
		--- RAYCAST PARAMS ---
		
		local RayParams = RaycastParams.new()
		RayParams.FilterType = Enum.RaycastFilterType.Whitelist
		RayParams.FilterDescendantsInstances = {}

		local function _white_list_this(model)
			for _,part in pairs (model:GetChildren()) do
				if not part:IsA("BasePart") or part:GetAttribute("Ignore_RayCast_Value_For_Target_Scene") then continue end
				local Filtered = RayParams.FilterDescendantsInstances
				Filtered[#Filtered + 1] = part
				RayParams.FilterDescendantsInstances = Filtered
			end
		end

		for _,v in pairs (Scene_Config.Scene_Model:GetChildren()) do
			_white_list_this(v)
		end

		--- SCENE PREFERENCES ---

		local function button_effect_click_2(button)
			local oldsize = SUIP[button].Size
			button.Size=oldsize-UDI2(button.Size.X.Scale/1.5,0,button.Size.Y.Scale/1.5,0)
			_Services.Tween:Create(button,TWEEN_IN(.25,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{Size=oldsize}):play()
		end
		
		local function button_effect_click_3(button)
			local oldsize = SUIP[button].Size
			button.Size=oldsize-UDI2(button.Size.X.Scale/5,0,button.Size.Y.Scale/.8,0)
			_Services.Tween:Create(button,TWEEN_IN(.5,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),{Size=oldsize}):play()
		end
		
		--- SS_clean_button

		local function update_trash_acumulation()		
			__SC_SS_trash_acumulated.Text = #Scene_Config.Cum_Folder:GetDescendants()
		end update_trash_acumulation()	
		TA_IN(Scenes_Connections,Scene_Config.Cum_Folder.ChildAdded:connect(update_trash_acumulation))
		TA_IN(Scenes_Connections,Scene_Config.Cum_Folder.ChildRemoved:connect(update_trash_acumulation))
		TA_IN(Scenes_Connections,__SC_SS_clean_button.MouseButton1Click:connect(function()
			MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_002",{PlayOnRemove=true})
			button_effect_click_2(__SC_SS_clean_button)
			Scene_Config.Cum_Folder:ClearAllChildren()
		end))
		
		--- SS_loop_button
		__SC_SS_loop_button.Loop.Visible = true
		__SC_SS_loop_button.UnLoop.Visible = false

		TA_IN(Scenes_Connections,__SC_SS_loop_button.MouseButton1Click:connect(function()
			MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_002",{PlayOnRemove=true})
			button_effect_click_2(__SC_SS_loop_button)
			if Scene_Config.OnLoop then
				Scene_Config.OnLoop = false
				__SC_SS_loop_button.Loop.Visible = true
				__SC_SS_loop_button.UnLoop.Visible = false
			else
				Scene_Config.OnLoop = true
				__SC_SS_loop_button.Loop.Visible = false
				__SC_SS_loop_button.UnLoop.Visible = true
			end
		end))

		--- SS_pause_button
		__SC_SS_pause_button.Pause.Visible = true
		__SC_SS_pause_button.Play.Visible = false

		TA_IN(Scenes_Connections,__SC_SS_pause_button.MouseButton1Click:connect(function()
			MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_002",{PlayOnRemove=true})
			button_effect_click_2(__SC_SS_pause_button)
			if Scene_Config.Pause then
				Scene_Config.Pause = false
				__SC_SS_pause_button.Pause.Visible = true
				__SC_SS_pause_button.Play.Visible = false
			else
				Scene_Config.Pause = true
				__SC_SS_pause_button.Pause.Visible = false
				__SC_SS_pause_button.Play.Visible = true
			end
		end))
	
		--█▀▀█ █▀▀█ ▀█░█▀ 　 █░░ ░▀░ █▀▀ ▀▀█▀▀ 
		--█░░█ █░░█ ░█▄█░ 　 █░░ ▀█▀ ▀▀█ ░░█░░ 
		--█▀▀▀ ▀▀▀▀ ░░▀░░ 　 ▀▀▀ ▀▀▀ ▀▀▀ ░░▀░░
		
		local Head_Welds_List = {}
		local Atrrname = "HEAD_WELDER_CHECKQUE_FP_SCENE"
		local List_Entity_Available = {}
		local ChangedMode,ChangedChar
		local rotation_z = CFA(0,0,0)
		TA_IN(Scene_Instances,Scene_Config.Scene_Model)
		
		local function get_Head_from(models)
			for _,parts in pairs(models:GetDescendants()) do
				if parts:IsA("BasePart") and parts:GetAttribute("Part_Category") == "Head" then
					return parts
				end
			end
		end

		for _,models in pairs(Scene_Config.Scene_Model:GetChildren()) do
			if models:FindFirstChild("Entity_Name_User") then
				local Head = get_Head_from(models)
				TA_IN(List_Entity_Available,{EntityType= models:FindFirstChild("Entity_Name_User").Value,Character=models,Head=Head})
			end
		end

		local function get_my_character(botname)
			for i,v in pairs (List_Entity_Available) do
				if not v.InUse_POV and v.EntityType == botname then
					v.InUse_POV = true
					return v
				end
			end
		end

		local function Weld_Excelsios(Model_acc)
			if not Model_acc:GetAttribute(Atrrname) then
				Model_acc:SetAttribute(Atrrname,true) 
				TA_IN(Head_Welds_List,{Group=Model_acc,Parent=Model_acc.Parent})
				Model_acc.Parent = _Services.Lighting
			end
		end

		local function Reset_All_Head_Welds()
			for _,v in pairs(Head_Welds_List) do
				if v.Group:GetAttribute(Atrrname) then
					v.Group:SetAttribute(Atrrname,nil) 
					v.Group.Parent = v.Parent
				end
			end
			Head_Welds_List = {}
		end

		local function ChangeCamera(Mode,HisCharacter)
			if HisCharacter == ChangedChar and Mode == ChangedMode and Mode ~= "RESET" then 
				MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_CameraError",{PlayOnRemove=true})
				return 
			end
			if Scenes_Connections.LoopCameraCustom then Scenes_Connections.LoopCameraCustom:Disconnect() Scenes_Connections.LoopCameraCustom = nil end
			if Scenes_Connections.FP_Input_Changer then Scenes_Connections.FP_Input_Changer:Disconnect() Scenes_Connections.FP_Input_Changer = nil end
			if not Save_CFrame_Camera then Save_CFrame_Camera = Camera.CFrame end
			Reset_All_Head_Welds()
			if Mode=="RESET" and (ChangedChar or ChangedMode) then
				ChangedChar,ChangedMode = nil,nil
				MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_CameraReset",{PlayOnRemove=true})
				if Save_CFrame_Camera then
					Camera.CFrame = Save_CFrame_Camera
					Save_CFrame_Camera = nil
				end
				check__switch({BB=nil,TM=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,TS=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
			elseif Mode == "Focus" and (ChangedChar ~= HisCharacter or ChangedMode ~= Mode) then	
				MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Camera",{PlayOnRemove=true})
				ChangedChar,ChangedMode = HisCharacter,Mode
				check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,TS=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
				Camera.CameraSubject = HisCharacter.Head
				Camera.CameraType = Enum.CameraType.Custom
				
				Scenes_Connections.LoopCameraCustom=_Services.Run.RenderStepped:connect(function()
					Camera.CFrame = SCENE_OFFSET_RETURN(Camera.CFrame*rotation_z)
				end)
			elseif Mode == "FP" and (ChangedChar ~= HisCharacter or ChangedMode ~= Mode) then
				MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Camera",{PlayOnRemove=true})
				ChangedChar,ChangedMode = HisCharacter,Mode
				local rotation_offset = CFA(0,0,0)
				local next_rotation_offset = CFA(0,0,0)
				local old_rotation_offset = next_rotation_offset

				for _,Weld_Head in pairs( HisCharacter.Character:FindFirstChild("__Fake__Parts__"):GetChildren()) do
					if Weld_Head:GetAttribute("FirstPersonTag") == true and Weld_Head:IsA("Weld") then
						Weld_Excelsios(Weld_Head.Part1.Parent)
					end
				end

				--AnotherWeld
				if HisCharacter.AnotherWeld then
					Weld_Excelsios(HisCharacter.AnotherWeld)
				end

				Scenes_Connections.FP_Input_Changer = _Services.UserInput.InputChanged:connect(function(input)
					if input.UserInputType == Enum.UserInputType.MouseMovement then
						local SENNN = _Services.UserInput.MouseDeltaSensitivity
						next_rotation_offset = next_rotation_offset:Lerp(CFA(0, M_RAD(-input.Delta.X)*SENNN, 0) * CFA(-M_RAD(input.Delta.Y)*SENNN, 0, 0),.5)
					end
				end)

				local OffsetFp = HisCharacter.Head:GetAttribute("OffsetFp") 
				if OffsetFp then
					OffsetFp = CFN(OffsetFp.X,OffsetFp.Y,OffsetFp.Z)
				else
					OffsetFp = CFN()
				end

				check__switch({BB=true,TM=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,TS=LOCAL_MD_.Meta_Elements.Anti_Free_Camera,NN=nil,FF=LOCAL_MD_.FF.Update_Free_Camera}) 
				Scenes_Connections.LoopCameraCustom=_Services.Run.RenderStepped:connect(function()
					if old_rotation_offset == next_rotation_offset then
						next_rotation_offset = next_rotation_offset:Lerp(CFA(0,0,0),.1)
					end
					old_rotation_offset = next_rotation_offset
					rotation_offset = rotation_offset*next_rotation_offset
					Camera.CFrame = (HisCharacter.Head.CFrame*OffsetFp)*rotation_offset*rotation_z
				end)
			end
		end

		local function Add_Pov_Chracter(Local_Config)
			local SlotCha = script.slot_character_scenes:Clone()
			local ViewPortFrame = SlotCha.slot_content:FindFirstChild("PLAYER_FACE")
			local character_name = SlotCha.slot_content:FindFirstChild("character_name")
			local toggle_Fp = SlotCha.slot_content:FindFirstChild("toggle_Fp")
			local toggle_focus = SlotCha.slot_content:FindFirstChild("toggle_focus")

			TA_IN(Scene_Instances,SlotCha)
			SlotCha.Parent = __SC_SS_POV_Characters_list

			local HisCharacter	
			if Local_Config.ImPlayer then
				module:Viewport_Frame_Player(ViewPortFrame,MD_.Current_Skin,"Cloth",nil,true,true)
				character_name.Text = "You"
				local Rig_Player = Scene_Config.Scene_Model.Rig_Player
				HisCharacter={Character=Rig_Player,Head=get_Head_from(Rig_Player),AnotherWeld=Rig_Player:FindFirstChild("_Face_Rig")}
			else
				local RigFake = Local_Config.Bot_Character.Parent:Clone()
				character_name.Text = Local_Config.Bot_Config.REAL_Name
				RigFake.Parent = ViewPortFrame
				local Rig = Local_Config.Bot_Character:Clone()
				Rig.Parent = ViewPortFrame
				local HAEAA  = Rig.Head

				local Camera = INST("Camera",ViewPortFrame)
				Camera.FieldOfView=10
				ViewPortFrame.CurrentCamera = Camera
				Camera.CFrame = CFN(HAEAA.CFrame.p+(HAEAA.CFrame.LookVector*15)+(HAEAA.CFrame.RightVector*-15)+(HAEAA.CFrame.UpVector*1),HAEAA.CFrame.p) 
				ViewPortFrame.LightDirection = Camera.CFrame.LookVector
				HisCharacter = get_my_character(Local_Config.Bot_Config.REAL_Name)
			end

			module:animated_hover("Style_2",toggle_Fp,{SFX="UI_Hover_001";connection_table=Scenes_Connections})	
			module:animated_hover("Style_2",toggle_focus,{SFX="UI_Hover_001";connection_table=Scenes_Connections})	
			TA_IN(Scenes_Connections,toggle_Fp.MouseButton1Click:connect(function()
				ChangeCamera("FP",HisCharacter)
			end))
			TA_IN(Scenes_Connections,toggle_focus.MouseButton1Click:connect(function()
				ChangeCamera("Focus",HisCharacter)
			end))
		end
		TA_IN(Scenes_Connections,__SC_SS_reset.MouseButton1Click:connect(function()
			ChangeCamera("RESET")
		end))
		
		-- añade peronsjea a l lista de fov xd
		for i,v in pairs (Scene_Config.Local_Config_Log) do -- personajes del SCENE CONFIG
			Add_Pov_Chracter(v.Local_Config)
		end Add_Pov_Chracter(MD_.Re_Bots[Character]) -- el jguador es exclusivo equis de
		
		--▀▀█▀▀ █▀▀█ █▀▀█ █▀▀▀ █▀▀ ▀▀█▀▀   	█▀▀█ █▀▀▄ █▀▀▄ 　 ▀▀█▀▀ █▀▀█ █▀▀█ █▀▀▄ █▀▀ █▀▀█ █▀▀█ █▀▀█ █▀▀ █▀▀▄ █▀▀ █░░█ 　	█▀▀ █▀▀ ▀▀█▀▀ █░░█ █▀▀█ 
		--░░█░░ █▄▄█ █▄▄▀ █░▀█ █▀▀ ░░█░░  	█▄▄█ █░░█ █░░█ 　 ░░█░░ █▄▄▀ █▄▄█ █░░█ ▀▀█ █░░█ █▄▄█ █▄▄▀ █▀▀ █░░█ █░░ █▄▄█  	▀▀█ █▀▀ ░░█░░ █░░█ █░░█ 
		--░░▀░░ ▀░░▀ ▀░▀▀ ▀▀▀▀ ▀▀▀ ░░▀░░ 　 	▀░░▀ ▀░░▀ ▀▀▀░ 　 ░░▀░░ ▀░▀▀ ▀░░▀ ▀░░▀ ▀▀▀ █▀▀▀ ▀░░▀ ▀░▀▀ ▀▀▀ ▀░░▀ ▀▀▀ ▄▄▄█  	▀▀▀ ▀▀▀ ░░▀░░ ░▀▀▀ █▀▀▀

		local CURRENT_TARGET_PART = nil
		local LOOKING_TARGET_STATE
		
		local function target_update_UI()
			TargetManipulator_B_GetPart.Visible = not CURRENT_TARGET_PART and not LOOKING_TARGET_STATE
			TargetManipulator_B_CleanPart.Visible = CURRENT_TARGET_PART and not LOOKING_TARGET_STATE
			TargetManipulator_B_Recoding.Visible = LOOKING_TARGET_STATE
			TransparencyManipulator_B_Recoding.Visible = LOOKING_TARGET_STATE
			TransparencyManipulator_B_GetPart.Visible = not LOOKING_TARGET_STATE
			button_effect_click_3(TargetManipulator_TargetButtons)
			button_effect_click_3(TransparencyManipulator_TargetButtons)
		end target_update_UI()
		
		local function reset_transparency()
			for i,v in pairs (Scene_Config.Scene_Model:GetDescendants()) do
				if v:IsA("BasePart") and v:GetAttribute("OR_Transparency") then
					v.Transparency = v:GetAttribute("OR_Transparency")
				end
			end
		end
		
		local function start_looking_for_(style)
			if not LOOKING_TARGET_STATE then
				LOOKING_TARGET_STATE = true
				spawn(function()
					local NEXT_TARGET
					local Mouse=  __VMOUSE()
					local cursor = MD_.FF:fake_part_detail (Color3.fromRGB(255, 234, 0),CFrame.new(),Vector3.new(.1,.1,.1),"Forever")
					cursor.Transparency=.5

					local hitbox = MD_.FF:fake_part_detail (Color3.fromRGB(89, 255, 0),CFrame.new(),Vector3.new(.1,.1,.1),"Forever")
					hitbox.Transparency=.5
					
					MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_012",{PlayOnRemove=true})
					
					local SelectionBox = INST("SelectionBox",hitbox)
					SelectionBox.Adornee = hitbox
					SelectionBox.Color3 = Color3.fromRGB(12, 255, 0)
					SelectionBox.SurfaceColor3 = Color3.fromRGB(90, 203, 70)
					SelectionBox.LineThickness = .1
					SelectionBox.SurfaceTransparency=.75
					
					target_update_UI()

					repeat _Services.Run.RenderStepped:wait()
						local unit = (Mouse.Hit.p-Camera.CFrame.p).unit
						local RayCastResults = MD_.FF:CastUntilHitWhiteList(Camera.CFrame.p,Camera.CFrame.p+(unit*250),RayParams)

						cursor.CFrame = CFrame.new(RayCastResults.Position)

						if RayCastResults.Instance then
							hitbox.CFrame = RayCastResults.Instance.CFrame
							hitbox.Size = RayCastResults.Instance.Size
						else
							hitbox.CFrame = Camera.CFrame*CFrame.new(500,0,0)
							hitbox.Size = Vector3.new()
						end

						if LOCAL_MD_.ClickMouseButton1 then
							LOCAL_MD_.ClickMouseButton1 = nil
							NEXT_TARGET = RayCastResults.Instance
							if LOCAL_MD_.LeftShift_state ~= "ON" or NEXT_TARGET then
								break
							end
						end
					until not _____Scene_Career.Visible and LOOKING_TARGET_STATE
					if NEXT_TARGET then
						MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_014",{PlayOnRemove=true})
						if style == "transparency" and NEXT_TARGET.Parent:FindFirstChild("__Fake__Parts__") then
							local Rig = NEXT_TARGET.Parent
							local nameclean = NEXT_TARGET.Name:gsub(tostring(">>" .. Rig.Name .. "<<_"),"")
							local FakeModel = Rig:FindFirstChild("__Fake__Parts__"):FindFirstChild(nameclean)
							if not FakeModel then FakeModel = Rig:FindFirstChild("__Fake__Parts__"):FindFirstChild(NEXT_TARGET.Name) end
							if FakeModel then
								for i,v in pairs (FakeModel:GetDescendants()) do
									local or_transpartency = v:GetAttribute("OR_Transparency")
									if v:IsA("BasePart") and or_transpartency and or_transpartency ~= 1 then
										v.Transparency = LOCAL_MD_.SCENE_TRANSPARENCY
									end
								end
							end
						end
						if style == "target" then
							if Scenes_Connections.TARGETLo_opCameraCustom then Scenes_Connections.TARGETLo_opCameraCustom:Disconnect() Scenes_Connections.TARGETLo_opCameraCustom = nil end
							local LastCFrame = SCENE_OFFSET_RETURN(NEXT_TARGET.CFrame)
							Scenes_Connections.TARGETLo_opCameraCustom=_Services.Run.RenderStepped:connect(function()
								local smooth_ness = (1-LOCAL_MD_.SCENE_SMOOTHNESS)^2
								local NEXT_TARGETCFrame = SCENE_OFFSET_RETURN(NEXT_TARGET.CFrame)
								if __LOCK__CFRAME == "YES" then
									local Rel = NEXT_TARGETCFrame * LastCFrame:inverse()
									Camera.CFrame = Camera.CFrame:Lerp(Rel * Camera.CFrame ,smooth_ness)
								end
								if __FOCUS__POSITION == "YES" then
									Camera.CFrame = Camera.CFrame:Lerp(CFrame.new(Camera.CFrame.p,NEXT_TARGETCFrame.p),smooth_ness)
								end
								LastCFrame = LastCFrame:Lerp(NEXT_TARGETCFrame,smooth_ness)
							end)
						end
					else
						MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_015",{PlayOnRemove=true})
						MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_010",{PlayOnRemove=true})
					end
					cursor:Destroy()
					hitbox:Destroy()
					if style == "target" then CURRENT_TARGET_PART = NEXT_TARGET end
					LOOKING_TARGET_STATE = nil
					target_update_UI()
					if style == "transparency" and NEXT_TARGET and LOCAL_MD_.LeftShift_state == "ON" then return start_looking_for_(style) end -- hold shit for more transparency shit :v
				end)
			end	
		end

		TA_IN(Scenes_Connections,TargetManipulator_B_GetPart.MouseButton1Click:connect(function()	
			start_looking_for_("target")
		end))
		TA_IN(Scenes_Connections,TransparencyManipulator_B_GetPart.MouseButton1Click:connect(function()	
			start_looking_for_("transparency")
		end))
		TA_IN(Scenes_Connections,TransparencyManipulator_B_ResetDefault.MouseButton1Click:connect(function()	
			reset_transparency()
			MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_013",{PlayOnRemove=true})
			button_effect_click_3(TransparencyManipulator_B_ResetDefault)
		end))
		
		TA_IN(Scenes_Connections,TargetManipulator_B_CleanPart.MouseButton1Click:connect(function()
			CURRENT_TARGET_PART = nil
			if Scenes_Connections.TARGETLo_opCameraCustom then Scenes_Connections.TARGETLo_opCameraCustom:Disconnect() Scenes_Connections.TARGETLo_opCameraCustom = nil end
			MD_.FF:PlaySound(__PC_character_list_scrolling,"UI_Button_013",{PlayOnRemove=true})
			target_update_UI()
		end))
		TA_IN(Scenes_Connections,TargetManipulator_B_Recoding.MouseButton1Click:connect(function()
			if LOOKING_TARGET_STATE then 
				CURRENT_TARGET_PART = nil
				LOOKING_TARGET_STATE = nil
				target_update_UI()
			end
		end))
		
		TA_IN(Scenes_Connections,TargetManipulator_B_CleanPart.MouseEnter:connect(function()
			if not Scene_Instances.TARGET_DISPLAY and CURRENT_TARGET_PART then
				local hitbox = MD_.FF:fake_part_detail (Color3.fromRGB(255, 179, 0),CFrame.new(),Vector3.new(.1,.1,.1),"Forever")
				hitbox.Transparency=.85
				hitbox.Size = CURRENT_TARGET_PART.Size
				Scene_Instances.TARGET_DISPLAY = hitbox
				
				local SelectionBox = INST("SelectionBox",hitbox)
				SelectionBox.Adornee = hitbox
				SelectionBox.Color3 = Color3.fromRGB(12, 255, 0)
				SelectionBox.SurfaceColor3 = Color3.fromRGB(90, 203, 70)
				SelectionBox.LineThickness = .1
				SelectionBox.SurfaceTransparency=.75
				
				while Scene_Instances.TARGET_DISPLAY and CURRENT_TARGET_PART and _Services.Run.RenderStepped:wait() do
					if CURRENT_TARGET_PART then
						hitbox.CFrame = CURRENT_TARGET_PART.CFrame
					end
				end
				
				if Scene_Instances.TARGET_DISPLAY then
					Scene_Instances.TARGET_DISPLAY:Destroy()
					Scene_Instances.TARGET_DISPLAY=nil
				end
			end
		end))
		
		TA_IN(Scenes_Connections,TargetManipulator_B_CleanPart.MouseLeave:connect(function()
			if Scene_Instances.TARGET_DISPLAY then
				Scene_Instances.TARGET_DISPLAY:Destroy()
				Scene_Instances.TARGET_DISPLAY=nil
			end
		end))
		
		--▀▀█▀▀ █▀▀█ █▀▀█ █▀▀▀ █▀▀ ▀▀█▀▀ 　 ▀█░█▀ █▀▀█ █░░ █░░█ █▀▀ █▀▀ 
		--░░█░░ █▄▄█ █▄▄▀ █░▀█ █▀▀ ░░█░░ 　 ░█▄█░ █▄▄█ █░░ █░░█ █▀▀ ▀▀█ 
		--░░▀░░ ▀░░▀ ▀░▀▀ ▀▀▀▀ ▀▀▀ ░░▀░░ 　 ░░▀░░ ▀░░▀ ▀▀▀ ░▀▀▀ ▀▀▀ ▀▀▀
		
		local function target_change_state(ui,state)
			ui.CORRECT.Visible = state == "YES"
			ui.NoCORRECT.Visible = state == "NO"
		end
		
		local function add_custom_button_1(ui,change_state,current_state)
			change_state("NO")
			target_change_state(ui,current_state())
			TA_IN(Scenes_Connections,ui.MouseButton1Click:connect(function()
				MD_.FF:PlaySound(__SC_Scene_Settings,"UI_Button_009",{PlayOnRemove=true})
				change_state(current_state() == "YES" and "NO" or "YES")
				target_change_state(ui,current_state())
				button_effect_click_2(ui)
			end))
		end
		
		-- FOCUS POSITION --
		add_custom_button_1(TargetManipulator_B_FocusPosition,function(next_state) __FOCUS__POSITION = next_state end,function() return __FOCUS__POSITION end)
		-- LOCK CFRAME --
		add_custom_button_1(TargetManipulator_B_LockCFrame,function(next_state) __LOCK__CFRAME = next_state end,function() return __LOCK__CFRAME end)
		-- VIBRATION MODE -- 
		add_custom_button_1(CameraManMode_B_VibrationMode,function(next_state) __VIBRATION__MODE = next_state random1,random2 = M_RAN(),M_RAN() end,function() return __VIBRATION__MODE end)
		--
		----█▀▀▄ █▀▀█ █▀▀ █▀▀█ █░█ █▀▀ █▀▀ █▀▀ █▀▀▄ █▀▀ 
		----█▀▀▄ █▄▄▀ █▀▀ █▄▄█ █▀▄ ▀▀█ █░░ █▀▀ █░░█ █▀▀ 
		----▀▀▀░ ▀░▀▀ ▀▀▀ ▀░░▀ ▀░▀ ▀▀▀ ▀▀▀ ▀▀▀ ▀░░▀ ▀▀▀
		
		local Togle_QE
		local CurrentProgress,AmountProgressN = 0,0
		local BRLT = SUIP[__SC_break_label].Position
		local Done,tick_press,__VIBRATION__LastCFrame
		__SC_break_label.Position = UDI2(BRLT.X.Scale,0,BRLT.Y.Scale,0)
		
		TA_IN(Scenes_Connections,_Services.Run.RenderStepped:connect(function(ms)
			
			--████████████
			--████████████
			
			--█░█ █ █▄▄ █▀█ ▄▀█ █▀▄ █▀█ █▀█   ░░█ ▄▀█ ░░█ ▄▀█
			--▀▄▀ █ █▄█ █▀▄ █▀█ █▄▀ █▄█ █▀▄   █▄█ █▀█ █▄█ █▀█
			
			if __VIBRATION__MODE == "YES" then
				local smooth_ness = .1

				local _x_v = (tick()+math.cos(tick()*random2*LOCAL_MD_.V_Rate))*LOCAL_MD_.V_Rate
				local _y_v = (tick()+math.sin(tick()*random1*LOCAL_MD_.V_Rate))*LOCAL_MD_.V_Rate
				
				local NEXT_TARGETCFrame = CFrame.new(0,0,0)*CFrame.Angles((math.sin(_x_v)*LOCAL_MD_.V_Range)/25,(math.cos(_y_v)*LOCAL_MD_.V_Range)/50,0)
				
				__VIBRATION__LastCFrame = __VIBRATION__LastCFrame or NEXT_TARGETCFrame
				local Rel = NEXT_TARGETCFrame * __VIBRATION__LastCFrame:inverse()
				Camera.CFrame *= Rel
				__VIBRATION__LastCFrame = __VIBRATION__LastCFrame:Lerp(NEXT_TARGETCFrame,smooth_ness)
			else
				__VIBRATION__LastCFrame = nil
			end
			
			--████████████
			--████████████
			
			rotation_z = rotation_z:Lerp(CFA(0,0,M_RAD(LOCAL_MD_.Z_ANGLE)),.2)
			Camera.FieldOfView = MD_.FF:Lerp(Camera.FieldOfView,LOCAL_MD_.FOV_SCENES,.1)
			if not Done then
				__SCB_display_bar_Gra.Offset = Vector2.new((CurrentProgress/100)-1,0)
				local multi_for_dmg = 1+(5-LOCAL_MD_.Health)/3
				CurrentProgress = M_CL(CurrentProgress-(.2*multi_for_dmg),0,110)
				AmountProgressN += CurrentProgress/85
				local of = M_SIN(AmountProgressN)/45
				__SC_break_label.Position = UDI2(BRLT.X.Scale,0,BRLT.Y.Scale+of,0)
				if CurrentProgress >= 100  then
					Done = true
					Reset_All_Head_Welds()
					MD_.Re_Bots[Character].Scene_Config:Stop_Scene()
				end
			end
			
			--████████████
			--████████████
			
		end))

		__SC_break_label.Position=SUIP[__SC_break_label].Position

		__SCB_Toggle_Z.Size=SUIP[__SCB_Toggle_Z].Size
		__SCB_Toggle_X.Size=SUIP[__SCB_Toggle_X].Size

		TA_IN(Scenes_Connections,_Services.UserInput.InputBegan:connect(function(input, gameProcessed)
			if not Done then
				if tick_press and tick_press - tick() < 0 then
					tick_press= nil
				end
				if input.KeyCode == Enum.KeyCode.Z and (Togle_QE == "E" or not Togle_QE) and not tick_press then
					tick_press = tick()+.01
					Togle_QE="Q"
					CurrentProgress += 4

					MD_.FF:PlaySound(__SCB_Toggle_X,"UI_Escape_Button",{PlayOnRemove=true;PlaybackSpeed=.7+(CurrentProgress/300)})
					local TOXX = SUIP[__SCB_Toggle_X].Size
					_Services.Tween:Create(__SCB_Toggle_X,TWEEN_IN(.15,Tween_Styles.Back,Tween_Directions.InOut,0,false,0),{Size=UDI2(TOXX.X.Scale*1.25,0,TOXX.Y.Scale*1.25,0)}):play() 
					local TOXX = SUIP[__SCB_Toggle_Z].Size
					_Services.Tween:Create(__SCB_Toggle_Z,TWEEN_IN(.15,Tween_Styles.Back,Tween_Directions.InOut,0,false,0),{Size=UDI2(TOXX.X.Scale*.85,0,TOXX.Y.Scale*.85,0)}):play() 
				elseif input.KeyCode == Enum.KeyCode.X and (Togle_QE == "Q" or not Togle_QE) and not tick_press then
					tick_press = tick()+.01
					Togle_QE="E"
					CurrentProgress += 4
					MD_.FF:PlaySound(__SCB_Toggle_Z,"UI_Escape_Button",{PlayOnRemove=true;PlaybackSpeed=.7+(CurrentProgress/300)})
					local TOXX = SUIP[__SCB_Toggle_Z].Size
					_Services.Tween:Create(__SCB_Toggle_Z,TWEEN_IN(.15,Tween_Styles.Back,Tween_Directions.InOut,0,false,0),{Size=UDI2(TOXX.X.Scale*1.25,0,TOXX.Y.Scale*1.25,0)}):play() 
					local TOXX = SUIP[__SCB_Toggle_X].Size
					_Services.Tween:Create(__SCB_Toggle_X,TWEEN_IN(.15,Tween_Styles.Back,Tween_Directions.InOut,0,false,0),{Size=UDI2(TOXX.X.Scale*.85,0,TOXX.Y.Scale*.85,0)}):play() 
				end
			end
		end))
	end
end

