	local function update_all_grid ()
		for i,v in pairs (to_grid_list) do
			local UiGridLayout = v.UiGridLayout
			local function update_grid()
				local contentSize = UiGridLayout.AbsoluteContentSize
				local NewSize = (v.Y) * v.frame_scroll.AbsoluteSize.Y
				local NewPadding = (v.Y_padding) * v.frame_scroll.AbsoluteSize.Y
				v.frame_scroll.CanvasSize = UDim2.fromOffset(0, contentSize.Y)
				UiGridLayout.CellPadding = UDI2(v.X_padding,0, 0, NewPadding)
				UiGridLayout.CellSize = UDI2(v.X,0, 0, NewSize)
			end
			update_grid()
			if not v.GetPropertyChangedSignal_AbsoluteContentSize then
				v.GetPropertyChangedSignal_AbsoluteContentSize= true
				UiGridLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(update_grid)
			end
		end
	end
	Camera:GetPropertyChangedSignal("ViewportSize"):Connect(update_all_grid) update_all_grid ()
	--█████████████████████████████████████████████████████████████▀███████
	--█▄─▄─▀██▀▄─██▄─▄▄▀███─▄▄▄▄█▄─▄▄─█─▄─▄─█─▄─▄─█▄─▄█▄─▀█▄─▄█─▄▄▄▄█─▄▄▄▄█
