	do -- FOV BAR
		local BarFovInfo = {MyValue=80/120;Min=5;Max=120;UpdateFunction=function(Current_Value,CalculatedVal) 
			LOCAL_MD_.FOV_SCENES = CalculatedVal
		end}
		CreateBarOption(__SC_SS_Fov_bar,BarFovInfo)
	end
	
	do -- VOLUME BAR
		local Volumen_Bar = __PCSETTINGSCC_values_1:FindFirstChild("Volumen_Bar")
		local BarFovInfo = {MyValue=MD_.MUSIC_VOLUME/200;Min=0;Max=200;UpdateFunction=function(Current_Value,CalculatedVal) 
			MD_.MUSIC_VOLUME = CalculatedVal
		end}
		CreateBarOption(Volumen_Bar,BarFovInfo)
	end
	
	do -- UI SIZE BAR
		local UIS_Bar = __PCSETTINGSCC_values_4:FindFirstChild("UIS_Bar")
		local BarFovInfo = {MyValue=MD_.UI_SIZE/100;Min=0;Max=100;tween_path=.15;UpdateFunction=function(Current_Value,CalculatedVal) 
			MD_.UI_SIZE = (CalculatedVal)

			local calculacion_anal = .5-(CalculatedVal/100)
			local o = 1-(calculacion_anal/1.5)
			for i,v in pairs ({_____Menu_Frames,_____Menu_Interactions,_____Player_Career,_____Wave_Menu,__SC_Scene_PREFERENCES,__SC_break_label}) do
				local s = SUIP[v].Size
				v.Size = UDim2.fromScale(s.X.Scale*o,s.Y.Scale*o)
			end
		end}
		CreateBarOption(UIS_Bar,BarFovInfo)
	end
	
	do -- FOV SETTINGS BAR
		local Fov_Bar = __PCSETTINGSCC_values_3:FindFirstChild("FOV_Bar")
		local BarFovInfo = {MyValue=MD_.CURRENT_FOV/120;Min=0;Max=120;UpdateFunction=function(Current_Value,CalculatedVal) 
			MD_.CURRENT_FOV = CalculatedVal
		end}
		CreateBarOption(Fov_Bar,BarFovInfo)
	end
	
	do -- Z ANGLE BAR
