	do -- SMOOTHNESS BAR
		local BarFovInfo = {MyValue=LOCAL_MD_.SCENE_SMOOTHNESS/100;Min=0;Max=100;UpdateFunction=function(Current_Value,CalculatedVal) 
			LOCAL_MD_.SCENE_SMOOTHNESS = CalculatedVal/100
		end}
		CreateBarOption(__SC_SS_Smoothness,BarFovInfo)
	end
	
	local min,max = -30,30
