		local BarFovInfo = {MyValue=.5;Min=min;Max=max;UpdateFunction=function(Current_Value,CalculatedVal) 
			LOCAL_MD_.SCENE_OFFSET_Z = CalculatedVal/max
		end}
		CreateBarOption(__SC_SS_CoordinateZ,BarFovInfo)
	end
	
	do -- RATE BAR
		local BarFovInfo = {MyValue=LOCAL_MD_.V_Rate/100;Min=0;Max=100;UpdateFunction=function(Current_Value,CalculatedVal) 
			LOCAL_MD_.V_Rate = (CalculatedVal/50)^5
		end}
		CreateBarOption(CameraManMode_V_Speed,BarFovInfo)
