function module:UI_Loop()
	local difer = (5-LOCAL_MD_.Health)*1.5
	local difer2 = (5-LOCAL_MD_.Health)*2
	local X_ = M_RAD(tick()%360)*285*(difer2+1)
	local X2_ = M_RAD(tick()%360)*185
	for i,v in pairs (Heart_UI_List) do
		v.Rotation = M_SIN(X_+M_RAD((i+1)*35))*25
		local y_move= M_COS(X_+M_RAD((i+1)*65))/(13-difer)
		v.Position = UDI2(0.5, 0,0.5+y_move, 0)
	end
	
	__WA__ROTATE_GRADIENT_1.Rotation = X2_*55
	__WA__ROTATE_GRADIENT_2=__WA__ROTATE_GRADIENT_1.Rotation
	__WA_Button.Rotation = M_COS(X2_)*5
	
	for i,v in pairs ({__MIB_admin_button,__MIB_shop_button,__MIB_peace_button,__MIB_character_list_button,__MIB_settings_button}) do
		v.Rotation = M_COS(X2_+M_RAD(v.Parent.LayoutOrder*25))*5
	end
	
	for i,v in pairs ({__WABU_Abuser;__WABU_Gentile;__WABU_Rapist}) do
		v.Rotation = M_COS(X2_+M_RAD(v.Parent.LayoutOrder*15))*2
	end
	
	if MD_.Current_Money ~= __backgrup_money then
		__MI_Money_amount.Text = MD_.Current_Money .. "$"
		
		do
			local money_display = script.money_display:Clone()
			money_display.Parent = __MI_Money_amount
			money_display.Size = UDim2.fromScale(1,1)
			money_display.Position = UDim2.fromScale(.5,.5)
			money_display.TextColor3 =  (__backgrup_money > MD_.Current_Money and Color3.fromRGB(255, 0, 4)) or Color3.fromRGB(17, 255, 0)
			local UIStroke = money_display:FindFirstChild("UIStroke")
			UIStroke.Color =  (__backgrup_money > MD_.Current_Money and Color3.fromRGB(84, 0, 1)) or Color3.fromRGB(22, 86, 14)
			local simbol = (__backgrup_money > MD_.Current_Money and "-") or "+"
			money_display.Text = simbol .. math.abs(__backgrup_money-MD_.Current_Money) .. "$"
			
			local twinfo = TWEEN_IN(1.25,Tween_Styles.Sine,Tween_Directions.Out,0,false,0)
			_Services.Tween:Create(UIStroke,twinfo,{Transparency=1}):play()
			_Services.Tween:Create(money_display,twinfo,{TextTransparency=1;Position = UDim2.fromScale(1.5,.5)}):play()
			
			_Services.Debris:AddItem(money_display,1.25)
		end
		
		__MI_Money.Size = UDim2.fromScale(0,0)

		_Services.Tween:Create(__MI_Money,TWEEN_IN(.5,Tween_Styles.Elastic,Tween_Directions.Out,0,false,0),SUIP[__MI_Money]):play()
		
		__backgrup_money = MD_.Current_Money
	end
	
	-- stamina stuff
	if OldStaminaAmount and LOCAL_MD_.StaminaAmount ~= OldStaminaAmount then
		if OldStaminaAmount > LOCAL_MD_.StaminaAmount then
			StaminaAmount_Start_Reload = tick() + 1
		end
	end
	
	if StaminaAmount_Start_Reload-tick() < 0 and LOCAL_MD_.StaminaAmount ~= LOCAL_MD_.StaminaAmountMa then
		LOCAL_MD_.StaminaAmount += .2
	end
	LOCAL_MD_.StaminaAmount = M_CL(LOCAL_MD_.StaminaAmount,0,LOCAL_MD_.StaminaAmountMax)
	if LOCAL_MD_.StaminaAmount ~= OldStaminaAmount then
		_Services.Tween:Create(stamina_bar.ui_base.bar,TWEEN_IN(.15,Tween_Styles.Linear,Tween_Directions.Out,0,false,0),{Size=UDI2(LOCAL_MD_.StaminaAmount/LOCAL_MD_.StaminaAmountMax,0,1,0)}):play()
	end
	
	local Confirm_Max_Stamina = LOCAL_MD_.StaminaAmount == LOCAL_MD_.StaminaAmountMax 
	OldStaminaAmount=LOCAL_MD_.StaminaAmount
	--
	
	if Confirm_Max_Stamina_Backup ~= Confirm_Max_Stamina then
		local SSS = SUIP[stamina_bar]
		if Confirm_Max_Stamina then
			_Services.Tween:Create(stamina_bar,TWEEN_IN(.5,Tween_Styles.Back,Tween_Directions.In,0,false,0),{Position=SSS.Position+UDI2(0,0,.5,0)}):play()
		else
			_Services.Tween:Create(stamina_bar,TWEEN_IN(.5,Tween_Styles.Back,Tween_Directions.Out,0,false,0),{Position=SSS.Position}):play()
		end
		Confirm_Max_Stamina_Backup = Confirm_Max_Stamina
	end
end

return module
]=]
