-- reset combinations table value
function module:Reset_Current_Combination(LocalConfig)
	LocalConfig.Current_Combination = {}
	for _,Entiy in pairs (MD_.AI_CONFIG) do
		LocalConfig.Current_Combination[Entiy.REAL_Name] = {Amount=0}
	end
end 

-- check for current available combination
function module:Examine_Combinations(REAL_Name,TARGET_REAL_Name,Combinations_Conditions,Target_Current_Combination)
	-- Combinations_Conditions -- conditions from the entity about the target
	-- Target_Current_Combination -- shows the current combination list from the target
	if not Combinations_Conditions then return false end
	for _,List in pairs (Combinations_Conditions) do
		-- mira todos los ehhhhhhh compara la actual lista de combinaciones del target
		local Continue = true
		for tag,tab in pairs(Target_Current_Combination) do
			local LN = List.Needed or {}
			if not LN[tag] and tab.Amount ~= 0 and tag ~= REAL_Name then 
				Continue = false
			end
		end
		if Continue and List.Request(Target_Current_Combination,REAL_Name) then
			return List.AnimationConfig
		end
	end
	return false
end

