function module:Setup_AI()
	local AI_CONFIG = {}
	for _,AI in next,script.AI_MOBS_LIST:GetChildren()do
		if AI:IsA("ModuleScript") then
			local AIName = AI.Name;
			local Success,ErrorMessage = pcall(function() --Prevents it from breaking the entire game.
				AI_CONFIG[AIName] = require(AI);
			end); if not Success then
				warn("["..AIName.."-Loading Error]: "..ErrorMessage);
			end;
		end;
	end;
	MD_.AI_CONFIG=AI_CONFIG
end

