function module:LoadCharacter(Entity_Name_User,WAVE_MODE)
	
	local CONFIG_NAME,Bot_Character = Entity_Name_User.Value,Entity_Name_User.Parent
	local Bot_Config = MD_.AI_CONFIG[CONFIG_NAME]
	if not Bot_Config then warn(" < " .. CONFIG_NAME .. " > ","Dosent Exist!!") return end

	--████████████████████████████████████████████████████████████████████████████████████████████
	--█─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─███─▄▄▄─█─█─██▀▄─██▄─▄▄▀█████░██████▀▄─██▄─▀█▄─▄█▄─▄█▄─▀█▀─▄█
