			Local_Config.MaxHealth = amount
			Local_Config.Health = amount
			Local_Config.Functions:Update_Health_UI()
		end  Local_Config.Functions:Update_Health_Max(Local_Config.Health)
		
		function Local_Config.Functions:IncreaseHealth(amount)
			if Local_Config.Health <= 0 or Local_Config.Health == Local_Config.MaxHealth then return false end
			Local_Config.Health = math.clamp(Local_Config.Health+amount,0,Local_Config.MaxHealth) 
			Local_Config.Functions:Update_Health_UI()
			return true
		end 
		
		function Local_Config.Functions:Update_Rarity(next_rarity)
			Local_Config.Entity_Rarity = Entity_Rarity[next_rarity];
			Local_Config.Functions:Update_Health_UI_Info()
		end
		
		function Local_Config.Functions:UpdateTeam(teamname)
			Local_Config.Team=teamname
