			if Local_Config.Target_Entity then
				return Local_Config.Target_Entity.Self.My_Scene_Model and Local_Config.Target_Entity.Self.My_Scene_Model:FindFirstChild("MAIN_SCENERY_PART") or Local_Config.Target_Entity.Bot_Root
			end
			return false
		end	
		
