					or (Local_Config.Target_Entity.Scene_Config and Local_Config.Target_Entity.Scene_Config.Scene_Active)  -- if target entity is in a scene
					or Local_Config.Target_Entity.Self.Freedom -- if target entity is masturvacion xd
					or MD_.ORGY_MODE -- if admin orgy mode
			) and Can_Follow -- if combinations are nice to be able to fuck
		end
		
