	--█─██▄─██─▄█▀███─███████─████─▀─███─▄─▄█─██▄─██─▄█▀███─██████─▄████─██─███─█▄▀─██─███▀███─████─██─██─██─█▄▀─██
	--▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▀▀▄▄▄▀▀▄▄▀▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▀▄▄▄▀▀▀▀▄▄▄▄▀▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀
	
	do
		local RayParamsPlatform = RaycastParams.new()
		RayParamsPlatform.FilterType = Enum.RaycastFilterType.Blacklist
		RayParamsPlatform.FilterDescendantsInstances = {New_Entity_Group}
		
		if WAVE_MODE then
			function Local_Config.Functions:GET_CLOSES_TARGET()
				if self_.Tick_Target_Checker and self_.Tick_Target_Checker - tick() < 0 then self_.Tick_Target_Checker = nil end
				if not self_.Tick_Target_Checker then -- not self_.Tracking_Target and 
					self_.Tick_Target_Checker = tick() + 1
					
					local magnitude_saved = 30
					local Choosed_Target = (Bot_Config.WAVE_CORE_ATTACK and MD_.WAVE_CONFIG.MAIN_CORE) or Local_Config.ENTITY_ORIGIN
					
					for i,v in pairs (MD_.Re_Bots) do
						if v.Bot_Character ~= Bot_Character and v.Team ~= Local_Config.Team and v.Bot_Humanoid.Health > 0 and (Can_Follow or not Bot_Config.Require_Combination) and not v.Self.Defeated then
							local MATH_WORK = (Bot_Root.CFrame.p-v.Bot_Root.CFrame.p)*Vector3.new(1,2,1)
							if MATH_WORK.magnitude < magnitude_saved then
								magnitude_saved = MATH_WORK.magnitude
								Choosed_Target = v
							end
						end
					end
					if Choosed_Target and 
						(
							not Local_Config.Target_Entity  -- si no tiene a nadie
								or ( Local_Config.Target_Entity and not Local_Config.Self.Joined_Party))  -- persigue a la persona si no esta en su fiesta
					then -- if in scene can't change target
						Local_Config.Target_Entity = Choosed_Target
					end
				end
			end
		else
			function Local_Config.Functions:GET_CLOSES_TARGET()
				if self_.Tick_Target_Checker and self_.Tick_Target_Checker - tick() < 0 then self_.Tick_Target_Checker = nil end

				if not self_.Tick_Target_Checker then -- not self_.Tracking_Target and 
					self_.Tick_Target_Checker = tick() + 1
					local magnitude_saved = Bot_Config.MagnitudeDetect
					local Choosed_Target

					for i,v in pairs (MD_.Re_Bots) do
						local MATH_WORK = (Bot_Root.CFrame.p-v.Bot_Root.CFrame.p)
						if MATH_WORK.magnitude < magnitude_saved then
							local combinexdxdxdxdxxdx = Can_Follow or not Bot_Config.Require_Combination
							if v.Bot_Character ~= Bot_Character and v.Team ~= Local_Config.Team and v.Bot_Humanoid.Health > 0 and (combinexdxdxdxdxxdx or not Choosed_Target) and not v.Self.Defeated then
								local RayCastResults = MD_.FF:CastUntilHitWithHumanoid(Bot_Root.CFrame.p,v.Bot_Root.CFrame.p,RayParamsPlatform)
								local mag = (RayCastResults.Position-v.Bot_Root.CFrame.p).magnitude
								if (mag < 4) then
									magnitude_saved = MATH_WORK.magnitude
									Choosed_Target = v
								end
							end
						end
					end
					if Choosed_Target and 
						(
								not Local_Config.Target_Entity  -- si no tiene a nadie
								or ( Local_Config.Target_Entity and not Local_Config.Self.Joined_Party))  -- persigue a la persona si no esta en su fiesta
					then -- if in scene can't change target
						Local_Config.Target_Entity = Choosed_Target
						
					end
				end
			end
		end
	end

