	-- attack function 
	function Local_Config.Functions:Attack()
		if Local_Config.Target_Entity and not self_.Joined_Party then -- rape
			if self_._META_CAN_JOIN_SCENE_ then -- in case the player is weak
				local LOAD_ANIMATION = Local_Config.Functions:CheckMyCombination(Local_Config.Target_Entity)
				if LOAD_ANIMATION then
					MD_.FF:Start_Scene(Local_Config,LOAD_ANIMATION,Local_Config.Team)
				end
			end
		end
	end

