	--██─▀─███─█▄▀─███─███─█▄█─███─▀─████─████─██─██─██─█▄▀─██▄▄▄▄─█
	--▀▄▄▀▄▄▀▄▄▄▀▀▄▄▀▄▄▄▀▄▄▄▀▄▄▄▀▄▄▀▄▄▀▀▄▄▄▀▀▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀
	
	-- for especial animations
	function Local_Config.Functions:custom_playing_animation(animation,speed,Especial_Events,T)
		local T=T or {}
		for i,v in pairs (Events_Animations) do v:Disconnect() v=nil end Events_Animations = {}
		self_.Animation_Stopped = false
		local animation_instance = __LA(Bot_Humanoid.Animator, animation.Animation)

		local ANIMATION_EVENTS_TABLE = Especial_Events or Bot_Config.Animation_Events
		table.insert(Events_Animations,animation_instance:GetMarkerReachedSignal("EspecialEvent"):Connect(function(value)
			if ANIMATION_EVENTS_TABLE[value] then
				ANIMATION_EVENTS_TABLE[value]()
			end
		end))
		table.insert(Events_Animations,animation_instance.Stopped:Connect(function(value)
			self_.Animation_Stopped = true
		end))
		animation_instance:Play(T.Transition)
		if speed then
			animation_instance:AdjustSpeed(speed)
		end
		return animation_instance
	end
	
	--██████████████████████████████████████████████████████████████████████
	--█─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─███▄─▄▄─█▄─▀█▄─▄█─▄─▄─█▄─▄█─▄─▄─█▄─█─▄█
	--█▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄████─▄█▀██─█▄▀─████─████─████─████▄─▄██
	--▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀▀▀▄▄▄▄▄▀▄▄▄▀▀▄▄▀▀▄▄▄▀▀▄▄▄▀▀▄▄▄▀▀▀▄▄▄▀▀
	
	local Bot_Module_Extender = Bot_Config:CUSTOM_START(Local_Config)

	--███████████████████████████████████████████████████████████
	--██▀▄─██▄─▄▄─█▄─▄███▄─▄▄─█▄─██─▄█▄─▀█▄─▄█─▄▄▄─█─▄▄▄▄███▀▄▄▀█
	--██─▀─███─▄▄▄██─█████─▄████─██─███─█▄▀─██─███▀█▄▄▄▄─████▀▄██
	--▀▄▄▀▄▄▀▄▄▄▀▀▀▄▄▄▀▀▀▄▄▄▀▀▀▀▄▄▄▄▀▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▀
	
	do
		if WAVE_MODE then
			function Local_Config.Functions:CAN_TARGET_TO_ATTACK()
				return  Local_Config.Target_Entity and Local_Config.Target_Entity.Bot_Character and (Can_Follow or MD_.WAVE_CONFIG.Active)
			end
			local _path_tracking

			function Local_Config.Functions:START_WALKING()
				if not _path_tracking then
					_path_tracking = true
					spawn(function()
						if Local_Config.Target_Entity then
							if Local_Config.Target_Entity.path_finding and Local_Config.Self.Target_Magnitude > 10 then
								local current_Target_Entity = Local_Config.Target_Entity	
								local destination = Local_Config.Self.Target_Root.CFrame.p

								local path = _Services.PathfindingService:CreatePath({
									AgentRadius = Bot_Config.AgentRadius,
									AgentHeight = Bot_Config.AgentHeight,
									AgentCanJump = true,
									Costs = {
									}
								})

								local oldtick_loop,break_chain
								oldtick_loop = tick() + 1

								local success, errorMessage = pcall(function()
									path:ComputeAsync(Bot_Root.CFrame.p, destination)
								end)

								if path.Status == Enum.PathStatus.Success then
									local waypoints = path:GetWaypoints()
									local nextWaypointIndex = 0

									--for i,v in pairs (waypoints) do
									--	MD_.FF:fake_part_detail(COR_RGB(255, 0,0),CFN(v.Position),VE3(1,1,1),10)
									--end

									for i,waypoint in pairs (waypoints) do
										oldtick_loop = tick() + 1
										local oldtick = tick() + 1

										if waypoint.Action == Enum.PathWaypointAction.Jump then
											Bot_Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
										end

										repeat 
											UnitPathFinding = (waypoint.Position-Bot_Root.CFrame.p).unit
											Bot_Humanoid:MoveTo(waypoint.Position+(UnitPathFinding*2))
											local magni_xz = ((waypoint.Position-Bot_Root.CFrame.p)*Vector3.new(1,0,1)).magnitude
											if magni_xz < 2 then
												break
											end
											wait() 
										until oldtick - tick() < 0 
										UnitPathFinding = nil

										if oldtick - tick() < 0 or break_chain then break_chain = true break end
									end
								end

								repeat wait() until Local_Config.Target_Entity ~= current_Target_Entity or not success or break_chain or oldtick_loop - tick() < 0

								UnitPathFinding = nil
								wait(.1)
							else
								local point_ = Local_Config.Self.Target_Root.CFrame.p+(-Local_Config.Self.Target_Unit*Local_Config.Bot_Config.Range_MoveTo)
								Bot_Humanoid:MoveTo(point_)
								if not Local_Config.Target_Entity.Dont_Attack then
									Bot_Module_Extender:MOVE_TO_TARGET()
								end
							end
						end

						_path_tracking = false
					end)
				end
				self_.Tracking_Target=true
			end
		else
			function Local_Config.Functions:CAN_TARGET_TO_ATTACK() -- function that returns if entity can walk to the target
				return  Local_Config.Target_Entity and Local_Config.Target_Entity.Bot_Character -- if target exist
					and MD_.Friendly=="NO" -- pvp mode
					and Can_Follow -- if combinations are nice to be able to fuck
					and self_._META_CAN_ATTACK_KEEP_
					--and Target_Entity.Scene_Config and not Target_Entity.Scene_Config.Scene_Active -- FOR ATTACKERS BUT STIL IN PROGRESS
			end
			function Local_Config.Functions:START_WALKING()
				local point_ = Local_Config.Self.Target_Root.CFrame.p+(-Local_Config.Self.Target_Unit*Local_Config.Bot_Config.Range_MoveTo)
				Bot_Humanoid:MoveTo(point_)
				Bot_Module_Extender:MOVE_TO_TARGET()
				self_.Tracking_Target=true
			end
		end

		function Local_Config.Functions:disable_st()
			Local_Config.Trigger_GetBack.Value = nil
			if Local_Config.Trigger_Damage.Value then
				Local_Config.Trigger_Damage.Value = nil
				Local_Config.Trigger_Damage:SetAttribute("EntityTableID",nil)
				Local_Config.Trigger_Damage:SetAttribute("DamageAmount",nil)
			end
		end
	end
	
	--███████████████████████
	--█▄─▄███─▄▄─█─▄▄─█▄─▄▄─█
	--██─██▀█─██─█─██─██─▄▄▄█
	--▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▀
	
	Local_Config.Functions.Loop_Entity_Function=function() 
		--DEFEATED EVENT
		if self_.Defeated then 
			if InstantRemove then
				New_Entity_Group:Destroy()	
				Billboard:Destroy()
			elseif not self_.Defeated_Count then
				self_.Defeated_Count = true
				if WAVE_MODE and Bot_Config.Money then
					local Character,LIBRARY_MODULE = MD_.FF:Get_Player_Character(true)
					if LIBRARY_MODULE then 
						LIBRARY_MODULE.FF:Money_Display(Bot_Config.Money,Bot_Root.CFrame.p)
					end
					MD_.Current_Money+=Bot_Config.Money
				end
				delay(4,function()
					if self_.DeadFunction_Effect then 
						self_.DeadFunction_Effect() 
					else
						MD_.FF:CreatedParticle("POOF",Bot_Root.CFrame.p+Vector3.new(0,2,0),{ParticleTime=.15})
						MD_.FF:PlaySound(Bot_Root,"Other_Vanishing_001",{PlayOnRemove=true})
						MD_.FF:PlaySound(Bot_Root,"Other_Vanishing_002",{PlayOnRemove=true})
					end
					Billboard:Destroy()
					New_Entity_Group:Destroy()
				end)
			end
			return 
		end
		
		-- if Target_Entity exist, and entity is defeated or Target_Entity dosent exist later
		if Local_Config.Target_Entity and not Local_Config.Target_Entity.point_____system and (not Local_Config.Target_Entity.Bot_Humanoid:IsDescendantOf(game) or Local_Config.Target_Entity.Self.Defeated) then
			Local_Config.Target_Entity = nil
		end
		-- for debug mode
		if Local_Config.Debug_Board then
			Local_Config.Functions:LoopDebug()
		end
		
		self_._META_CANT_ATTACK_ = MD_.FF:not_empty__switch(Local_Config.Meta_Elements.CantAttack.LockSwitch)
		self_._META_STATIC_ = MD_.FF:not_empty__switch(Local_Config.Meta_Elements._STATIC_.LockSwitch)
		self_._META_CAN_KEEP_ = not (self_._Getting_Dead or self_._META_STATIC_)
		self_._META_CAN_ATTACK_KEEP_  = not self_._META_CANT_ATTACK_ and self_._META_CAN_KEEP_
		self_._META_CAN_JOIN_SCENE_ = Local_Config.Target_Entity and Local_Config.Functions:Get_Join_Scene()

		-- default trigger/damage value
		if Local_Config.Trigger_Damage.Value then
			local EntityTableID = Local_Config.Trigger_Damage:GetAttribute("EntityTableID")
			if EntityTableID == Local_Config.Entity_ID then
				Local_Config.Functions:disable_st()
			elseif EntityTableID then -- YOU HIT MEEE?? I FUCK YOU
				for _,v in pairs (MD_.Re_Bots) do
					if v.Entity_ID == EntityTableID then
						if v.Team == Local_Config.Team then
							Local_Config.Functions:disable_st()
						else
							Local_Config.Target_Entity = v
							self_.Tick_Target_Checker = tick() + 4
						end
						break
					end
				end
			end
		end
		--
		
		-- custom loop function for entity module
		Bot_Module_Extender:CUSTOM_LOOP(Local_Config,Anim_Config)
		
		-- disable trigger/damage value
		Local_Config.Functions:disable_st()
		--

		--█░█ ▄▀█ █░░ █░█ █▀▀   █░█ █▀█ █▀▄ ▄▀█ ▀█▀ █▀▀ █▀█
		--▀▄▀ █▀█ █▄▄ █▄█ ██▄   █▄█ █▀▀ █▄▀ █▀█ ░█░ ██▄ █▀▄
		--xd cum updater
		
		local Target_Entity = Local_Config.Target_Entity
		Local_Config.Functions:GET_CLOSES_TARGET()
		Local_Config.Self.Current_Force = MD_.FF:Get_Velocity(Bot_Root)
		Local_Config.Self.Target_Root = Local_Config.Functions:Get_Target_Root()
		if Local_Config.Self.Target_Root then
			Local_Config.Self.Target_Unit = (Local_Config.Self.Target_Root.CFrame.p-Bot_Root.CFrame.p).Unit
			Local_Config.Self.Target_Magnitude = (Local_Config.Self.Target_Root.CFrame.p-Bot_Root.CFrame.p).Magnitude
		else
			Local_Config.Self.Target_Unit = nil
			Local_Config.Self.Target_Magnitude = nil
		end

		--█░█░█ ▄▀█ █░░ █▄▀
		--▀▄▀▄▀ █▀█ █▄▄ █░█
		
		local NotMove = MD_.FF:not_empty__switch(Local_Config.Meta_Elements.NoMovement.LockSwitch)
		
		-- Combination Required or not
		if Bot_Config.Require_Combination and not Time_ReCheckCombination and Target_Entity and Target_Entity.Current_Combination then
			Time_ReCheckCombination = tick()+2
			Can_Follow = Local_Config.Functions:CheckMyCombination(Target_Entity)
		elseif Time_ReCheckCombination and Time_ReCheckCombination - tick() < 0 then
			Time_ReCheckCombination = nil
		end
		--
		
		if not NotMove and self_._META_CAN_KEEP_ and Local_Config.Functions:CheckCooldownTarget() then -- if can walk, not dying, not static and can attack and not target cooldown
			--[[
			Normal: the entity will only decide to attack the target if the function lets him
			Wave: the entity can fuck the target, but there is the Core Priority at the top
			]]
			if Local_Config.Functions:CAN_TARGET_TO_ATTACK() or self_._META_CAN_JOIN_SCENE_ then
				Local_Config.Functions:START_WALKING()
			elseif Target_Entity and  (Local_Config.Target_Entity.Scene_Config and Local_Config.Target_Entity.Scene_Config.Scene_Active) then --[[some kind of spectate XD ONLY IF THERE IS A TARGET]]
				if not _pos_to_walk_away or (not old_tick_change_position or old_tick_change_position - tick() < 0) then
					old_tick_change_position = tick()+.5
					local cframe_by_unit = CFrame.new(Vector3.new(),Local_Config.Self.Target_Unit)
					_pos_to_walk_away = Local_Config.Self.Target_Root.CFrame.p + (-Local_Config.Self.Target_Unit*15) 
					if Local_Config.Self.Target_Magnitude < 8.5 then
						_pos_to_walk_away += (cframe_by_unit.RightVector*(2*MD_.FF:grnw()))
					end
				end
				Bot_Humanoid:MoveTo(_pos_to_walk_away) 
			else -- stop
				stop()
			end
		else -- stop
			stop()
		end

		--█▀█ ▄▀█ █▀▀ █▀▄ █▀█ █░░ █░░
		--█▀▄ █▀█ █▄█ █▄▀ █▄█ █▄▄ █▄▄
		
		local RagdollMeta = MD_.FF:not_empty__switch(Local_Config.Meta_Elements.Ragdoll.LockSwitch) and not MD_.FF:not_empty__switch(Local_Config.Meta_Elements.AntiRagdoll.LockSwitch)
		if RagdollMeta ~= self_.RagdollMetaBackup then
			if RagdollMeta then
				Bot_Humanoid:ChangeState(Enum.HumanoidStateType.Physics)
				MD_.FF:RagdollMode("Add",Bot_Character)
			else
				Bot_Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
				MD_.FF:RagdollMode("Remove",Bot_Character)
			end
			self_.RagdollMetaBackup = RagdollMeta
		end

		--█▄▄ █▀█ █▀▄ █▄█   █▀▀ █▄█ █▀█ █▀█
		--█▄█ █▄█ █▄▀ ░█░   █▄█ ░█░ █▀▄ █▄█
		
		if not MD_.FF:not_empty__switch(Local_Config.Meta_Elements.CustomBodyGyro.LockSwitch) then
			local DIRECC = UnitPathFinding or Local_Config.Self.Target_Unit
			
			if DIRECC and not MD_.FF:not_empty__switch(Local_Config.Meta_Elements.NoAutoRotate.LockSwitch) and Bot_Character:FindFirstChild("RAGDOLL_COMPLEMENTS") == nil then
				DIRECC =  MD_.FF:IsNan(DIRECC,Bot_Root.CFrame.LookVector)*Vector3.new(1,0,1)
				if DIRECC == VE3() then DIRECC = Bot_Root.CFrame.LookVector end
				Body_Gyro.CFrame = CFrame.new(Bot_Root.CFrame.p,Bot_Root.CFrame.p+(DIRECC*255))
				Body_Gyro.MaxTorque = Vector3.new(1,1,1)*900000
			else
				Body_Gyro.MaxTorque = Vector3.new()
			end
		end
		
		Anim_Config.NO_WALK_ANIMATION = NotMove
		Anim_Config:AnimLoop({Current_Force=Local_Config.Self.Current_Force;Using_Change_Anim_Speed=Local_Config.Self.Using_Change_Anim_Speed;Velocity=Bot_Root.Velocity})	
	end
	
end
