--▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒--
--♦♥--MEMORY LIBRARY--♦♥--
local INST 		= Instance.new
local NRAY 		= Ray.new
local RAPM		= RaycastParams.new
local PHYSIPRO 	= PhysicalProperties.new
local VE3 		= Vector3.new
local UDI2		= UDim2.new
local CFN 		= CFrame.new
local TWEEN_IN	= TweenInfo.new
local CFA 		= CFrame.Angles
local M_COS		= math.cos
local M_SIN		= math.sin
local M_RAD		= math.rad
local M_RAN 	= math.random
local M_FLOOR 	= math.floor
local M_SQRT 	= math.sqrt
local M_MA 		= math.max
local M_MI 		= math.min
local M_CL		= math.clamp
local M_ABS		= math.abs
local S_SUB 	= string.sub
local S_FND 	= string.find
local CO_CRE	= coroutine.create
local CO_RES	= coroutine.resume
local NUMSEQ	= NumberSequence.new
local TA_RE 	= table.remove
local TA_IN 	= table.insert
local TA_SO 	= table.sort
local COR_RGB 	= Color3.fromRGB
--♦♥--♦♥--♦♥--♦♥--♦♥--♦♥--
--▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒--

local MD_ = _G._MD

return {
	REAL_Name="Human";MagnitudeDetect=60;Health=3;HipHeight=1.9;WalkSpeed=19;Money=30;Weight=3;Range_MoveTo=4;Change_Anim_Speed_Multi=1;AgentRadius=1.5;AgentHeight=2;Require_Combination=false;Entity_Rarity="Resistence";
	CUSTOM_START=function(_,Local_Config)
		local Bot_Character = Local_Config.Bot_Character
		local Bot_Humanoid = Local_Config.Bot_Humanoid
		local Bot_Root = Local_Config.Bot_Root
		local Anim_Config = Local_Config.Anim_Config
		local Human_TorsoLower = Bot_Character:FindFirstChild("TorsoLower")
		local ticker_amount = 0
		
		local self_ = Local_Config.Self
		local Lock_Bounce_Toggle = Instance.new("BoolValue",Bot_Character)
		Lock_Bounce_Toggle.Parent = Bot_Character
		Lock_Bounce_Toggle.Name="Lock_Bounce_Toggle" 
		Local_Config.Functions:UpdateTeam("Ally")
		Local_Config.Meta_Elements.Sleep={LockSwitch={}};	

		local SkinValue = self_.Attributes.Skin
		if not SkinValue then
			local Skins_description_table_names = {}
			for i,v in pairs (MD_.Skins_description) do table.insert(Skins_description_table_names,i) end
			SkinValue = Skins_description_table_names[math.random(1,#Skins_description_table_names)]
		end
		
		local MyProfileFolder = _Services.RepliStorage.Characters.Profile[SkinValue]
		
		local ClothType = Instance.new("StringValue",Bot_Humanoid) 
		ClothType.Name = "ClothType_String"
		ClothType.Value = "Cloth"
		self_.ClothType = ClothType
		local SkinType = Instance.new("StringValue",Bot_Humanoid) 
		SkinType.Name = "Skin_String"
		SkinType.Value = SkinValue
		self_.SkinType = ClothType
		local VoiceType = INST("StringValue",Bot_Humanoid) 
		VoiceType.Name = "Voice_Style"
		VoiceType.Value = MyProfileFolder:GetAttribute("Voice_Style")
		self_.VoiceType=VoiceType
		local FaceType = INST("StringValue",Bot_Humanoid) 
		FaceType.Name = "Face_Style"
		FaceType.Value = MyProfileFolder:GetAttribute("Face_Style")
		self_.FaceType=FaceType
		
		self_.CanTakeDown = 0
		local Troppy_Type = "Fighter"
		if Troppy_Type == "Fighter" then
			local Events= {}

			local SwordInfo = MD_.Objects_Catalog.Melee.Items["WoodenSword"]

			function self_:LoopAttack()
				local Target_Magnitude = Local_Config.Self.Target_Magnitude
				local Target_Unit = Local_Config.Self.Target_Unit

				if self_.AttackCooldown and self_.AttackCooldown - tick() < 0 then self_.AttackCooldown=nil end
				if Target_Magnitude and not self_.___ACTION_NAME then 
					if Target_Magnitude <= 5 and not self_.AttackCooldown then
						self_.AttackCooldown = tick()+1
						self_.Facial_Config:attack_call_event()
						for i,v in pairs (Events) do v:Disconnect() v=nil end
						--------------
						if self_.SwordModel then self_.SwordModel:Destroy() end
						local SwordModel = game.ReplicatedStorage.Objects.Melee_Items:FindFirstChild(SwordInfo.ObjectName):Clone()
						SwordModel.Parent = Bot_Character
						local ATTACH_TO = Bot_Character:FindFirstChild(SwordModel:GetAttribute("ToolAttachPart"))
						SwordModel.MainPart.CFrame= ATTACH_TO.CFrame
						SwordModel.MainPart.trail.Enabled = true
						self_.SwordModel=SwordModel
						local Motor_6D = MD_.FF:Motor6D(ATTACH_TO,SwordModel.MainPart) 
						Motor_6D.Parent=SwordModel.MainPart
						--------------
						local SwordAnimation = __LA(Bot_Humanoid.Animator, SwordModel:FindFirstChild("Sword_Attack"))
						SwordAnimation:Play(0)

						table.insert(Events,SwordAnimation:GetMarkerReachedSignal("Stop"):Connect(function(value)
							SwordAnimation:Stop()
							if self_.SwordModel then self_.SwordModel:Destroy() end
						end))
						--------------
						local custom_box = {
							CFrame = Bot_Root.CFrame+(Target_Unit*5);
							Size = Vector3.new(3,3,3);
						}
						for i,v in pairs (MD_.FF:hitbox_detector(custom_box,1,false)) do
							if v:FindFirstChild("WeakPointEntity") then 
								Local_Config.Functions:Weak_Point(SwordInfo.Damage,v.WeakPointEntity.Value) 
							end
						end
						--------------
						MD_.FF:PlaySound(Bot_Root,"Other_Whoosh_1",{PlayOnRemove=true;PlaybackSpeed=math.random(1250,1750)/1000})
					end
				end
			end
		end

		function self_:UpdateCharacter()
			if self_.Facial_Config then
				self_.Facial_Config.FE_Rig:Destroy()
				self_.Facial_Config=nil
			end
			if Bot_Character.Parent:FindFirstChild("__Fake__Parts__") then
				Bot_Character.Parent:FindFirstChild("__Fake__Parts__"):Destroy()
			end
			local Facial_Config = MD_.FF:Dress_My_Character({FACE_STYLE=FaceType.Value;SKIN_NAME=SkinType.Value;CHARACTER=Bot_Character;CLOTH_TYPE=ClothType.Value;NoFacial=false,BouncyObjects=true,BouncyValueLock=nil})
			self_.Facial_Config = Facial_Config

			if Bot_Character:FindFirstChild("__Fake__Parts__") then
				Bot_Character:FindFirstChild("__Fake__Parts__").Parent = Bot_Character.Parent
			end
		end self_:UpdateCharacter()
		
		--███████████████████████████████████████████████████████████████████████████████
		--███████████████████████████████████████████████████████████████████████████████
		--███████████████████████████████████████████████████████████████████████████████
	
		local Bot_Module_Extender = {}

		--	███████████████████████████████████████████████████████████████
		--	█─▄▄▄─█▄─██─▄█─▄▄▄▄█─▄─▄─█─▄▄─█▄─▀█▀─▄███▄─▄███─▄▄─█─▄▄─█▄─▄▄─█
		--	█─███▀██─██─██▄▄▄▄─███─███─██─██─█▄█─█████─██▀█─██─█─██─██─▄▄▄█
		--	▀▄▄▄▄▄▀▀▄▄▄▄▀▀▄▄▄▄▄▀▀▄▄▄▀▀▄▄▄▄▀▄▄▄▀▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▀
		
		local oldtick = tick()
		Bot_Module_Extender.CUSTOM_LOOP=function()
			
			-- perfomance for loop face
			local va_s_a = math.max((100-(_Services.Workspace.CurrentCamera.CFrame.p-Bot_Root.CFrame.p).magnitude+10)/100,0)
			ticker_amount+=va_s_a
			if ticker_amount >= 3 or va_s_a > .9 then
				ticker_amount = 0
				oldtick = tick()
				self_.Facial_Config:Face_Loop()
			end
			--
			
			Local_Config.Sleep = MD_.FF:not_empty__switch(Local_Config.Meta_Elements.Sleep.LockSwitch)
			if self_.trigger_damage_tick and self_.trigger_damage_tick - tick() < 0 then self_.trigger_damage_tick = nil end
			
			--███████████████████████████████▀███████████████████████████████████████
			--█▄─▄▄▀██▀▄─██▄─▀█▀─▄██▀▄─██─▄▄▄▄█▄─▄▄─█▄─▄▄─█▄─█─▄█▄─▄▄─█▄─▀█▄─▄█─▄─▄─█
			--██─██─██─▀─███─█▄█─███─▀─██─██▄─██─▄█▀██─▄█▀██▄▀▄███─▄█▀██─█▄▀─████─███
			--▀▄▄▄▄▀▀▄▄▀▄▄▀▄▄▄▀▄▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▀▄▀▀▀▄▄▄▄▄▀▄▄▄▀▀▄▄▀▀▄▄▄▀▀
			
			if Local_Config.Trigger_Damage.Value and not self_.trigger_damage_tick and not self_.Defeated and self_._META_CAN_KEEP_ then
				local customtag = {Name="GetBack" .. tick()}
				self_.trigger_damage_tick = tick()+1.5
				local DamageAmount = Local_Config.Trigger_Damage:GetAttribute("DamageAmount") or 1
				Local_Config.Health -= DamageAmount
				Local_Config.Functions:Update_Health_UI()
				MD_.FF:PlaySound(Bot_Root,"EN_Get_Damage_001",{PlaybackSpeed=1.15;Volume=1.5})
				local BodyVelocity = Instance.new("BodyVelocity",Bot_Root)
				BodyVelocity.MaxForce=Vector3.new(99999,9999e9999,99999)
				BodyVelocity.Velocity=Vector3.new(0,25,0)  + (Bot_Root.CFrame.lookVector*-45) 
				_Services.Debris:AddItem(BodyVelocity,.1)
				Bot_Root.Velocity = Bot_Root.Velocity + (Bot_Root.CFrame.lookVector*-45) + Vector3.new(0,25,0)

				if Local_Config.Health <= 0 then
					self_._Getting_Dead = true	
				end
				-- RAGDOLL
				self_.CanTakeDown += DamageAmount
				if self_.CanTakeDown >= 3 then
					self_.CanTakeDown = 0
					MD_.FF:CreatedParticle("Defeated_Particles",Bot_Root.Position,{CustomParent=Bot_Root;DebrisTime=2;ParticleTime=.1})
					MD_.FF:check__switch({BB=true,TM=Local_Config.Meta_Elements.CantAttack,TS=customtag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=true,TM=Local_Config.Meta_Elements.Ragdoll,TS=customtag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=true,TM=Local_Config.Meta_Elements.Sleep,TS=customtag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=true,TM=Anim_Config,TS=customtag,NN="Custom_Animation_Process",FF=nil}) 
					Anim_Config:AllStopAnimation(0)
					delay(2,function()
						MD_.FF:check__switch({BB=nil,TM=Local_Config.Meta_Elements.CantAttack,TS=customtag,NN=nil,FF=nil}) 
						MD_.FF:check__switch({BB=nil,TM=Local_Config.Meta_Elements.Ragdoll,TS=customtag,NN=nil,FF=nil}) 
						MD_.FF:check__switch({BB=nil,TM=Local_Config.Meta_Elements.Sleep,TS=customtag,NN=nil,FF=nil}) 
						MD_.FF:check__switch({BB=nil,TM=Anim_Config,TS=customtag,NN="Custom_Animation_Process",FF=nil}) 
					end)
				end
				--
			end
			
			--███████████████████████████████████████████████████████████
			--█▄─▄▄▀█▄─▄▄─██▀▄─██▄─▄▄▀███▄─▄▄─█▄─█─▄█▄─▄▄─█▄─▀█▄─▄█─▄─▄─█
			--██─██─██─▄█▀██─▀─███─██─████─▄█▀██▄▀▄███─▄█▀██─█▄▀─████─███
			--▀▄▄▄▄▀▀▄▄▄▄▄▀▄▄▀▄▄▀▄▄▄▄▀▀▀▀▄▄▄▄▄▀▀▀▄▀▀▀▄▄▄▄▄▀▄▄▄▀▀▄▄▀▀▄▄▄▀▀
			
			if self_._Getting_Dead and not self_.___ACTION_NAME then
				self_.Defeated = true	
				
				self_.ClothType.Value="Naked_2"
				self_:UpdateCharacter()
				MD_.FF:PlaySound(Bot_Root,"EN_Dead_002",{PlayOnRemove=true})
				MD_.FF:PlaySound(Bot_Root,"EN_Dead_001",{PlayOnRemove=true})
				MD_.FF:PlaySound(Bot_Root,"Player_Ragdoll",{PlayOnRemove=true})
				self_.Facial_Config:FuckingDie()

				local customtag = {Name="Death"}
				MD_.FF:check__switch({BB=true,TM=Local_Config.Meta_Elements.CantAttack,TS=customtag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=Local_Config.Meta_Elements.Ragdoll,TS=customtag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=Local_Config.Meta_Elements.Sleep,TS=customtag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=Anim_Config,TS=customtag,NN="Custom_Animation_Process",FF=nil}) 
				Anim_Config:AllStopAnimation(0)
				MD_.FF:CreatedParticle("Defeated_Particles",Bot_Root.Position,{CustomParent=Bot_Root;DebrisTime=2;ParticleTime=.1})
			end
			
		end;

		--	███████████████████████████████████████████████████████████████▀█████████████
		--	█▄─▀█▀─▄█─▄▄─█─▄─▄─█▄─▄▄─███─▄─▄─█─▄▄─███─▄─▄─██▀▄─██▄─▄▄▀█─▄▄▄▄█▄─▄▄─█─▄─▄─█
		--	██─█▄█─██─██─███─████─▄█▀█████─███─██─█████─████─▀─███─▄─▄█─██▄─██─▄█▀███─███
		--	▀▄▄▄▀▄▄▄▀▄▄▄▄▀▀▄▄▄▀▀▄▄▄▄▄▀▀▀▀▄▄▄▀▀▄▄▄▄▀▀▀▀▄▄▄▀▀▄▄▀▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀
		
		Bot_Module_Extender.MOVE_TO_TARGET=function()	
			if not MD_.ORGY_MODE then
				self_:LoopAttack()
			end
		end;
		
		--███████████████████████████████████████████████████████████████████████████████
		--███████████████████████████████████████████████████████████████████████████████
		--███████████████████████████████████████████████████████████████████████████████
		
		return Bot_Module_Extender
	end;
	Animation_Events={	
	};
	Conditions_For_Combinations={
	};
};
]=]
