local NUMSEQ	= NumberSequence.new
local TA_RE 	= table.remove
local TA_IN 	= table.insert
local TA_SO 	= table.sort
local COR_RGB 	= Color3.fromRGB
--♦♥--♦♥--♦♥--♦♥--♦♥--♦♥--
--▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒--

local module = {}

local Running = Enum.HumanoidStateType.Running
local Falling = Enum.HumanoidStateType.FallingDown
local FreeFalling = Enum.HumanoidStateType.Freefall
local Jumping = Enum.HumanoidStateType.Jumping
local Landed = Enum.HumanoidStateType.Landed

local MD_ = _G._MD
local FootStepSFX_Folder = _Services.RepliStorage:FindFirstChild("Sounds"):FindFirstChild("0_FootStepSFX")

--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘
--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘
function module:Setup_Animations(Character,Style,C)
	local C = C or {}
	local Humanoid = Character.Humanoid
	
	local Anim_Config = {}
	Anim_Config.AnimationsFolder = _Services.RepliStorage.Animations.Characters:FindFirstChild(Style)
	Anim_Config.States={}
	Anim_Config.Animations={}
	Anim_Config.Custon_Animation_Events={}
	Anim_Config.custom_animation={}
	Anim_Config.DONT_STOP_ANIMATIONS={	
		["FlapWing"]=function(AnimName) end;
		["Attack2Anim"]=function(AnimName) end;
		["AttackAnim"]=function(AnimName) end;
		["Attack2JumpAnim"]=function(AnimName) end;
		["Attack3_StartAnim"]=function(AnimName) end;
		["Invisible"]=function(AnimName) end;
		["FallSpinAnim"]=function(AnimName) end;
		["DeadEnough"]=function(AnimName) end;
		["KnockeOutAnim"]=function(AnimName) end;
		["Masturbate_Loop_1"]=function(AnimName) end;
		["Masturbate_Start"]=function(AnimName) end;
		["Masturbate_Start_Alternative"]=function(AnimName) end;
		["Masturbate_Loop_1_Alternative"]=function(AnimName) end;
		["JumpAlternativeAnim"]=function(AnimName) return AnimName == "WalkAnim" or AnimName == "IdleAnim"  end;
		["JumpAnim"]=function(AnimName) return AnimName == "WalkAnim" or AnimName == "IdleAnim"  end;
		["DoubleJumpAnim"]=function(AnimName) return AnimName == "WalkAnim" or AnimName == "IdleAnim" end;
		["BackJumpAnim"]=function(AnimName) return AnimName == "WalkAnim" or AnimName == "IdleAnim" end;
		["NakedJumpAnim"]=function(AnimName) return AnimName == "WalkAnim" or AnimName == "IdleAnim" end;
	}
	Anim_Config.DONT_TOUCH_MY_ANIMATION={}
	Anim_Config.Custom_Animation_Process={}
	
	local EventAction,CurrentAnimation,Swimming,CurrentAnimation_instance,Ticker_Prevent_Y_Clip
	Anim_Config.Current_Force = 25
	Anim_Config.Can_Step_SFX = true
	
	--compile animations to get loaded animations (prevent cut animations)
	function Anim_Config:Animation_Setup_Folder(_replace_folder_anim,_reset)
		Anim_Config.custom_animation={}
		for _,Animation in pairs(Anim_Config.AnimationsFolder:GetChildren()) do
			if Animation:IsA("Animation") then
				local anim_replaced = _replace_folder_anim and _replace_folder_anim:FindFirstChild(Animation.Name)
				Animation = anim_replaced or Animation
				Anim_Config.Animations[Animation.Name] = __LA(Humanoid.Animator, Animation)
			end
		end
		if _reset then
			Anim_Config:Restart_Current_Animation()
		end
	end
	-- 
	Anim_Config:Animation_Setup_Folder()

	--repeat animation
	function Anim_Config:Restart_Current_Animation()
		if CurrentAnimation then Anim_Config:PlayAnimation(CurrentAnimation,true) end
	end
	
	--restart all animations
	function Anim_Config:AllStopAnimation(transition,animation_follow)
		local PlayingAnimations = __GAT(Humanoid)
		for _,PlayingAnimation in pairs(Anim_Config.Animations) do
			if not Anim_Config.DONT_TOUCH_MY_ANIMATION[PlayingAnimation.Name] then
				PlayingAnimation:Stop(transition)
				PlayingAnimation = __LA(Humanoid.Animator, PlayingAnimation.Animation)
			end
		end
		if PlayingAnimations then
			for _,PlayingAnimation in pairs(PlayingAnimations) do
				if Anim_Config.Animations[PlayingAnimation.Name] and Anim_Config.Animations[PlayingAnimation.Name] ~= animation_follow and not Anim_Config.DONT_TOUCH_MY_ANIMATION[PlayingAnimation.Name] then
					PlayingAnimation:Stop(transition)
				end
			end
		end
	end
	
	--stop animation
	function Anim_Config:StopAnimation(AnimName)
		local PlayingAnimations = __GAT(Humanoid)
		if PlayingAnimations then
			for _,PlayingAnimation in pairs(PlayingAnimations) do
				if Anim_Config.Animations[PlayingAnimation.Name] and (not Anim_Config.DONT_STOP_ANIMATIONS[PlayingAnimation.Name] or Anim_Config.DONT_STOP_ANIMATIONS[PlayingAnimation.Name](AnimName))  then
					PlayingAnimation:Stop()
				end
			end
		end
	end
	
	--play animation
	function Anim_Config:PlayAnimation(AnimName,Replace,transition)
		if MD_.FF:not_empty__switch(Anim_Config.Custom_Animation_Process) then return end
		local next_anim = Anim_Config.custom_animation[AnimName] or Anim_Config.Animations[AnimName]

		CurrentAnimation = AnimName
		Anim_Config.Current_Animation_Name=AnimName
		if CurrentAnimation_instance == next_anim and not Replace then return end
		if not Replace then
			CurrentAnimation_instance = next_anim
			Anim_Config:StopAnimation(AnimName)
		end
		if next_anim then
			if EventAction then 
				EventAction:Disconnect() 
				EventAction = nil 
			end
			EventAction = next_anim:GetMarkerReachedSignal("Function"):Connect(function(value)
				if value == "Step" and Anim_Config.Can_Step_SFX and Anim_Config.Current_Force > 5 and Character.HumanoidRootPart:IsDescendantOf(_Services.Workspace) and not Anim_Config.States.Falling then
					local FloorMaterial = tostring(Humanoid.FloorMaterial.Name)
					local TypeFoot = (FootStepSFX_Folder:FindFirstChild(FloorMaterial) and FloorMaterial) or "Default"
					MD_.FF:PlaySound(Character.HumanoidRootPart,TypeFoot,{PlayOnRemove=true;PlaybackSpeed=(((M_RAN()*65)%50)/100) + .8;Search_Sound=FootStepSFX_Folder})
				end
				if Anim_Config.Custon_Animation_Events[value] then
					Anim_Config.Custon_Animation_Events[value]()
				end
			end)
			next_anim:Play(transition)
		end

		return next_anim
	end
	
	--connection event
	Humanoid.StateChanged:Connect(function(Old,New)
		if New == Enum.HumanoidStateType.Running then
			Anim_Config.States.Jumping=false
			Anim_Config.States.Falling=false
		elseif New == Jumping then
			Anim_Config.States.Jumping=true
			Anim_Config.States.Falling=true
		--	Anim_Config:PlayAnimation("JumpAnim")
		elseif New == Falling or New == FreeFalling then
			Anim_Config.States.Jumping=false
			Anim_Config.States.Falling=true
			if Anim_Config.Animations.FallAnim then
				Anim_Config:PlayAnimation("FallAnim")
			end
		elseif New == Landed then
			Anim_Config.States.Jumping=false
			Anim_Config.States.Falling=false
		end
	end)
	
	--seat animation
	if Anim_Config.Animations.Seat then
		local custom_seat_tag = {Name="Seat"}
		local function onSeated(isSeated, seat)
			if isSeated then
				MD_.FF:check__switch({BB=true,TM=Anim_Config,TS=custom_seat_tag,NN="Custom_Animation_Process",FF=nil})
				Anim_Config:AllStopAnimation(.15)
				Anim_Config.Animations.Seat:Play()
			else
				MD_.FF:check__switch({BB=nil,TM=Anim_Config,TS=custom_seat_tag,NN="Custom_Animation_Process",FF=nil})
				Anim_Config:AllStopAnimation(.15)
				Anim_Config.Animations.Seat:Stop()
				Anim_Config:Restart_Current_Animation()
			end
		end
		Humanoid.Seated:Connect(onSeated)
	else
		Humanoid.Seated:Connect(function()
			Humanoid.Sit=false
		end)
	end
	--loop
	function Anim_Config:AnimLoop(T)
		local Current_Force,Using_Change_Anim_Speed,Velocity = T.Current_Force,T.Using_Change_Anim_Speed,T.Velocity
		
		if not Anim_Config.States.Jumping and not Anim_Config.States.Falling then
			Using_Change_Anim_Speed = Using_Change_Anim_Speed or 1
			Anim_Config.Current_Force=Current_Force
			if Anim_Config.Current_Force > 5 then
				if Anim_Config.RunningToggle then
					Anim_Config:PlayAnimation("RunningAnim")
				else
					if Anim_Config.Backward_Walk then
						Anim_Config:PlayAnimation("BackWalkAnim",nil,.1)
					else
						Anim_Config:PlayAnimation("WalkAnim")
					end
				end
				Anim_Config.WalkingAnim=true
				CurrentAnimation_instance:AdjustSpeed((Current_Force/15.74)*Using_Change_Anim_Speed)
			else
				Anim_Config:PlayAnimation("IdleAnim")
				Anim_Config.WalkingAnim=false
				if Anim_Config.Idle_WalkSpeed_Depends then
					CurrentAnimation_instance:AdjustSpeed(Humanoid.WalkSpeed/12.74)
				end
				
			end
		elseif Anim_Config.States.Falling then
			if math.abs(Velocity.Y) < 2 then
				if Ticker_Prevent_Y_Clip and Ticker_Prevent_Y_Clip - tick() < 0 then
					Ticker_Prevent_Y_Clip = nil
					Humanoid:ChangeState(Enum.HumanoidStateType.Landed)
				elseif not Ticker_Prevent_Y_Clip then
					Ticker_Prevent_Y_Clip = tick()+.1
				end
			else
				Ticker_Prevent_Y_Clip = nil
			end
		else
			Anim_Config.WalkingAnim=false
		end
	end
	
	Anim_Config:PlayAnimation("IdleAnim")
	
	return Anim_Config
end
--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘
--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘--◘◘

return module
]=]
SRC[6395]=[==[local _Services = {
	["Workspace"] = game:GetService("Workspace");
	["Lighting"] = game:GetService("Lighting");
	["Player"] = game:GetService("Players");
	["Run"] = game:GetService("RunService");
	["Debris"] = game:GetService("Debris");
	["UserInput"] = __VUIS();
	["Tween"] = game:GetService("TweenService");
	["Physics"] = game:GetService("PhysicsService");
	["StarterGui"] = game:GetService("StarterGui");
	["StarterPlayer"] = game:GetService("StarterPlayer");
	["RepliStorage"] = game:GetService("ReplicatedStorage");
	["ServerStorage"] = game:GetService("ServerStorage");
	["Chat"] = game:GetService("Chat");
