--♦♥--MEMORY LIBRARY--♦♥--
local INST 		= Instance.new
local NRAY 		= Ray.new
local RAPM		= RaycastParams.new
local PHYSIPRO 	= PhysicalProperties.new
local VE3 		= Vector3.new
local UDI2		= UDim2.new
local CFN 		= CFrame.new
local TWEEN_IN	= TweenInfo.new
local CFA 		= CFrame.Angles
local M_COS		= math.cos
local M_SIN		= math.sin
local M_RAD		= math.rad
local M_RAN 	= math.random
local M_FLOOR 	= math.floor
local M_SQRT 	= math.sqrt
local M_MA 		= math.max
local M_MI 		= math.min
local M_CL		= math.clamp
local M_ABS		= math.abs
local S_SUB 	= string.sub
local S_FND 	= string.find
local CO_CRE	= coroutine.create
local CO_RES	= coroutine.resume
local NUMSEQ	= NumberSequence.new
local TA_RE 	= table.remove
local TA_IN 	= table.insert
local TA_SO 	= table.sort
local COR_RGB 	= Color3.fromRGB
--♦♥--♦♥--♦♥--♦♥--♦♥--♦♥--
--▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒▒--

local module = {}
local MD_ = _G._MD

local scene_tag = {Name="Scene_Archiever"}

function module:LoadAnimation(Humanoid,Animation) -- lazy function :V
	local Animator = Humanoid:FindFirstChild("Animator")
	return __LA(Animator, Animation)
end

--███████████████████████████████████████████████████████████████████████████████████████████████
--█─▄▄▄▄█─▄▄▄─█▄─▄▄─█▄─▀█▄─▄█▄─▄▄─███─▄▄▄─█─▄▄─█▄─▀█▄─▄█─▄─▄─█▄─▄▄▀█─▄▄─█▄─▄███▄─▄███▄─▄▄─█▄─▄▄▀█
--█▄▄▄▄─█─███▀██─▄█▀██─█▄▀─███─▄█▀███─███▀█─██─██─█▄▀─████─████─▄─▄█─██─██─██▀██─██▀██─▄█▀██─▄─▄█
--▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀▀▄▄▄▀▀▄▄▀▄▄▀▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▀▄▄▀

function module:Start_Scene(Local_Config,AnimationConfig,Team)
	local TBC____ = Local_Config.Target_Entity
	if Local_Config and not TBC____.Scene_Config.DebounceScene and TBC____.Bot_Humanoid.Health > 0 then
		TBC____.Scene_Config.DebounceScene = true
		local NextPos,Model
		
		--█▀▀▀ █▀▀ ▀▀█▀▀ 　 █▀▀█ █▀▀█ █▀▀ 
		--█░▀█ █▀▀ ░░█░░ 　 █░░█ █░░█ ▀▀█ 
		--▀▀▀▀ ▀▀▀ ░░▀░░ 　 █▀▀▀ ▀▀▀▀ ▀▀▀
		
		if not TBC____.Scene_Config.Current_Position then
			local ROOT_POSITION = TBC____.Bot_Root.CFrame.p -- origin
			NextPos = ROOT_POSITION + Vector3.new(0,2,0)
			local raycastParams = RAPM()
			raycastParams.FilterDescendantsInstances = {TBC____.Bot_Character,Local_Config.Bot_Character}
			raycastParams.FilterType = Enum.RaycastFilterType.Blacklist
			local raycastResult =  MD_.FF:CastUntilHitWithHumanoid(NextPos,NextPos+VE3(0,-15,0),raycastParams)
			if raycastResult and raycastResult.Position and raycastResult.Instance then
				local Unit = (ROOT_POSITION-raycastResult.Position).unit
				local Magnitude = (ROOT_POSITION-raycastResult.Position).magnitude
				NextPos = ROOT_POSITION-(Unit*M_CL(Magnitude,0,55))
				TBC____.Scene_Config.Current_Position = NextPos
			else
				wait(.1)
				TBC____.Scene_Config.DebounceScene = false
				return false
			end
		else
			NextPos = TBC____.Scene_Config.Current_Position
		end
		
		--█████■████
		--█████■████
		--█████■████
		-- this function is only repeated once
		if not TBC____.Scene_Config.Local_Config_Log then
			TBC____.Scene_Config.Local_Config_Log = {}
			
			if not TBC____.ImPlayer then -- if the player is not a bot, use the same method to disappear bots
				-- dissapear target with bot
				MD_.FF:check__switch({BB=true,TM=TBC____.Meta_Elements.AntiRagdoll,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=TBC____.Meta_Elements.CantAttack,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=TBC____.Anim_Config,TS=scene_tag,NN="Custom_Animation_Process",FF=nil}) 
				TBC____.Anim_Config:AllStopAnimation(0)
				
				TBC____.Bot_Character.Parent.Parent = _G.Lighting_Debris
			end		
		end
		-- changing the combinations amount of entities for the scenes
		TBC____.Current_Combination[Local_Config.Bot_Config.REAL_Name].Amount += 1
		-- add bot to log
		TA_IN(TBC____.Scene_Config.Local_Config_Log,{Local_Config=Local_Config})
		-- remove other scene model
		if TBC____.Scene_Config.Scene_Model then TBC____.Scene_Config.Scene_Model:Destroy() TBC____.Scene_Config.Scene_Model=nil end
		--█████■████
		--█████■████
		--█████■████
		-- FINISH SCENE FUNCTION
		function TBC____.Scene_Config:Stop_Scene()
			TBC____.Cooldown = true
			--remove the entire rig escene
			if TBC____.Scene_Config.Scene_Model then TBC____.Scene_Config.Scene_Model:Destroy() TBC____.Scene_Config.Scene_Model=nil end
			-- makes bots reappear as they were before and adds a cooldown tag
			for i,v in pairs (TBC____.Scene_Config.Local_Config_Log) do
				if v.Local_Config.Bot_Root and v.Local_Config.Bot_Root:IsDescendantOf(game) then
					v.Local_Config.Bot_Character.Parent.Parent = v.Local_Config.SavedParent
					local customtag = {Name="Scene_Archiever" .. tick()}
					MD_.FF:check__switch({BB=true,TM=v.Local_Config.Meta_Elements.NoMovement,TS=customtag,NN=nil,FF=nil}) 
					delay(3,function()
						MD_.FF:check__switch({BB=nil,TM=v.Local_Config.Meta_Elements.NoMovement,TS=customtag,NN=nil,FF=nil}) 
					end)
					v.Local_Config.Self.My_Scene_Model = nil
					v.Local_Config.Self.Joined_Party = false
					
					MD_.FF:check__switch({BB=nil,TM=v.Local_Config.Meta_Elements._STATIC_,TS=scene_tag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=nil,TM=v.Local_Config.Meta_Elements.AntiRagdoll,TS=scene_tag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=nil,TM=v.Local_Config.Meta_Elements.CantAttack,TS=scene_tag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=nil,TM=v.Local_Config.Meta_Elements.NoAutoRotate,TS=scene_tag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=nil,TM=v.Local_Config.Meta_Elements.NoMovement,TS=scene_tag,NN=nil,FF=nil}) 
					MD_.FF:check__switch({BB=nil,TM=v.Local_Config.Anim_Config,TS=scene_tag,NN="Custom_Animation_Process",FF=nil}) 

					v.Local_Config.Anim_Config:Restart_Current_Animation(0)
				end
			end
			-- if the main target is a bot or not it will change the type of protocol for appear
			if TBC____.ImPlayer then -- disspear by player
				local Character,LIBRARY_MODULE = MD_.FF:Get_Player_Character(true)
				if LIBRARY_MODULE then 
					LIBRARY_MODULE.FF:Break_Scene_UI("END")
					MD_.FF:check__switch({BB=nil,TM=LIBRARY_MODULE.Meta_Elements.Anchored_State,TS=MD_.Meta_Elements.Scenes_PLAY,NN=nil,FF=function()LIBRARY_MODULE.FF:Scene_Updated_Meta(nil) end}) 
				end
			else
				MD_.FF:check__switch({BB=nil,TM=TBC____.Meta_Elements.AntiRagdoll,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=nil,TM=TBC____.Meta_Elements.CantAttack,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=nil,TM=TBC____.Anim_Config,TS=scene_tag,NN="Custom_Animation_Process",FF=nil}) 
				TBC____.Anim_Config:Restart_Current_Animation(0)
				if TBC____.Bot_Root and TBC____.Bot_Root:IsDescendantOf(game) then
					TBC____.Bot_Character.Parent.Parent = TBC____.SavedParent
				end
			end
			-- cooldown for the target
			delay(3,function()
				TBC____.Cooldown=false
			end)
			-- reset
			MD_.FF:Reset_Current_Combination(TBC____)
			for i,v in pairs (TBC____.Scene_Config.Local_Config_Log) do
				v.Local_Config.Target_Entity=nil
			end
			TBC____.Scene_Config={}	
		end
		--█████■████
		--█████■████
		--█████■████
		-- add the rig scene and position it according to the camera angle and with raycast
		-- SET _ SCENE _ POSITION
		
		do
			local ORModel = _Services.RepliStorage.Animations.Scenes:FindFirstChild(AnimationConfig.AnimModel)
			Model = ORModel.Rig:Clone()
			Model.Parent = _Services.Workspace
			Model.Name = "__SCENE__".. AnimationConfig.AnimModel .. "__SEX__"
			local MainSceneryPart = Model:FindFirstChild("MAIN_SCENERY_PART")
			Model.PrimaryPart=MainSceneryPart
			TBC____.Scene_Config.Scene_Model=Model
			MD_.FF:Install_Scene(ORModel,Model,TBC____,{Team=Team})
			
			-- rig scene angle offset
			local unit_camera = (NextPos-_Services.Workspace.CurrentCamera.CFrame.p).unit
			local angle_extra = CFA(0,0,0)			
			if MainSceneryPart:FindFirstChild("ANGLE_START") then angle_extra=MainSceneryPart:FindFirstChild("ANGLE_START").Value end
			-- final set cframe
			local offset_y_main = (MainSceneryPart.Size.Y/2)
			local A=Model:GetExtentsSize()
			spawn(function()
				MainSceneryPart.CFrame=((CFN(NextPos,NextPos+(unit_camera*VE3(100,0,100)))*angle_extra)+VE3(0,offset_y_main,0))
				if TBC____.Scene_Config.TimeOffParticles and TBC____.Scene_Config.TimeOffParticles - tick() < 0 then TBC____.Scene_Config.TimeOffParticles = nil end
				if not TBC____.Scene_Config.TimeOffParticles then
					TBC____.Scene_Config.TimeOffParticles = tick() + 1
					MD_.FF:PlaySound(MainSceneryPart,"Player_GetRaped2",{PlayOnRemove=true})
					if math.random(1,100) == 90 then
						MD_.FF:PlaySound(MainSceneryPart,"PartyScene.mp3",{PlayOnRemove=true})
						MD_.FF:CreatedParticle("CONFETI2",nil,{BASE_CFRAME=MainSceneryPart.CFrame*CFN(0,A.Y/2.5,0);ParticleTime=.5;BASE_PART=true;BASE_SIZE=A*VE3(.5,0,.5)})
					else
						MD_.FF:CreatedParticle("HEART2",nil,{BASE_CFRAME=MainSceneryPart.CFrame*CFN(0,A.Y/2.5,0);ParticleTime=.2;BASE_PART=true;BASE_SIZE=A*VE3(.5,0,.5)})
					end
					
				end
				--
				
				_G.Modules_Poof_Manage({CF=MainSceneryPart.CFrame*CFN(0,A.Y/2,0),SIZE=A*VE3(1,.65,1),AMOUNT=M_RAN(8,13);RANGE=.15;STYLE="Style2";TIME=1.5;NEXT_CF_RANGE=8.5;SIZE_MULTIER=3;TRANSPARENCY_FUNC=function() return 0 end;EASINGSTYLE=Enum.EasingStyle.Sine,EASINGDIRECTION=Enum.EasingDirection.Out})
			end)
		end
		--█████■████
		--█████■████
		--█████■████
		-- if player
		--the protocol to make the player invisible
		--Unlike the function in the beginning, this function has to be repeated to reset the scene preferences function
		if TBC____.ImPlayer then
			local Character,LIBRARY_MODULE = MD_.FF:Get_Player_Character(true)
			if LIBRARY_MODULE then 
				MD_.FF:check__switch({BB=true,TM=LIBRARY_MODULE.Meta_Elements.Anchored_State,TS=MD_.Meta_Elements.Scenes_PLAY,NN=nil,FF=function()LIBRARY_MODULE.FF:Scene_Updated_Meta(true) end}) 
				LIBRARY_MODULE.FF:Break_Scene_UI("START",TBC____.Scene_Config)
			end
		end
		-- makes bots disappear
		for i,v in pairs (TBC____.Scene_Config.Local_Config_Log) do
			v.Local_Config.Self.My_Scene_Model = Model
			if not v.Teleported then
				v.Teleported = true
				--
				v.Local_Config.Self.Joined_Party = true
				MD_.FF:check__switch({BB=true,TM=v.Local_Config.Meta_Elements._STATIC_,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=v.Local_Config.Meta_Elements.AntiRagdoll,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=v.Local_Config.Meta_Elements.CantAttack,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=v.Local_Config.Meta_Elements.NoAutoRotate,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=v.Local_Config.Meta_Elements.NoMovement,TS=scene_tag,NN=nil,FF=nil}) 
				MD_.FF:check__switch({BB=true,TM=v.Local_Config.Anim_Config,TS=scene_tag,NN="Custom_Animation_Process",FF=nil}) 
				v.Local_Config.Anim_Config:Restart_Current_Animation()
				v.Local_Config.Anim_Config:AllStopAnimation(0)
				--
				v.Local_Config.Bot_Character.Parent.Parent = _G.Lighting_Debris
			end
		end
		TBC____.Scene_Config.Scene_Active = true
		wait(.1)
		TBC____.Scene_Config.DebounceScene = false
		return true
	end
	return false
end

--█████████████████▀██████████████████████████████████████████████████████████████████████████████████████
--█▄─▄▄▀██▀▄─██─▄▄▄▄█▄─▄▄▀█─▄▄─█▄─▄███▄─▄█████─▄▄▄─█─▄▄─█▄─▀█▄─▄█─▄─▄─█▄─▄▄▀█─▄▄─█▄─▄███▄─▄███▄─▄▄─█▄─▄▄▀█
--██─▄─▄██─▀─██─██▄─██─██─█─██─██─██▀██─██▀███─███▀█─██─██─█▄▀─████─████─▄─▄█─██─██─██▀██─██▀██─▄█▀██─▄─▄█
--▀▄▄▀▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▀▀▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀▀▄▄▄▀▀▄▄▀▄▄▀▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▀▄▄▀

function module:RagdollMode(Tipo,Char)
	-- add ragdoll effects
	if Tipo == "Add" then
		local SIZE = nil
		
		local RAGDOLL_COMPLEMENTS = INST("Folder",Char)
		RAGDOLL_COMPLEMENTS.Name="RAGDOLL_COMPLEMENTS"
		
		local MyHead = Char:FindFirstChild("Head")
		local Human = Char:FindFirstChildOfClass("Humanoid") 
		local IsHuman = Human:FindFirstChild("IsHuman")
		if IsHuman then
			SIZE = .35
		end
		local HumanoidRootPart = Char:FindFirstChild("HumanoidRootPart") 
		Human.RequiresNeck = false
		
		--Motor6D_RAGDOLL_EVENTS
		local GetAscentConnections = MD_.FF:GetAscent(Char)
		for _,primary in pairs (GetAscentConnections) do
			local primary_padre = primary.Padre
			local primary_pieza = primary.Pieza
			--- no collision for each part
			for _,secondary in pairs (GetAscentConnections) do
				local secondary_padre = secondary.Padre
				if secondary_padre:FindFirstChild("NO_RAGDOLL") then -- solo no tiene colision para los objetos con el noRagdoll
					if secondary_padre ~= primary_padre then
						local NoCol = INST("NoCollisionConstraint", RAGDOLL_COMPLEMENTS)
						NoCol.Part0 = primary_padre
						NoCol.Part1 = secondary_padre
						NoCol.Name = "NCC_" .. primary_padre.Name .. ">" .. secondary_padre.Name
					end
				end
			end
			local NoCol = INST("NoCollisionConstraint", RAGDOLL_COMPLEMENTS)
			NoCol.Part0 = primary_padre
			NoCol.Part1 = primary_pieza
			NoCol.Name = "NCC_" .. primary_padre.Name .. ">" .. primary_pieza.Name
			
			--- fake part
			if primary_pieza ~= HumanoidRootPart and primary_pieza ~= MyHead and primary_pieza and primary_pieza.Name and primary_pieza:FindFirstChild("NO_RAGDOLL") == nil then
				--- connections
				MD_.FF:ConnectPart(primary_padre,primary_pieza,primary,RAGDOLL_COMPLEMENTS)
				local Part_Fake_Collide = INST("Part")
				Part_Fake_Collide.Name = "FakePartB)" .. primary_pieza.Name
				Part_Fake_Collide.CFrame = primary_pieza.CFrame
				Part_Fake_Collide.Size = primary_pieza.Size * (SIZE or .65)

				Part_Fake_Collide.Transparency = 1
				Part_Fake_Collide.Color = COR_RGB(255,0,0)
				Part_Fake_Collide.Parent = RAGDOLL_COMPLEMENTS
				Part_Fake_Collide.CanCollide = true
				
				local Ignore_RayCast_Value = INST("IntValue",Part_Fake_Collide)
				Ignore_RayCast_Value.Name="Ignore_RayCast_Value"
				
				local Propiedades = PHYSIPRO (5, 0, 0, 0, 100)
				Part_Fake_Collide.CustomPhysicalProperties = Propiedades

				local weld = MD_.FF:Weld(Part_Fake_Collide,primary_pieza) 
				weld.Parent = Part_Fake_Collide
			end
		end
		---
		local X,Y,Z = math.sin(math.random()-.5),math.sin(math.random()-.5),math.sin(math.random()-.5)
		if MyHead then
			MyHead.Velocity = MyHead.Velocity+Vector3.new(X*5,Y*5,Z*5);
		end
	elseif Tipo == "Remove" then -- remove ragdoll effects
		local MyHead = Char:FindFirstChild("Head")
		local HumanoidRootPart = Char:FindFirstChild("HumanoidRootPart")
		local Human = Char:FindFirstChildOfClass("Humanoid")
		if Human.Health <= 0 then return end
		local RAGDOLL_COMPLEMENTS = Char:FindFirstChild("RAGDOLL_COMPLEMENTS")
		if RAGDOLL_COMPLEMENTS then
			RAGDOLL_COMPLEMENTS:Destroy()
		end

		for _,d in pairs(Char:GetDescendants()) do
			if d:IsA("Attachment") then
				if S_FND(d.Name,"_Attachment_Remove_SCRIPT_REMOVE") then
					d:Destroy()
				end
			elseif d:IsA("Motor6D") then
				d.Enabled = true
			end
		end

		Human.RequiresNeck = true
		
	end
	return true
end

--█████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████
--█▄─▄▄▀█▄─▄▄─█─▄▄▄─█─▄▄─█▄─▄▄▀██▀▄─██─▄─▄─█▄─▄█─▄▄─█▄─▀█▄─▄███▄─▄▄─██▀▄─██▄─▄▄▀█─▄─▄─█─▄▄▄▄████████─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─█
--██─██─██─▄█▀█─███▀█─██─██─▄─▄██─▀─████─████─██─██─██─█▄▀─█████─▄▄▄██─▀─███─▄─▄███─███▄▄▄▄─████████▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄█
--▀▄▄▄▄▀▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▀▄▄▀▄▄▀▄▄▀▄▄▀▀▄▄▄▀▀▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀▀▀▄▄▄▀▀▀▄▄▀▄▄▀▄▄▀▄▄▀▀▄▄▄▀▀▄▄▄▄▄▀██████▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀

function module:Fake_Parts(Rig,Parts,Bouncy_Feature,BouncyValueLock)

	local Colors_Table = {COR_RGB(64, 211, 255),COR_RGB(150, 80, 255),COR_RGB(168, 124, 255),COR_RGB(17, 255, 76),COR_RGB(181, 120, 255),COR_RGB(255, 193, 93),COR_RGB(255, 138, 191),COR_RGB(255, 119, 29),COR_RGB(255, 58, 61)} 
	local CurrentColor1 = Colors_Table[M_RAN(1,#Colors_Table)]
	
	--in case of re skin
	if Rig:FindFirstChild("__Fake__Parts__") then
		Rig:FindFirstChild("__Fake__Parts__"):Destroy()
	end
	
	for i,v in pairs (Rig:GetChildren()) do
		if v:IsA("BasePart") then
			if v:FindFirstChild("Visible") == nil then
				v.Transparency=1
			end
			v.CustomPhysicalProperties = PHYSIPRO(0,0,0,0,0)
		end
	end
	local HumanoidRootPart = Rig:FindFirstChild("HumanoidRootPart") or Rig:FindFirstChild("MAIN_SCENERY_PART")
	if HumanoidRootPart then
		HumanoidRootPart:SetAttribute("Ignore_RayCast_Value_For_Target_Scene",true)
		HumanoidRootPart.RootPriority=10
		local Weight = HumanoidRootPart:GetAttribute("Weight") or 2
		HumanoidRootPart.CustomPhysicalProperties = PHYSIPRO(Weight,0,0,0,0)
	end
	
	local DecoFolder = INST("Folder",Rig)
	DecoFolder.Name = "__Fake__Parts__"
	
	local Lock_Bounce = {Value=false}
	if DecoFolder.Parent:FindFirstChild("Lock_Bounce_Toggle") then
		Lock_Bounce = DecoFolder.Parent:FindFirstChild("Lock_Bounce_Toggle")
	elseif BouncyValueLock then
		Lock_Bounce = BouncyValueLock
	end

	---create the groups----
	local GroupsName={}
	for _,v in pairs(Parts:GetChildren()) do -- {left_arm={};right_arm={}}
		if v.Name ~= "__Random__" then 
			if not GroupsName[v.Name] then
				GroupsName[v.Name] = {}
			end
			TA_IN(GroupsName[v.Name],v)
		end
	end
	---__RANDOM__
	for _,__Random__ in pairs (Parts:GetChildren()) do
		if __Random__.Name == "__Random__" then
			local GetParts = __Random__:GetChildren()
			local ChooseRandom = GetParts[M_RAN(1,#GetParts)]
			for _,v in pairs(ChooseRandom:GetChildren()) do
				if not GroupsName[v.Name] then
					GroupsName[v.Name] = {}
				end
				TA_IN(GroupsName[v.Name],v)
			end
		end
	end

	local Bouncy_Objects={}
	local Bouncy_Objects_Functions={}
	---random Parts to 
	for _,group in pairs (GroupsName) do
		local PickRandom = group[M_RAN(1,#group)]
		local RealPart = Rig:FindFirstChild(PickRandom.Name)
		if RealPart then
			local Clone_DecoPart = PickRandom:Clone()
			Clone_DecoPart.Parent = DecoFolder
			local MainPart = Clone_DecoPart:FindFirstChild("MainPart")

			for _,sub_parts in pairs(Clone_DecoPart:GetDescendants()) do
				--default propierties
				if sub_parts:IsA("BasePart") then
					if not sub_parts:GetAttribute("Transparency") then
						local t = sub_parts.Transparency
						sub_parts:SetAttribute("Transparency",t)
					end
					if sub_parts.Name == "ColorParts" then
						sub_parts.Color = CurrentColor1
					end
					if sub_parts:FindFirstChild("INVISIBLE") or sub_parts:GetAttribute("INVISIBLE") == true  then
						sub_parts.Transparency=1
					end
					sub_parts.CanCollide = false
					sub_parts.CanTouch = false
					sub_parts.Anchored = false
		
					sub_parts.CustomPhysicalProperties = PHYSIPRO(0,0,0,0,0)
					if not sub_parts:GetAttribute("OR_Transparency") then
						sub_parts:SetAttribute("OR_Transparency",sub_parts.Transparency)
					end
				end
				
				if sub_parts:FindFirstChild("CustomWeld") then-- custom weld
					MD_.FF:Weld(sub_parts:FindFirstChild("CustomWeld").Value,sub_parts)
				elseif sub_parts:FindFirstChild("Bounce_Propierties") and Bouncy_Feature then	 -- bouncy object
					local PRO_VAL = sub_parts:FindFirstChild("Bounce_Propierties")
					local Origin = MainPart
					local Update_Me_Part
					
					if sub_parts:FindFirstChild("Bounce_Propierties"):FindFirstChild("Custom_Update_Cast") then
						Update_Me_Part = sub_parts:FindFirstChild("Bounce_Propierties"):FindFirstChild("Custom_Update_Cast").Value
					end
					if sub_parts:FindFirstChild("Bounce_Propierties"):FindFirstChild("Custom_Pivot") then
						Origin = sub_parts:FindFirstChild("Bounce_Propierties"):FindFirstChild("Custom_Pivot").Value
					end
					local Offset = Origin.CFrame:ToObjectSpace(sub_parts.CFrame)
					TA_IN(Bouncy_Objects,{
						Part=sub_parts;Origin=Origin;Offset=Offset;Update_Me_Part=Update_Me_Part;
						Friction_POSITION=PRO_VAL:GetAttribute("Friction_POSITION");K_POSITION=PRO_VAL:GetAttribute("K_POSITION");Friction_ROTATE=PRO_VAL:GetAttribute("Friction_ROTATE");K_ROTATE=PRO_VAL:GetAttribute("K_ROTATE")
						;AutoUpdate=PRO_VAL:GetAttribute("AutoUpdate")
						;Lock_POSITION=PRO_VAL:GetAttribute("Lock_POSITION");Lock_ROTATION=PRO_VAL:GetAttribute("Lock_ROTATION")
						;Y_R_Multiplier=PRO_VAL:GetAttribute("_Y_R_Multiplier");X_R_Multiplier=PRO_VAL:GetAttribute("_X_R_Multiplier");Z_R_Multiplier=PRO_VAL:GetAttribute("_Z_R_Multiplier")
						;Y_R_Max=PRO_VAL:GetAttribute("__Y_R_Max");X_R_Max=PRO_VAL:GetAttribute("__X_R_Max");Z_R_Max=PRO_VAL:GetAttribute("__Z_R_Max")
						;Y_R_Min=PRO_VAL:GetAttribute("__Y_R_Min");X_R_Min=PRO_VAL:GetAttribute("__X_R_Min");Z_R_Min=PRO_VAL:GetAttribute("__Z_R_Min")
					})
				elseif sub_parts:IsA("BasePart") and sub_parts ~= MainPart then -- default weld
					local weld = MD_.FF:Weld(MainPart,sub_parts)
				end
			end
			MainPart.CFrame = RealPart.CFrame
			local weld = MD_.FF:Weld(RealPart,MainPart)
			weld.Parent = DecoFolder
			weld.Name = RealPart.Name .. "_Main_Weld_"
			
			if RealPart:GetAttribute("FirstPersonTag") then
				weld:SetAttribute("FirstPersonTag",true)
			end
			if RealPart:FindFirstChild("IgnoreRaycastScene") then
				RealPart:SetAttribute("Ignore_RayCast_Value_For_Target_Scene",true)
			end
		end
	end

	if #Bouncy_Objects ~= 0 and Bouncy_Feature then
		
		-- makes the function for Bouncy_Objects_Functions
		for _,bouncy_propierties in pairs (Bouncy_Objects) do	
			local Origin = bouncy_propierties.Origin
			local Origin_Offset = (bouncy_propierties.Origin.CFrame*bouncy_propierties.Offset)
			bouncy_propierties.Part.Anchored = true

			if not bouncy_propierties.Lock_POSITION then
				bouncy_propierties.Position = _G.Modules_SpringModule_V1.new(Origin_Offset.p, VE3(), Origin_Offset.p,bouncy_propierties.Friction_POSITION,bouncy_propierties.K_POSITION)
			end
			if not bouncy_propierties.Lock_ROTATION then
				bouncy_propierties.Rotation = _G.Modules_SpringModule_V1.new(Origin_Offset.p, VE3(), Origin_Offset.p,bouncy_propierties.Friction_ROTATE,bouncy_propierties.K_ROTATE)
			end
			bouncy_propierties.Part.CFrame = Origin_Offset
			---
			function bouncy_propierties:GetY(Velocity_Y)
				return M_RAD(M_CL(math.deg(Velocity_Y*bouncy_propierties.Y_R_Multiplier),(bouncy_propierties.Y_R_Min),(bouncy_propierties.Y_R_Max)))
			end
			---
			function bouncy_propierties:GetX(Velocity_X)
				return M_RAD(M_CL(math.deg(Velocity_X*bouncy_propierties.X_R_Multiplier),(bouncy_propierties.X_R_Min),(bouncy_propierties.X_R_Max)))
			end
			---
			function bouncy_propierties:GetZ(Velocity_Z)
				return M_RAD(M_CL(math.deg(Velocity_Z*bouncy_propierties.Z_R_Multiplier),(bouncy_propierties.Z_R_Min),(bouncy_propierties.Z_R_Max)))
			end
			------------------------------------------------------
			------------------------------------------------------
			if bouncy_propierties.Position then
				function bouncy_propierties:GetPosition()
					return bouncy_propierties.Position.ActualPosition
				end
			else
				function bouncy_propierties:GetPosition(Origin_Offset)
					return Origin_Offset
				end
			end
			------------------------------------------------------
			----------------------------------------------------
			-- loop
			local function lock_()
				local Origin_Offset = (bouncy_propierties.Origin.CFrame*bouncy_propierties.Offset)
				local Position,Rotation = bouncy_propierties.Position,bouncy_propierties.Rotation
				bouncy_propierties.Part.CFrame = Origin_Offset
				if Position then Position.ActualPosition = Origin_Offset.p Position.Position = Position.ActualPosition Position:Update() end
				if Rotation then Rotation.ActualPosition = Origin_Offset.p Rotation.Position = Rotation.ActualPosition Rotation:Update() end
			end lock_()
			
			local do_it = true
			delay(.15,function()
				do_it = false
			end)
			
			Bouncy_Objects_Functions[bouncy_propierties.Part] = {_update_function=function()
				local Origin_Offset = (bouncy_propierties.Origin.CFrame*bouncy_propierties.Offset)
				if Lock_Bounce.Value or do_it or not DecoFolder:IsDescendantOf(_Services.Workspace) then
					lock_()
				else
					local Position,Rotation = bouncy_propierties.Position,bouncy_propierties.Rotation
					if Position then Position.Position = Origin_Offset.p Position:Update() end

					local x,y,z = Origin_Offset:ToEulerAnglesXYZ()
					bouncy_propierties.Part.CFrame = (CFN(bouncy_propierties:GetPosition(Origin_Offset.p))) * CFA(x,y,z)

					if Rotation then 
						Rotation.Position = Origin_Offset.p Rotation:Update() 
						local use_velocity =  Origin_Offset:VectorToObjectSpace(Rotation.Velocity)
						bouncy_propierties.Part.CFrame *= CFA(bouncy_propierties:GetY(use_velocity.Y)+bouncy_propierties:GetZ(use_velocity.Z),0,bouncy_propierties:GetX(use_velocity.X))--  bouncy_propierties:GetY(use_velocity.Y)+bouncy_propierties:GetX(use_velocity.Z),0,bouncy_propierties:GetZ(use_velocity.X))
					end
				end
				if Bouncy_Objects_Functions[bouncy_propierties.Update_Me_Part] then
					Bouncy_Objects_Functions[bouncy_propierties.Update_Me_Part]._update_function()
				end
			end,}
		end
		-- read the function
		local RE RE = _Services.Run.RenderStepped:Connect(function()
			if not DecoFolder:IsDescendantOf(game) then RE:Disconnect() RE = nil end
			for number,bouncy_propierties in pairs (Bouncy_Objects) do	
				if bouncy_propierties.Part:IsDescendantOf(game) then
					if bouncy_propierties.AutoUpdate then
						Bouncy_Objects_Functions[bouncy_propierties.Part]._update_function()
					end
				else
					Bouncy_Objects_Functions[bouncy_propierties.Part]=nil
					Bouncy_Objects[number]=nil
				end
			end
		end)
	end
end

--████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████████
--█▄─▄▄─██▀▄─██─▄▄▄─█▄─▄██▀▄─██▄─▄█████▄─▄▄─█▄─▀─▄█▄─▄▄─█▄─▄▄▀█▄─▄▄─█─▄▄▄▄█─▄▄▄▄█▄─▄█─▄▄─█▄─▀█▄─▄██████████─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─█
--██─▄████─▀─██─███▀██─███─▀─███─██▀████─▄█▀██▀─▀███─▄▄▄██─▄─▄██─▄█▀█▄▄▄▄─█▄▄▄▄─██─██─██─██─█▄▀─███████████▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄█
--▀▄▄▄▀▀▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄█▄▄▀▄▄▄▀▀▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀████████▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀

function module:Facial_Expresiones(Character,FaceType,Character_resourses,POTRAIT_MODE : bool,DEFAULT_CHARISMA : face_state)
	local Config = {}
	
	local Head_Expresions,FACE_CONTROLLER,__ANIMATED_FACE_SETUP
	
	--Main Values 
	Config.charisma = DEFAULT_CHARISMA or "1_Good"
	Config.current_face_state = "Idle"
	
	--[[
		X3 (due to 1_Good 2_Meh 3_Sad)
		9x3 = 27 unique animated faces ._.
		9 variety{
		Idle
		Jump
		Hurt
		Excited
		Masturbation
		Attack
		Ragdoll
		Left
		Right
		}
		
		27 x 5 (total of uniques face expressiones)
		135 animated faces 
	]]
	
	--get the main face controller from his folder
	local __FE_Folder = _Services.RepliStorage:FindFirstChild("Faces"):FindFirstChild(FaceType)
	local __POTRAIT_FACE_FOLDER = __FE_Folder:FindFirstChild("POTRAIT_MODE")
	Config.FE_Folder = __FE_Folder

	--puts the face rig (cheeks :,V) + generate joints
	local FE_Rig = Character_resourses:FindFirstChild("_Face_Rig"):Clone() FE_Rig.Parent = Character
	local MAIN_EXpresion = FE_Rig.MainEXpresion
	MAIN_EXpresion.CFrame = Character.Head.CFrame
	local Weld_Main_Part = MD_.FF:Motor6D(Character.Head,MAIN_EXpresion)
	Weld_Main_Part.Parent = Character
	Weld_Main_Part.Name = MAIN_EXpresion.Name .. "_Main_Weld_"
	Config.Weld_Main_Part=Weld_Main_Part
	Config.FE_Rig = FE_Rig
	
	--face controller require values
	local Face_Event_String = Instance.new("StringValue",Character)
	Face_Event_String.Name = "Face_Event_String"
	
	local TARGET_OBJECT = Instance.new("ObjectValue",Face_Event_String)
	TARGET_OBJECT.Name = "TARGET_OBJECT"
	
	--annoying shit to dissapear
	for i,v in pairs (FE_Rig:GetDescendants()) do
		if not v:IsA("BasePart") then continue end
		v.CanCollide = false
		v.CanTouch = false
	end
	
	local Animator_Controller = FE_Rig.AnimationController.Animator
	
	-- find the expression value of the head to make in what direction should the face go
	local Face_Side = "Front"
	function Config:GetFaceExpresion()
		for i,v in pairs (Character:GetDescendants()) do
			if v:FindFirstChild("FACE_EXPRESSION_EMULATOR") then
				Head_Expresions = v
				Face_Side = v:FindFirstChild("FACE_EXPRESSION_EMULATOR").Value
			end
		end
	end  
	--

	Config.DisableSideTick={} -- to prevent auto update for faces
	Config:GetFaceExpresion()
	
	-- runs the face controller
	local function install_module_face_controller()
		if __ANIMATED_FACE_SETUP then __ANIMATED_FACE_SETUP:Destroy() __ANIMATED_FACE_SETUP = nil end
		__ANIMATED_FACE_SETUP = __FE_Folder:FindFirstChild("ANIMATED_FACE_SETUP"):Clone()
		__ANIMATED_FACE_SETUP.Parent = Head_Expresions
		FACE_CONTROLLER = require(__ANIMATED_FACE_SETUP)
		FACE_CONTROLLER = FACE_CONTROLLER(Head_Expresions.Parent,__ANIMATED_FACE_SETUP,nil,MD_,Face_Event_String)
	end
	
	if not POTRAIT_MODE then
		install_module_face_controller()
	elseif __POTRAIT_FACE_FOLDER then -- runs the potrait mode (single execution)
		local Get_Mood_Face = __POTRAIT_FACE_FOLDER:FindFirstChild(Config.charisma)
		local available = Get_Mood_Face:GetChildren()
		local random_alternative = available[math.random(1,#available)]
		for _,a in pairs (random_alternative:GetChildren()) do local b = a:Clone() b.Parent = Head_Expresions b.Face = Face_Side end 
	else
		warn("POTRAIT MODE ISSUE WITH :" .. Config.charisma .. "-" .. FaceType .. "-" )
	end
	--
	
	function Config:SceneMode() FE_Rig.AnimationController:Destroy() end
	
	local Current_Eyes,Current_Mouth,Current_Blurry

	local State_Chance = {
		{Name = "Idle"		, Chance = 100	; Time_stay = 1.5;}, -- each one of these is an entry
		{Name = "Left"		, Chance = 40   ; Time_stay = .8;},
		{Name = "Excited"	, Chance = 20	; Time_stay = .8;},
		{Name = "Right"		, Chance = 40	; Time_stay = .6;}
	}
	
	function Config:Face_Loop(force)
		if (not __ANIMATED_FACE_SETUP or not __ANIMATED_FACE_SETUP:IsDescendantOf(game) or not FACE_CONTROLLER) then return end
		Face_Event_String.Value = Config.charisma .. "_" .. Config.current_face_state
		
		if not Config.ChangeSideTick and not MD_.FF:not_empty__switch(Config.DisableSideTick) then
			local Face_State_choosed = MD_.FF:getRandomItem(State_Chance)
			Config.ChangeSideTick = tick() + (M_RAN(50,600)/100)* Face_State_choosed.Time_stay
			Config.current_face_state = Face_State_choosed.Name
		elseif  Config.ChangeSideTick and  Config.ChangeSideTick - tick() < 0 then
			Config.ChangeSideTick = nil
		end
		
		FACE_CONTROLLER:Loop()
	end
	
	function Config:jump_call_event()
		if Config.BLOCK then return end
		Config.ChangeSideTick = tick() + .8
		Config.current_face_state="Jump"
		FACE_CONTROLLER:Update()
	end
	
	function Config:attack_call_event()
		if Config.BLOCK then return end
		Config.ChangeSideTick = tick() + .8
		Config.current_face_state="Attack"
		FACE_CONTROLLER:Update()
	end
	
	function Config:hurt_call_event()
		if Config.BLOCK then return end
		Config.ChangeSideTick = tick() + 4
		Config.current_face_state="Hurt"
		FACE_CONTROLLER:Update()
	end

	function Config:ChangeFaceStyle(face,timing)
		if Config.BLOCK then return end
		Config.ChangeSideTick = tick() + timing
		Config.current_face_state=face
	end
	
	function Config:FuckingDie(bool)
		MD_.FF:check__switch({BB=true,TM=Config,TS={Name="FUCKING DED"},NN="DisableSideTick",FF=nil})
		Config.current_face_state="Ragdoll"
		Config.BLOCK=true
	end

	function Config:RagdollStyle(bool)
		if Config.BLOCK then return end
		if bool == "ON" then
			Config.current_face_state="Ragdoll"
			MD_.FF:check__switch({BB=true,TM=Config,TS={Name="Ragdoll"},NN="DisableSideTick",FF=nil})
		elseif bool == "OFF" then
			MD_.FF:check__switch({BB=nil,TM=Config,TS={Name="Ragdoll"},NN="DisableSideTick",FF=nil})
			Config.ChangeSideTick = nil
		end
	end
	
	function Config:Excited(bool)
		if Config.BLOCK then return end
		if bool == "ON" then
			Config.current_face_state="Masturbation"
			MD_.FF:check__switch({BB=true,TM=Config,TS={Name="Masturbation"},NN="DisableSideTick",FF=nil})
		elseif bool == "OFF" then
			MD_.FF:check__switch({BB=nil,TM=Config,TS={Name="Masturbation"},NN="DisableSideTick",FF=nil})
			Config.ChangeSideTick = nil
		end
	end
	
	function Config:Restart(next_face)
		Config:GetFaceExpresion()
		install_module_face_controller()
	end
	
	return Config
end

--███████████████████████████████████████████████████████████████████████████████████████████████████
