--skin_name,Character,Type,NoFacial,BouncyObjects,BouncyValueLock
function module:Dress_My_Character(C)
	local C = C or {}
	module:Fake_Parts(C.CHARACTER,_Services.RepliStorage.Characters.Profile[C.SKIN_NAME][C.CLOTH_TYPE],C.BouncyObjects,C.BouncyValueLock)
	if not C.NoFacial then
		local Get_Face_Style = C.FACE_STYLE or _Services.RepliStorage.Characters.Profile[C.SKIN_NAME]:GetAttribute("Face_Style")
		return module:Facial_Expresiones(C.CHARACTER,Get_Face_Style,_Services.RepliStorage.Characters.Profile[C.SKIN_NAME],C.POTRAIT_MODE,C.CHARISMA)
	end
end

