function module:Get_Player_Character(return_library)
	local Character = _G.Player.Character
	local Library = return_library and Character:FindFirstChild("Character_Script") and require(Character.Character_Script.__LIBRARY)
	if Character and Character:FindFirstChild("Humanoid") then
		return (Character.Humanoid.Health > 0 and Character),Library
	end
end

return module
