for i,v in pairs (_Services.RepliStorage.Characters.Profile:GetChildren()) do
	layout+=1
	if not module.Skins_description[v.Name] then
		module.Skins_description[v.Name] = {real_name=v:GetAttribute("Real_Name") or v.Name;DeveloperName=v:GetAttribute("Real_Developer") or "Community";Layout=layout}
	end
	
	if not v:GetAttribute("Voice_Style") then v:SetAttribute("Voice_Style","Default_001") end 
	if not v:GetAttribute("Face_Style") then v:SetAttribute("Face_Style","Default_001") end 
end

