local RS_Objects = _Services.RepliStorage:WaitForChild("Objects");
local Vector3_rad = Vector3.new(1,1,1)*(math.pi/180);

local function GetCFrameAttribute(Value,AttributeName) if not Value or not AttributeName then return; end;
	local BaseCF = CFrame.new(Value:GetAttribute(AttributeName.."_CF") or Vector3.new()); --Not mandatory, but can act as the first base CFrame, which means it is at the front of the entire thing. ex: CFrame*[m1*m2*m3*...]
	local Index = 1; --Acts a bit like an ipairs loop, so anything can be renamed to a number that can't be reached if they want to preserve the number for adjustment testing.
	while true do --Could just run a loop for all of it using :GetAttributes(), but doesn't really matter.
		local Positional = Value:GetAttribute(AttributeName.."_CF_M"..Index);  if Positional then  BaseCF = BaseCF*CFrame.new(Positional);  end;
		local Angular = Value:GetAttribute(AttributeName.."_CF_Angle_M"..Index);  if Angular then Angular = Angular*Vector3_rad; BaseCF = BaseCF*CFrame.Angles(Angular.X,Angular.Y,Angular.Z); end;
		if not Positional and not Angular then break; end; 
		Index += 1;
	end;
	return BaseCF;
end;

