			SpreadValue = Value:GetAttribute("SpreadValue");
			DisplayCF = GetCFrameAttribute(Value,"DisplayCF");
			WorldViewMainCF = GetCFrameAttribute(Value,"WorldViewMainCF");
			Offset = GetCFrameAttribute(Value,"Offset");
		};
	end
end;

