local MD_ = _G._MD
local module = {}

local Log_Scenes={}

function module:Install_Scene(Scene_Origin,Model,TBC____,C)
	
	local MAIN_SCENERY_PART = Model:FindFirstChild("MAIN_SCENERY_PART")
	local AnimationController = Model:FindFirstChild("AnimationController").Animator
	
	local Scene_Manager = _G.Modules_Scene_Manager:Clone() Scene_Manager.Parent = Model for i,v in next,Scene_Origin.Scene_Module:GetChildren() do v:Clone().Parent = Scene_Manager end 
	local SCENE_CONFIG = require(Scene_Manager)
	local SCENE_ID = TBC____.Entity_ID .. Model.Name
	local Player_Faces_Folder pcall(function() Player_Faces_Folder = _Services.RepliStorage.Faces[TBC____.Bot_Humanoid.Face_Style.Value] end)
	
	local WaitUntilTick = tick()+1
	local GetMarkerReachedSignal={}
	local Saved_Faces_Parts={}
	local Saved_Table_Parts={}

	local Scene_Shared = {}
	Scene_Shared.Model = Model
	Scene_Shared.MAIN_SCENERY_PART=MAIN_SCENERY_PART
	Scene_Shared.AnimationController=AnimationController
	
	local Face_Event_String = Instance.new("StringValue",Model)
	Face_Event_String.Name = "Face_Event_String"
	local TARGET_OBJECT = Instance.new("ObjectValue",Face_Event_String)
	TARGET_OBJECT.Name = "TARGET_OBJECT"
	local TARGET_OFFSET = Instance.new("CFrameValue",TARGET_OBJECT)
	TARGET_OFFSET.Name = "TARGET_OFFSET"
	
	
	Scene_Shared.Face_Event_String = Face_Event_String
	local Cum_Folder = Instance.new("Folder",Model)
	Cum_Folder.Name="Cum_Folder"
	TBC____.Scene_Config.Cum_Folder = Cum_Folder

	--█████████████████████████████████████████████
	--█─▄▄▄▄█─▄▄▄─█▄─▄▄─█▄─▀█▄─▄█▄─▄▄─███▄─▄█▄─▄▄▀█
	--█▄▄▄▄─█─███▀██─▄█▀██─█▄▀─███─▄█▀████─███─██─█
	--▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀▀▀▄▄▄▀▄▄▄▄▀▀
	
	--this makes all the animations of the scenes apart from being random, they are not always the same
	Log_Scenes[SCENE_ID] = Log_Scenes[SCENE_ID] or {}
	
	local function Create_new_table()
		Log_Scenes[SCENE_ID] = {}
		for _,v in pairs (SCENE_CONFIG.ListPoses) do
			TA_IN(Log_Scenes[SCENE_ID],v)
		end
		MD_.FF:Shuffle(Log_Scenes[SCENE_ID])
	end
	
	local function Choose_next_pose()
		if #Log_Scenes[SCENE_ID] == 0 then -- if scene log scenes quote == 0
			Create_new_table()
		end
		local Return_Pose 
		for pos_table,pos_description in pairs (Log_Scenes[SCENE_ID]) do
			Return_Pose = pos_description
			TA_RE(Log_Scenes[SCENE_ID],pos_table)
			break
		end
		return Return_Pose
	end
	--
	local Current_Pose = Choose_next_pose()

	--█████████████████████████████████████████████████████████████████████████████████▀█████████████
	--█▄─▄▄─█▄─▀█▄─▄█─▄─▄─█▄─▄█─▄─▄─█▄─▄█▄─▄▄─█─▄▄▄▄███▄─▀█▀─▄██▀▄─██▄─▀█▄─▄██▀▄─██─▄▄▄▄█▄─▄▄─█▄─▄▄▀█
	--██─▄█▀██─█▄▀─████─████─████─████─███─▄█▀█▄▄▄▄─████─█▄█─███─▀─███─█▄▀─███─▀─██─██▄─██─▄█▀██─▄─▄█
	--▀▄▄▄▄▄▀▄▄▄▀▀▄▄▀▀▄▄▄▀▀▄▄▄▀▀▄▄▄▀▀▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▀▄▄▄▀▄▄▄▀▄▄▀▄▄▀▄▄▄▀▀▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▀▄▄▀
	
	--TO GET THE APPEARANCE
	local List_Entity_Available = {}
	for _,config in pairs(TBC____.Scene_Config.Local_Config_Log) do
		TA_IN(List_Entity_Available,{EntityType=config.Local_Config.Bot_Config.REAL_Name,Character=config.Local_Config.Bot_Character})
	end
	if not TBC____.ImPlayer then
		TA_IN(List_Entity_Available,{EntityType=TBC____.Bot_Config.REAL_Name,Character=TBC____.Bot_Character})
	end

	--███████████████████████████████████████████████████████████████████████████████████████
	--█─▄▄▄▄█─█─██▀▄─██▄─▄▄▀█▄─▄▄─███▄─▄▄─█▄─██─▄█▄─▀█▄─▄█─▄▄▄─█─▄─▄─█▄─▄█─▄▄─█▄─▀█▄─▄█─▄▄▄▄█
	--█▄▄▄▄─█─▄─██─▀─███─▄─▄██─▄█▀████─▄████─██─███─█▄▀─██─███▀███─████─██─██─██─█▄▀─██▄▄▄▄─█
	--▀▄▄▄▄▄▀▄▀▄▀▄▄▀▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▀▀▄▄▄▀▀▀▀▄▄▄▄▀▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀
	do
		--get the animation instance
		function Scene_Shared:GetAnimationInstance(animation_name)
			return Scene_Origin.Animations:FindFirstChild(animation_name)
		end
		
		--return a list of the parts with "FAKE_PART_CATEGORIE"
		function Scene_Shared:GetCategorieParts(Search_For,Categorie)
			local parts = {}
			for i,v in pairs (Search_For:GetDescendants()) do
				if v:FindFirstChild("FAKE_PART_CATEGORIE") and v:FindFirstChild("FAKE_PART_CATEGORIE").Value == Categorie then
					TA_IN(parts,v)
				end
			end
			return parts
		end
		
		--change the transparency of the parts with "GetCategorieParts"
		function Scene_Shared:Transparency_Parts(Nme,Tran)
			for i,v in pairs (Scene_Shared:GetCategorieParts(Model,Nme)) do
				if Tran == "Transparency" then
					local T = v:GetAttribute("Transparency")
					if T then
						v.Transparency=T
						v:SetAttribute("OR_Transparency",T)
					end
				else
					v.Transparency=Tran
					v:SetAttribute("OR_Transparency",Tran)
				end
			end
		end
		
		--remove the parts from the list with "GetCategorieParts"
		function Scene_Shared:RemoveCategorieParts(Search_For,Categorie)
			for i,v in pairs (Scene_Shared:GetCategorieParts(Search_For,Categorie)) do
				v:Destroy()
			end
		end
		
		--cum particle event
		function Scene_Shared:Cum_Event(Search,CumName,CumOriginName,C)
			local C = C or {}
			for i,v in pairs (Search:GetDescendants()) do
				if v.Name == CumOriginName then
					local CopyC = MD_.FF:shallowCopy(C)
					CopyC.Parent = Cum_Folder
					CopyC.Origin_Part = v
					MD_.FF:Generate_Semen(CopyC)
					
					--local Cum_ = game.ReplicatedStorage.Objects:FindFirstChild(CumName):Clone()
					--local DebrisTime,VelocityForce,Spread,backoffset = C.DebrisTime,C.Velocity,C.Spread,C.backoffset
					--Cum_.Parent = Model
					--Cum_.CFrame = v.CFrame+(v.CFrame.lookVector*C.backoffset)

					--Spread /= 100
					--local DIRECTION = CFN(VE3(),v.CFrame.lookVector*25) * CFA(M_RAD((M_RAN(-180,180))*Spread),M_RAD((M_RAN(-180,180)/180)*Spread),M_RAD((M_RAN(-180,180)*Spread)))

					--Cum_.Velocity = DIRECTION.lookVector*VelocityForce

					--_Services.Debris:AddItem(Cum_,DebrisTime)
				end
			end
		end
		
		-- Finds in all the model the part with the " current name"
		function Scene_Shared:GetPartName(Part_Name)
			local PartName
			if not Saved_Table_Parts[Part_Name] then
				for i,v in pairs (Model:GetDescendants()) do
					if v.Name == Part_Name then
						PartName = v
						break
					end
				end
				Saved_Table_Parts[Part_Name]=PartName
			else
				PartName = Saved_Table_Parts[Part_Name]
			end
			return PartName
		end
		

		-- PLAY SCENE SOUNDS
		function Scene_Shared:PlaySceneSound(Part_Sound_Name,SoundName,CS)
			if typeof(CS) == "string" then warn(Part_Sound_Name,SoundName,CS,"__DETECTED__PROBLEM_WITH_TABLE") end
			local CS = CS or {}
			local SoundPart = (typeof(Part_Sound_Name) ~= "string" and Part_Sound_Name) or Scene_Shared:GetPartName(Part_Sound_Name)
			local Search_Sound = _Services.RepliStorage.Sounds:FindFirstChild("0_Sexual_Sounds")

			--Change Sound by Char Voice
			if CS.Player_Style then
				local CHAR_VOICE = _Services.RepliStorage.Sounds:FindFirstChild("0_Character_Voices")
				Search_Sound = CHAR_VOICE:FindFirstChild(TBC____.Bot_Humanoid.Voice_Style.Value)
				if not Search_Sound then Search_Sound = CHAR_VOICE:FindFirstChild("Default") end
			end
			--
			if SoundPart then
				if CS.ReturnSound then
					return MD_.FF:PlaySound(SoundPart,SoundName,{Search_Sound=Search_Sound;PlayOnRemove=false,Volume=CS.Volume;PlaybackSpeed=CS.PlaybackSpeed,Save=true,NotPlaying=true})
				else	
					MD_.FF:PlaySound(SoundPart,SoundName,{Search_Sound=Search_Sound;PlayOnRemove=true,Volume=CS.Volume;PlaybackSpeed=CS.PlaybackSpeed})
				end
			end
		end

		-- FACIAL EXPRESSION CHANGER
		function Scene_Shared:Face_Changer_Event(PartName,StringKey,WhereSearchFaces)
			local Head_Expresions
			if not Saved_Faces_Parts[PartName] then
				for i,v in pairs (Model:GetDescendants()) do
					if v.Name == PartName then
						Head_Expresions = v
						break
					end
				end
				Saved_Faces_Parts[PartName]=Head_Expresions
			else
				Head_Expresions = Saved_Faces_Parts[PartName]
			end
			if Head_Expresions and Head_Expresions:FindFirstChild("FAKE_HEAD_PART") then
				local fake_head_part = Head_Expresions:FindFirstChild("FAKE_HEAD_PART")
				Head_Expresions = fake_head_part.Value
				local face_expression_emulator = Head_Expresions:FindFirstChild("FACE_EXPRESSION_EMULATOR")

				local Face_Side = face_expression_emulator.Value
				local DontRemoveTheseFaces={}
				--add the new faces

				if WhereSearchFaces == "Player" then WhereSearchFaces = Player_Faces_Folder end
				local Search_Faces = WhereSearchFaces or Scene_Origin.Faces
				
				if StringKey == "Animated_Face" then
					local ANIMATED_FACE_SETUP = Search_Faces:FindFirstChild("ANIMATED_FACE_SETUP"):Clone()
					ANIMATED_FACE_SETUP.Parent = Head_Expresions
					DontRemoveTheseFaces[ANIMATED_FACE_SETUP]=true
					local ACCESORY_MODULE = require(ANIMATED_FACE_SETUP)
					spawn(function()
						ACCESORY_MODULE = ACCESORY_MODULE(Head_Expresions.Parent,ANIMATED_FACE_SETUP,nil,MD_,Face_Event_String)
						local Heartbeat Heartbeat = _Services.Run.Heartbeat:connect(function()
							if ANIMATED_FACE_SETUP and ANIMATED_FACE_SETUP:IsDescendantOf(game) then ACCESORY_MODULE:Loop() else Heartbeat:Disconnect() end 
						end)
					end)
				elseif Search_Faces and Search_Faces:FindFirstChild(StringKey) then
					local FACE_FOLDER = Search_Faces:FindFirstChild(StringKey)
					for i,v in pairs (FACE_FOLDER:GetChildren()) do
						if v:IsA("Decal") or v:IsA("Texture") then
							local CopyFace = v:Clone()
							CopyFace.Parent = Head_Expresions
							CopyFace.Face = Face_Side
							DontRemoveTheseFaces[CopyFace]=true
						elseif v:IsA("Model") or v:IsA("Folder") then
							local CloneAccesory = v:Clone()
							for _,v in pairs (CloneAccesory:GetDescendants()) do
								if not v:IsA("BasePart") then continue end
								v.Anchored = false
								v.CanCollide = false
								if v ~= CloneAccesory.MainPart then
									MD_.FF:Weld(CloneAccesory.MainPart,v).Parent=CloneAccesory.MainPart
								end
							end
							for _,v2 in pairs (CloneAccesory:GetDescendants()) do
								if v2.Name == "ACCESORY_MODULE" and Head_Expresions.Parent then
									local ACCESORY_MODULE = require(v2)
									spawn(function()
										ACCESORY_MODULE = ACCESORY_MODULE(Head_Expresions.Parent,v2,nil,MD_,Face_Event_String)
										local Heartbeat Heartbeat = _Services.Run.Heartbeat:connect(function()
											if v2 and v2:IsDescendantOf(game) then ACCESORY_MODULE:Loop() else Heartbeat:Disconnect() end 
										end)
									end)
								end
							end

							CloneAccesory.Parent = Head_Expresions
							if CloneAccesory:FindFirstChild("MainPart") then
								CloneAccesory.MainPart.CFrame = Head_Expresions.Parent.MainPart.CFrame
								CloneAccesory.MainPart.Anchored=false
								MD_.FF:Weld(CloneAccesory.MainPart,Head_Expresions).Parent=CloneAccesory
							end
							DontRemoveTheseFaces[CloneAccesory]=true
						end
					end
				else
					warn("Missing:",StringKey,WhereSearchFaces)
				end

				--delete current faces
				for i,v in pairs (Head_Expresions:GetChildren()) do
					if not DontRemoveTheseFaces[v] and v~=fake_head_part and v~= face_expression_emulator then
						v:Destroy()
					end
				end
				--
			end
		end
	end
	--███████████████▀████████████████████████████████
	--█▄─▄▄▀█▄─▄█─▄▄▄▄███▄─▄─▀█▄─██─▄█▄─▄█▄─▄███▄─▄▄▀█
	--██─▄─▄██─██─██▄─████─▄─▀██─██─███─███─██▀██─██─█
	--▀▄▄▀▄▄▀▄▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▄▄▄▄▄▀▄▄▄▄▀▀
	do
		-- to build appearance from the entire rig
		local function build_rig(Rig,FakeParts)
			--Cleaner
			for _,object in pairs (FakeParts:GetDescendants()) do
				if object:IsA("Weld") then -- remove welds
					object:Destroy()
				elseif object:IsA("Trail") then -- annoying effect with trails
					local old_status = object.Enabled
					object.Enabled = false
					delay(.2,function()
						pcall(function()
							object.Enabled = old_status
						end)
					end)
				end
			end	
			-- change the fake parts model names to their current parents
			FakeParts.Name="CHOOSE PARTS"
			for _,rig_parts in pairs (Rig:GetChildren()) do
				if rig_parts:IsA("BasePart") then
					rig_parts.Transparency=1
					local replace_word = tostring(">>" .. Rig.Name .. "<<_")
					local Name_nocap = rig_parts.Name:gsub(replace_word,"")
					if FakeParts:FindFirstChild(Name_nocap) then
						local Fake_Model = FakeParts:FindFirstChild(Name_nocap)
						Fake_Model.Name = rig_parts.Name
					end	
				end
			end 
			--dress the Rig
			MD_.FF:Fake_Parts(Rig,FakeParts,true,nil)
			--remove the rest
			FakeParts:Destroy()
		end

		--look for the tag of facial expressions to add the tag that is the fake head 
		local function Find_FACE_EXPRESSION_EMULATOR (Parts,Head)
			for i,v in pairs (Parts:GetDescendants()) do
				if v:FindFirstChild("FACE_EXPRESSION_EMULATOR") then
					local ObjectValue = INST("ObjectValue",Head)
					ObjectValue.Name = "FAKE_HEAD_PART"
					ObjectValue.Value = v
					break
				end
			end
		end
		
		--This system does a search in the rig scene and adds the appearance that these have by copying your folder of decoration parts
		for _,Rig_Models in pairs (Model:GetChildren()) do
			if Rig_Models:IsA("Model") then
				local Rig_Models = Rig_Models
				
				-- furniture around
				if Rig_Models:FindFirstChild("Furniture_Rig") then
					local ActualRigModel = Rig_Models:FindFirstChild("Rig")
					local FakeParts = Rig_Models:FindFirstChild("Parts")
					local Furniture_Root = ActualRigModel:FindFirstChild("Furniture_Root")
					local Motor6D = MD_.FF:Motor6D(MAIN_SCENERY_PART,Furniture_Root)
					Motor6D.Parent = MAIN_SCENERY_PART
					build_rig(ActualRigModel,FakeParts)
					for _,rig_parts in pairs (ActualRigModel:GetChildren()) do
						if rig_parts:IsA("BasePart") then
							rig_parts.CanCollide = false
							rig_parts.Anchored = false
							rig_parts.Name = ">>".. Rig_Models.Name .. "<<_".. rig_parts.Name
						end
					end
					Motor6D.Name = Furniture_Root.Name
				end
				--- replace humans ---
				if Rig_Models.Name == "Rig_Player" then
					local Real_Rig_Copy = _Services.RepliStorage.Characters:FindFirstChild("Rig"):Clone()
					Real_Rig_Copy:FindFirstChildOfClass("Humanoid"):Destroy()
					Real_Rig_Copy.Parent = Rig_Models.Parent
					Real_Rig_Copy.Name = Rig_Models.Name
					Real_Rig_Copy.HumanoidRootPart.Anchored=true
					Real_Rig_Copy.HumanoidRootPart.CFrame = Rig_Models.HumanoidRootPart.CFrame
					MD_.FF:Motor6D(MAIN_SCENERY_PART,Real_Rig_Copy.HumanoidRootPart).Parent = MAIN_SCENERY_PART
					Rig_Models:Destroy()
					Rig_Models=Real_Rig_Copy
				end
				--- replace entities ---
				if Rig_Models:FindFirstChild("Entity_Name_User") then -- replace the current skeleton with a new one
					local Entity_Name_User = Rig_Models:FindFirstChild("Entity_Name_User")
					local Real_Rig_Copy = _Services.RepliStorage.Characters.Entity:FindFirstChild(Entity_Name_User.Value):FindFirstChild("Rig"):Clone()
					Real_Rig_Copy:FindFirstChildOfClass("Humanoid"):Destroy()
					Real_Rig_Copy.Parent = Rig_Models.Parent
					Real_Rig_Copy.Name = Rig_Models.Name
					Real_Rig_Copy.HumanoidRootPart.Anchored=true
					Real_Rig_Copy.HumanoidRootPart.CFrame = Rig_Models.HumanoidRootPart.CFrame
					MD_.FF:Motor6D(MAIN_SCENERY_PART,Real_Rig_Copy.HumanoidRootPart).Parent = MAIN_SCENERY_PART
					Rig_Models:Destroy()
					Rig_Models=Real_Rig_Copy
				end
				--- FAKER HUMAN ---
				if Rig_Models.Name == "Rig_Player" then -- for the player
					local Use_Cloth_Type = (TBC____.Bot_Humanoid.ClothType_String.Value == "Cloth" and "Naked_1") or TBC____.Bot_Humanoid.ClothType_String.Value 
					local FacilConfig = MD_.FF:Dress_My_Character({FACE_STYLE=TBC____.Bot_Humanoid.Face_Style.Value;SKIN_NAME=TBC____.Bot_Humanoid.Skin_String.Value;CHARACTER=Rig_Models;CLOTH_TYPE=Use_Cloth_Type;NoFacial=false,BouncyObjects=true,BouncyValueLock=nil})
					FacilConfig:SceneMode()
					
					--import facial expressions folder

					local Head = Rig_Models:FindFirstChild("Head")	
					Find_FACE_EXPRESSION_EMULATOR (Rig_Models,Head)
				end
				--- RENAMER ---
				for _,rig_parts in pairs (Rig_Models:GetChildren()) do
					if rig_parts:IsA("BasePart") then
						rig_parts.CanCollide = false
						rig_parts.Anchored = false
						rig_parts.Name = ">>".. Rig_Models.Name .. "<<_".. rig_parts.Name
					end
				end
				--- FAKER ENTITIES ---
				if Rig_Models:FindFirstChild("Entity_Name_User") then -- for entitys
					--Rig_Models
					local Entity_Name_User = Rig_Models:FindFirstChild("Entity_Name_User").Value
					local get_identical_entity
					for _,bot_available in pairs (List_Entity_Available) do
						if bot_available.EntityType == Entity_Name_User and not bot_available.OnUse then
							bot_available.OnUse = true
							get_identical_entity = bot_available.Character.Parent:FindFirstChild("__Fake__Parts__"):Clone()
							break
						end
					end
					
					if get_identical_entity then
						get_identical_entity.Parent = Rig_Models
						build_rig(Rig_Models,get_identical_entity)
					end
					
					local entity_head = Rig_Models:FindFirstChild(">>".. Rig_Models.Name .. "<<_Head")	
					Find_FACE_EXPRESSION_EMULATOR (Rig_Models,entity_head)
				end

			end
		end
	end
	--███████████████████████████████▀████████████████████████████████████████
	--█▄─▄▄▀██▀▄─██▄─▀█▀─▄██▀▄─██─▄▄▄▄█▄─▄▄─███─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─█
	--██─██─██─▀─███─█▄█─███─▀─██─██▄─██─▄█▀███▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄█
	--▀▄▄▄▄▀▀▄▄▀▄▄▀▄▄▄▀▄▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀
	
	--Stop Animation by attack
	local Trigger_Damage,Trigger_GetBack = MD_.FF:Damage_Events(Model,Model,C.Team)

	--█████████████████████████████████████████████████████████████
	--█▄─▀█▀─▄██▀▄─██▄─▄█▄─▀█▄─▄███─▄▄▄▄█─▄▄▄─█▄─▄▄─█▄─▀█▄─▄█▄─▄▄─█
	--██─█▄█─███─▀─███─███─█▄▀─████▄▄▄▄─█─███▀██─▄█▀██─█▄▀─███─▄█▀█
	--▀▄▄▄▀▄▄▄▀▄▄▀▄▄▀▄▄▄▀▄▄▄▀▀▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▀▀▄▄▀▄▄▄▄▄▀
	
	-- STOP THE SCENE ANIMATION DEFINITELY 
	function Scene_Shared:FinishSceneDefinitive()
		TBC____.Scene_Config:Stop_Scene()
	end
	
	-- STARTS THE SCENE ANIMATIONS
	function Scene_Shared:StartScene()
		local PlayingAnimations = __GAT(AnimationController)
		for _,PlayingAnimation in pairs(PlayingAnimations) do
			PlayingAnimation:Stop(0)
		end
		SCENE_CONFIG:Start_Scene_Process(Current_Pose,Scene_Shared)
	end
	
	-- IF PLAYER, RETARTS THE ANIMATION, IF BOT, FINISH THE ANIMATION
	function Scene_Shared:FinishScene()
		if TBC____.ImPlayer then
			local UI_Clone = _G.Game_UI:FindFirstChild("nigga_screen"):Clone()
			UI_Clone.Parent = _G.Player.PlayerGui
			_Services.Debris:AddItem(UI_Clone,.25)
			Scene_Shared:StartScene()
		else
			Scene_Shared:FinishSceneDefinitive()
		end
	end

	--████████████████████████████████████████████████████████████████████████████████████████████████████████████████
	--██▀▄─██▄─▀█▄─▄█▄─▄█▄─▀█▀─▄██▀▄─██─▄─▄─█─▄▄─█▄─▄▄▀███─▄▄▄─█─▄▄─█▄─▀█▄─▄█─▄─▄─█▄─▄▄▀█─▄▄─█▄─▄███▄─▄███▄─▄▄─█▄─▄▄▀█
	--██─▀─███─█▄▀─███─███─█▄█─███─▀─████─███─██─██─▄─▄███─███▀█─██─██─█▄▀─████─████─▄─▄█─██─██─██▀██─██▀██─▄█▀██─▄─▄█
	--▀▄▄▀▄▄▀▄▄▄▀▀▄▄▀▄▄▄▀▄▄▄▀▄▄▄▀▄▄▀▄▄▀▀▄▄▄▀▀▄▄▄▄▀▄▄▀▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▄▄▀▀▄▄▄▀▀▄▄▀▄▄▀▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▄▄▄▀▄▄▀▄▄▀
	
	function Scene_Shared:PlaySceneAnimation(AnimationName,Transition,C)
		local C = C or {}
		Scene_Shared.Stopped=false
		local AnimationInstance = Scene_Shared:GetAnimationInstance(AnimationName)
		local Animation = __LA(AnimationController, AnimationInstance)
		
		for i,v in pairs (GetMarkerReachedSignal) do v:Disconnect() v=nil end GetMarkerReachedSignal = {}
		TA_IN(GetMarkerReachedSignal,Animation.Stopped:Connect(function()
			Scene_Shared.Stopped=true
			Animation:AdjustSpeed(0)
			if SCENE_CONFIG.Stopped_Function then
				SCENE_CONFIG:Stopped_Function()
				SCENE_CONFIG.Stopped_Function=nil
			end
		end))
		TA_IN(GetMarkerReachedSignal,Animation.DidLoop:Connect(function()
			if SCENE_CONFIG.Looped_Function then
				SCENE_CONFIG:Looped_Function()
				if not SCENE_CONFIG.Looped_Keep then
					SCENE_CONFIG.Looped_Function=nil
				end
			end
		end))
		TA_IN(GetMarkerReachedSignal,Animation:GetMarkerReachedSignal("Especial"):Connect(function(value)
			if value == "Stop" then
				Scene_Shared.Stopped=true
				Animation:AdjustSpeed(0)
				if SCENE_CONFIG.Stopped_Function then
					SCENE_CONFIG:Stopped_Function()
					SCENE_CONFIG.Stopped_Function=nil
				end
			elseif value == "Trans" then
				if SCENE_CONFIG.Transition_Function then
					SCENE_CONFIG:Transition_Function()
					SCENE_CONFIG.Transition_Function=nil
				end
			elseif SCENE_CONFIG.Especial_Animation_Events and SCENE_CONFIG.Especial_Animation_Events[value] then
				SCENE_CONFIG.Especial_Animation_Events[value]()
			end
		end))
		-- Face controller for scenes
		TA_IN(GetMarkerReachedSignal,Animation:GetMarkerReachedSignal("FacePlayer"):Connect(function(value)
			local table_expressions = string.split(value,"===")
			Scene_Shared:Face_Changer_Event(table_expressions[1],table_expressions[2],"Player")
		end))
		TA_IN(GetMarkerReachedSignal,Animation:GetMarkerReachedSignal("Face"):Connect(function(value)
			local table_expressions = string.split(value,"===")
			Scene_Shared:Face_Changer_Event(table_expressions[1],table_expressions[2])
		end))
		if Scene_Shared.CurrentAnimation and not C.NoStopOther then
			Scene_Shared.CurrentAnimation:Stop(Transition)
		end
		
		Scene_Shared.CurrentAnimation=Animation
		Animation:Play(Transition)
		if C.Speed then
			Animation:AdjustSpeed(C.Speed)
		end
	end

	--███████████████████████████████████████████████████
	--█▄─▀█▀─▄██▀▄─██▄─▄█▄─▀█▄─▄███▄─▄███─▄▄─█─▄▄─█▄─▄▄─█
	--██─█▄█─███─▀─███─███─█▄▀─█████─██▀█─██─█─██─██─▄▄▄█
	--▀▄▄▄▀▄▄▄▀▄▄▀▄▄▀▄▄▄▀▄▄▄▀▀▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▀
	
	coroutine.wrap(function()
		while _Services.Run.RenderStepped:Wait() and Model:IsDescendantOf(game) do
			if (Trigger_Damage.Value or Trigger_GetBack.Value) and WaitUntilTick - tick() < 0 then
				Scene_Shared:FinishSceneDefinitive()
				break
			end
			if SCENE_CONFIG.Loop_Scene_Process and not TBC____.Scene_Config.Pause then
				if Scene_Shared.Pause_State and  Scene_Shared.CurrentAnimation and Scene_Shared.SaveSpeedCurrentAnimation then
					Scene_Shared.CurrentAnimation:AdjustSpeed(Scene_Shared.SaveSpeedCurrentAnimation)
					Scene_Shared.SaveSpeedCurrentAnimation = nil
				end
				Scene_Shared.Pause_State = nil
				if not TBC____.Scene_Config.OnLoop then
					SCENE_CONFIG:Loop_Scene_Process()
				end
			elseif not Scene_Shared.Pause_State then
				Scene_Shared.Pause_State = true
				if Scene_Shared.CurrentAnimation then
					Scene_Shared.SaveSpeedCurrentAnimation = Scene_Shared.CurrentAnimation.Speed
					Scene_Shared.CurrentAnimation:AdjustSpeed(0)
				end
			end
			Trigger_Damage.Value = false
			Trigger_GetBack.Value = false
		end
		for i,v in pairs (GetMarkerReachedSignal) do v:Disconnect() v=nil end GetMarkerReachedSignal = {}
	end)()
	
	--████████████████████████████████████████████████████████████████
	--█▄─▄▄─█▄─▄█▄─▀█▄─▄██▀▄─██▄─▄█████─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─█
	--██─▄████─███─█▄▀─███─▀─███─██▀███▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄█
	--▀▄▄▄▀▀▀▄▄▄▀▄▄▄▀▀▄▄▀▄▄▀▄▄▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀
	
	-- final addition
	spawn(function() wait()
		Scene_Shared:StartScene()
		-- angle offset
		local angle_extra = CFA(0,0,0)			
		if MAIN_SCENERY_PART:FindFirstChild("ANGLE_START") then angle_extra=MAIN_SCENERY_PART:FindFirstChild("ANGLE_START").Value end
		MAIN_SCENERY_PART.CFrame*=angle_extra
	end)
	
end

return module
]=]
