local module = {}
local MD_ = _G._MD
local CurrentMusicState,Playing_Music,Time_To_Change,Current_Music_Track,Current_Music_Config,Current_Music_Volume
local Musics_Archieve,Music_connections = {},{}
local Musics_CONFIG={
	["Intermission"]={Change_After_Loop=true;Time_To_Change=1;Can_Pause_Music=true};
	["WaveMode_1"]={Change_After_Loop=true;Time_To_Change=0;Can_Pause_Music=false};
}

function module:Setup_Music()
	local function return_music_ta(music)
		return {Music=music;Volume=music.Volume}
	end
	for _,v in next,_G.OST_Folder:GetChildren() do
		if v:IsA("Folder") then
			for _,music in next,v:GetChildren() do
				Musics_Archieve[v.Name] = Musics_Archieve[v.Name] or {} -- if Musics_Archieve dosent exist
				table.insert(Musics_Archieve[v.Name],return_music_ta(music))
				Musics_CONFIG[v.Name] = Musics_CONFIG[v.Name] or {}
			end
		elseif v:IsA("Sound") then
			local music = v
			Musics_Archieve[music.Name] = return_music_ta(music)
			Musics_CONFIG[music.Name] = Musics_CONFIG[music.Name] or {}
		end
	end
end

function module:Loop_Music()
	if Time_To_Change and Time_To_Change - tick() then Time_To_Change = nil Playing_Music = false end
	
	--█████████████
	--█████████████
	if MD_.FF:not_empty__switch(MD_.Meta_Elements.MUSIC_UnAVAILABLE.LockSwitch) then
		--█▀▄▀█ █░░█ ▀▀█▀▀ █▀▀ █▀▀ 
		--█░▀░█ █░░█ ░░█░░ █▀▀ ▀▀█ 
		--▀░░░▀ ░▀▀▀ ░░▀░░ ▀▀▀ ▀▀▀
		-- if there's some music playing, mute toggle pauses the music
		if Playing_Music and Current_Music_Track and Current_Music_Config then
			Playing_Music = false
			if Current_Music_Config.Can_Pause_Music then -- if pause option is available
				Current_Music_Track:Pause()
				Current_Music_Config.Paused_State = true
			else -- stop 
				Current_Music_Track:Stop()
			end
		end
		--█████████████
		--█████████████
	else
		--▀█░█▀ █▀▀█ █░░ █░░█ █▀▄▀█ █▀▀ 　 █▀▄▀█ █▀▀█ █▀▀▄ █▀▀█ █▀▀▀ █▀▀ █▀▀█ 
		--░█▄█░ █░░█ █░░ █░░█ █░▀░█ █▀▀ 　 █░▀░█ █▄▄█ █░░█ █▄▄█ █░▀█ █▀▀ █▄▄▀ 
		--░░▀░░ ▀▀▀▀ ▀▀▀ ░▀▀▀ ▀░░░▀ ▀▀▀ 　 ▀░░░▀ ▀░░▀ ▀░░▀ ▀░░▀ ▀▀▀▀ ▀▀▀ ▀░▀▀
		
		if Current_Music_Volume and Current_Music_Track then
			Current_Music_Track.Volume = Current_Music_Volume*MD_.MUSIC_VOLUME/100
		end
		
		--█▀▀█ █░░ █▀▀█ █░░█ █▀▀ 
		--█░░█ █░░ █▄▄█ █▄▄█ ▀▀█ 
		--█▀▀▀ ▀▀▀ ▀░░▀ ▄▄▄█ ▀▀▀
		
		if MD_.CurrentMusic ~= CurrentMusicState or not Playing_Music then
			for _,v in pairs (Music_connections) do v:Disconnect() v=nil end
			Time_To_Change = nil
			CurrentMusicState = MD_.CurrentMusic -- to prevent changing music all the time
			Playing_Music = true -- important to let system know that the music is playing
			-- get music table
			local Music_Info = Musics_Archieve[CurrentMusicState]
			-- if music instance IsA table then returns a random music from the table
			if typeof(Music_Info) == "table" then Music_Info = Music_Info[M_RAN(1,#Music_Info)] end
			-- if the music was paused in cache, then the old music returns
			local MusicConfig = Musics_CONFIG[CurrentMusicState]
			if MusicConfig.Paused_State then Music_Info = MusicConfig.Current_Music_Info end
			-- get music track
			local MusicTrack = Music_Info.Music
			local MusicVolume = Music_Info.Volume
			--█████████████
			--█████████████
			-- playing music process
			if Current_Music_Track then Current_Music_Track:Stop() end -- stop old music
			Current_Music_Track = MusicTrack -- set current track playing
			Current_Music_Track.Volume = MusicVolume*MD_.MUSIC_VOLUME/100 -- set volume according to setting
			Current_Music_Config = MusicConfig -- set current music config
			Current_Music_Volume = MusicVolume -- set current music volume
			MusicConfig.Current_Music_Info = Music_Info -- stores current music info in music config
			if MusicConfig.Paused_State then -- in case the music was paused
				MusicConfig.Paused_State = nil
				Current_Music_Track:Resume()
			else -- play the music from the beggining
				Current_Music_Track:Play()
			end
			MD_.Current_Music_Track=Current_Music_Track
			--█████████████
			--█████████████
			-- events
			local function update_music_list()
				Playing_Music = false
				MusicConfig.Paused_State = false
			end
			TA_IN(Music_connections,Current_Music_Track.Ended:Connect(update_music_list))
			TA_IN(Music_connections,Current_Music_Track.DidLoop:Connect(function()
				if Current_Music_Config.Change_After_Loop then
					update_music_list()
				end
			end))
			--█████████████
			--█████████████
			--
		end
	end
end

return module
]=]
