	--░░▀░░ ▀▀▀ ▀░░░▀ ▀▀▀ ▀░░▀ ▀▀▀▀
	
	do
		wait(1*c_timing_multiplier)
		pcall(function() _short_screen() end)
		TickingSFX:Play()
		wait(1*c_timing_multiplier)
	end
	--

	--█▀▀ █▀▀█ █░░█ █▀▀▄ ▀▀█▀▀ █▀▀▄ █▀▀█ █░░░█ █▀▀▄ 
	--█░░ █░░█ █░░█ █░░█ ░░█░░ █░░█ █░░█ █▄█▄█ █░░█ 
	--▀▀▀ ▀▀▀▀ ░▀▀▀ ▀░░▀ ░░▀░░ ▀▀▀░ ▀▀▀▀ ░▀░▀░ ▀░░▀

	do
		local SPH1 = __SPHERE_COUNT:FindFirstChild("1")
		local SPH2 = __SPHERE_COUNT:FindFirstChild("2")
		local SPH3 = __SPHERE_COUNT:FindFirstChild("3")
		local SPHSTART = __SPHERE_COUNT:FindFirstChild("STT")	
		local REAL_SPHERE_COUNT = __SPHERE_COUNT:FindFirstChild("__REAL_SPHERE_COUNT")
		SPH1.Visible = false SPH2.Visible = SPH1.Visible SPH3.Visible = SPH1.Visible SPHSTART.Visible = SPH1.Visible
		
		local function _number_show(UI,COLOR)
			UI.Visible = true
			UI.Size = UDim2.fromScale(4,0)
			REAL_SPHERE_COUNT.Size = UDim2.fromScale(1.5,1.5)
			REAL_SPHERE_COUNT.BackgroundTransparency = 1
			MD_.FF:PlaySound(REAL_SPHERE_COUNT,"UI_WaveCount1",{PlayOnRemove=true})
			MD_.FF:PlaySound(REAL_SPHERE_COUNT,"UI_WaveCount2",{PlayOnRemove=true})
			_Services.Tween:Create(REAL_SPHERE_COUNT,TWEEN_IN(.5*c_timing_multiplier,Tween_Styles.Bounce,Tween_Directions.Out,0,false,0),{Size=UDim2.fromScale(.85,.85);BackgroundTransparency=.5}) :Play()
			_Services.Tween:Create(UI,TWEEN_IN(.5*c_timing_multiplier,Tween_Styles.Back,Tween_Directions.Out,0,false,0),{Size=UDim2.fromScale(1,1)}) :Play()
			wait(1*c_timing_multiplier)
			UI.Visible = false
		end

		__SPHERE_COUNT.Position = UDim2.fromScale(.5,.5)
		__SPHERE_COUNT.Size = UDim2.fromScale(1.5,1.5)
		REAL_SPHERE_COUNT .Size = UDim2.fromScale(0.95,0.95)
		REAL_SPHERE_COUNT.BackgroundTransparency = 1
		__SPHERE_COUNT.Visible = true
		_Services.Tween:Create(REAL_SPHERE_COUNT,TWEEN_IN(.5*c_timing_multiplier,Tween_Styles.Sine,Tween_Directions.Out,0,false,0),{BackgroundTransparency=0.3}) :Play()
		_Services.Tween:Create(__SPHERE_COUNT,TWEEN_IN(.5*c_timing_multiplier,Tween_Styles.Sine,Tween_Directions.Out,0,false,0),{Position=UDim2.fromScale(.5,.5);Size=UDim2.fromScale(0.25,0.25)}) :Play()
		wait(1*c_timing_multiplier)
		_number_show(SPH3)
		_number_show(SPH2)
		_number_show(SPH1)
		TickingSFX:Destroy()
		do -- start show
			SPHSTART.Visible = true
			SPHSTART.Size = UDim2.fromScale(0,0)
			REAL_SPHERE_COUNT.Size = UDim2.fromScale(2,2)
			REAL_SPHERE_COUNT.BackgroundTransparency = .5
			REAL_SPHERE_COUNT.BackgroundColor3=Color3.fromRGB(0, 0, 0)
			_Services.Tween:Create(REAL_SPHERE_COUNT,TWEEN_IN(2*c_timing_multiplier,Tween_Styles.Sine,Tween_Directions.Out,0,false,0),{Size=UDim2.fromScale(0,0);BackgroundTransparency=1}) :Play()
			_Services.Tween:Create(SPHSTART,TWEEN_IN(.5*c_timing_multiplier,Tween_Styles.Bounce,Tween_Directions.Out,0,false,0),{Size=UDim2.fromScale(4.5,1.4)}) :Play()
			spawn(function()
				wait(1.25*c_timing_multiplier)
				_Services.Tween:Create(__SPHERE_COUNT,TWEEN_IN(.45*c_timing_multiplier,Tween_Styles.Back,Tween_Directions.In,0,false,0),{Size=UDim2.fromScale(0,0)}) :Play()
				wait(.5*c_timing_multiplier)
				__SPHERE_COUNT.Visible = false
			end)
		end
	end
	
	UI_MENU.Visible = true
 	MD_.FF:PlaySound(Wave_UI,"UI_StartWaveMode3",{PlayOnRemove=true})
	MD_.FF:PlaySound(Wave_UI,"UI_StartWaveMode4",{PlayOnRemove=true})
	MD_.CurrentMusic = "WaveMode_1"
	MD_.FF:check__switch({BB=nil,TM=MD_.Meta_Elements.MUSIC_UnAVAILABLE,TS=MD_.Meta_Elements.WAVE_MODE,NN=nil,FF=nil}) 
	
	--█████████████████████████████████████████████████
	--█▄─▄█─▄─▄─█▄─▄▄─█▄─▀█▀─▄███▄─▄███▄─▄█─▄▄▄▄█─▄─▄─█
	--██─████─████─▄█▀██─█▄█─█████─██▀██─██▄▄▄▄─███─███
	--▀▄▄▄▀▀▄▄▄▀▀▄▄▄▄▄▀▄▄▄▀▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀
	
	local WaveItemsFolder = _G.Objects_Scripts:FindFirstChild("Wave_Items") 
	
	local ITEM_LIST = {
		["Heart"]=function(SPAWNCF)
			local HEART_MODEL = WaveItemsFolder:FindFirstChild("Heart"):Clone() 
			local MainPart,_1,_2 = HEART_MODEL.MainPart,HEART_MODEL._1,HEART_MODEL._2
			HEART_MODEL.Parent = Items_Folder
			MainPart.CFrame = SPAWNCF + Vector3.new(0,2,0)
			local CF = MainPart.CFrame 
			
			local size_MainPart,size__1,size__2 = MainPart.Size,_1.Size,_2.Size
			Events[HEART_MODEL] = {}
			
			Events[HEART_MODEL].stepped = _Services.Run.Stepped:Connect(function()
				if MD_.Current_Music_Track then
					local amplitude = math.clamp(MD_.Current_Music_Track.PlaybackLoudness / 480, 0, 1) + .5
					local amv = Vector3.new(amplitude,amplitude,amplitude)
					MainPart.Size = size_MainPart * amv
					_1.Size = size__1 * amv
					_2.Size = size__2 * amv
				end
				HEART_MODEL.MainPart.CFrame = CF * CFrame.new(0,math.sin(math.rad((tick()*150)%360)),0)  * CFrame.Angles(0,math.rad((tick()*250)%360),0) 
			end)
			
			Events[HEART_MODEL].touched = MainPart.Touched:Connect(function(human)
				if human:IsA("BasePart") and human.Parent:FindFirstChild("Humanoid") and MD_.Re_Bots[human.Parent] then
					local bot_info = MD_.Re_Bots[human.Parent]
					if bot_info.ImPlayer then
						delete_event(Events[HEART_MODEL])
						Events[HEART_MODEL] = nil
						local max = math.random(4,7)
						MD_.FF:SafeRemove(HEART_MODEL)
						bot_info:heal_hearts()
						local clone_main = MainPart:Clone()
					
						MD_.FF:PlaySound(Wave_UI,"Player_Healed",{PlayOnRemove=true})
						MD_.FF:PlaySound(Wave_UI,"Player_Heal_Heart",{PlayOnRemove=true})
						clone_main.Parent = _Services.Workspace.Terrain
						clone_main.Anchored = true
						clone_main.Size = size_MainPart*.4
						_Services.Debris:AddItem(clone_main,.25)
						_Services.Tween:Create(clone_main,TWEEN_IN(.25,Enum.EasingStyle.Quad,Enum.EasingDirection.Out,0,false,0),{Transparency=1;Size=size_MainPart*3}):Play()
						
						for i=1,max do 
							local p = Instance.new("WedgePart",_Services.Workspace.Terrain)
							p.Color = _1.Color
							p.Material = _1.Material
							p.Reflectance = _1.Reflectance
							p.Transparency = _1.Transparency
							p.CFrame = MainPart.CFrame
							p.Size = Vector3.new(math.random(90,120)/100,math.random(90,120)/100,math.random(90,120)/100)
							local orange_cf = CFrame.new(Vector3.new(),MainPart.CFrame.lookVector)*CFrame.Angles(0,math.rad((i*360)/max),0)
							p.Velocity = orange_cf.LookVector*25
							_Services.Tween:Create(p,TWEEN_IN(1,Enum.EasingStyle.Sine,Enum.EasingDirection.Out,0,false,2),{Transparency=1}):Play()
							_Services.Debris:AddItem(p,3)
						end
						HEART_MODEL:Destroy()	
					end
				end
			end)
		end,
	}
	
	--███████████████████████
	--█▄─▄███─▄▄─█─▄▄─█▄─▄▄─█
	--██─██▀█─██─█─██─██─▄▄▄█
	--▀▄▄▄▄▄▀▄▄▄▄▀▄▄▄▄▀▄▄▄▀▀▀

	local function SPAWN_ENEMY(Entity_Name)
		local Rig_Entity = _Services.RepliStorage.Characters.Entity:FindFirstChild(Entity_Name).Rig:Clone()
		Rig_Entity.Parent = Enemy_Folder
		Rig_Entity.HumanoidRootPart.Anchored = true
		
		local Random_Plr_Spawn = Spawns_Types.Enemies[math.random(1,#Spawns_Types.Enemies)]
		local RootPart = Rig_Entity:FindFirstChild("HumanoidRootPart")
		RootPart.CFrame = Random_Plr_Spawn*CFrame.new(0,RootPart.Size.Y,0)

		local Entity_Name_User = INST("StringValue",Rig_Entity)
		Entity_Name_User.Name = "Entity_Name_User"
		Entity_Name_User.Value = Entity_Name
		MD_.FF:LoadCharacter(Entity_Name_User,true)
	end
	
	local function SPAWN_ITEM(Item_Name)
		local Random_Plr_Spawn = Spawns_Types.Items[math.random(1,#Spawns_Types.Items)]
		ITEM_LIST[Item_Name](Random_Plr_Spawn)
	end

	--███████████████████████████████████████████████████████████████
	--█▄─█▀▀▀█─▄██▀▄─██▄─█─▄█▄─▄▄─███─▄▄▄─█▄─██─▄█▄─▄▄─█▄─██─▄█▄─▄▄─█
	--██─█─█─█─███─▀─███▄▀▄███─▄█▀███─██▀─██─██─███─▄█▀██─██─███─▄█▀█
	--▀▀▄▄▄▀▄▄▄▀▀▄▄▀▄▄▀▀▀▄▀▀▀▄▄▄▄▄▀▀▀───▄▄▀▀▄▄▄▄▀▀▄▄▄▄▄▀▀▄▄▄▄▀▀▄▄▄▄▄▀
	
	local TIME = tick() + 280
	local CURRENT_WAVE = "1"
	
	local __WAVE__LOADER__ = {
		["1"]={
			Wave_Spawn = {
				--{Enemy="Noob";SpawnAt=280;Amount=7};
				--4 noobs 5 seconds
				{Enemy="Noob";SpawnAt=270;Amount=1};
				{Enemy="Noob";SpawnAt=265;Amount=1};
				{Enemy="Noob";SpawnAt=260;Amount=1};
				{Enemy="Noob";SpawnAt=255;Amount=1};
				----spawn hearts to heal yourself
				{Item="Heart";SpawnAt=240;Amount=1};
				----
				{Enemy="Noob";SpawnAt=230;Amount=2};
				{Enemy="Noob";SpawnAt=220;Amount=1};
				{Enemy="Noob";SpawnAt=210;Amount=2};
				{Enemy="Noob";SpawnAt=200;Amount=1};
				----spawn hearts to heal yourself
				{Item="Heart";SpawnAt=195;Amount=1};
				--
			};
		};
		
	}
	
	--██████████████████████████████████████████████████████████████
	--█▄─█▀▀▀█─▄██▀▄─██▄─█─▄█▄─▄▄─███─▄▄▄▄█▄─▄▄─█─▄─▄─█▄─██─▄█▄─▄▄─█
	--██─█─█─█─███─▀─███▄▀▄███─▄█▀███▄▄▄▄─██─▄█▀███─████─██─███─▄▄▄█
	--▀▀▄▄▄▀▄▄▄▀▀▄▄▀▄▄▀▀▀▄▀▀▀▄▄▄▄▄▀▀▀▄▄▄▄▄▀▄▄▄▄▄▀▀▄▄▄▀▀▀▄▄▄▄▀▀▄▄▄▀▀▀
	
	local function PRESENT_WAVE(CURRENT_WAVE)
		UI_MENU.WAVE_COUNT.Text = "Wave " .. CURRENT_WAVE
	end PRESENT_WAVE(CURRENT_WAVE)
	
	local function update_enemy_list()
		local amount = 0
		for i,v in pairs (Enemy_Folder:GetDescendants()) do
			if v:IsA("Humanoid") then
				amount+=1
			end
		end
		UI_MENU.ENEMIES_COUNT.Text = "Enemies: " .. amount
	end update_enemy_list()
	
	local function update_units_list()
		local amount = 0
		for i,v in pairs (Units_Folder:GetDescendants()) do
			if v:IsA("Humanoid") then
				amount+=1
			end
		end
		MD_.WAVE_UNITS_COUNT = amount
		UI_MENU.UNITS_COUNT.Text = "Units: " .. amount
	end update_enemy_list()

	table.insert(Events,Enemy_Folder.ChildAdded:Connect(update_enemy_list))
	table.insert(Events,Enemy_Folder.ChildRemoved:Connect(update_enemy_list))

	table.insert(Events,Units_Folder.ChildAdded:Connect(update_units_list))
	table.insert(Events,Units_Folder.ChildRemoved:Connect(update_units_list))
	
	while wait() do
		UI_MENU.TIME_COUNT.Text = MD_.FF:convertToHMS(TIME-tick())
		-- ADDS THE ENEMY IN THE ENEMY FOLDER
		for _,v in pairs (__WAVE__LOADER__[CURRENT_WAVE].Wave_Spawn) do
			if v.Already_Checked then continue end
			if v.SpawnAt >= TIME-tick() then 
				v.Already_Checked = true 
				for i=1,v.Amount do 
					if v.Enemy then 
						SPAWN_ENEMY(v.Enemy) 
					elseif v.Item then 
						SPAWN_ITEM(v.Item) 
					end 
				end 
			end 
			break
		end
		--HEALTH MANAGER
		if Trigger_Damage.Value then
			Trigger_Damage.Value = nil
			local DamageAmount = Trigger_Damage:GetAttribute("DamageAmount") or 1
			CURRENT_HEALTH -= DamageAmount
			Trigger_Damage:SetAttribute("EntityTableID",nil)
			Trigger_Damage:SetAttribute("DamageAmount",nil)
		end
		HEALTH_BAR_PROGRESS.Size = UDim2.fromScale(CURRENT_HEALTH/MAX_HEALTH,1)
		HEALTH_BAR_COUNT.Text = CURRENT_HEALTH .. "/" .. MAX_HEALTH
	end
	
	return true
end

return module
]=]
