return function (SCENE_CONFIG,CC,CFrame_Angle)
	local Face_Event_String = CC.Face_Event_String
	local TARGET_OBJECT= Face_Event_String:FindFirstChild("TARGET_OBJECT")
	local TARGET_OFFSET= TARGET_OBJECT:FindFirstChild("TARGET_OFFSET")
	local Noob_HEAD_ENT2 = CC.Model.Rig_Entity_2:FindFirstChild(">>Rig_Entity_2<<_Head")
	local Noob_HEAD_DICk_ENT2 = CC.Model.Rig_Entity_2:FindFirstChild(">>Rig_Entity_2<<_Dick_Head")
	local Head_String_Position = SCENE_CONFIG.Head_String_Position;
	local oldtick_start_scene_2,oldtick_start_scene_3,speed_up,oldtick_start_scene_4,oldtick_start_scene_5,oldtick_start_scene_6
	local Breath_1 = CC:PlaySceneSound(Head_String_Position,"Breath_001",{ReturnSound=true,Player_Style=true})
	
	CFrame_Angle.Value = CFrame.Angles(0,math.rad(90),0)
	CC:PlaySceneAnimation("EP1_Loop_1")
	CC:PlaySceneSound(Head_String_Position,"MMMMM_004",{Player_Style=true})
	CC:Face_Changer_Event(Head_String_Position,"Animated_Face","Player")
	Face_Event_String.Value = "24"
	
	oldtick_start_scene_2 = tick() + 8
	
	local ticker1 = 0
	
	--████████████████████████████████████████████████████████████████████████████████████████████
	--████████████████████████████████████████████████████████████████████████████████████████████
	--████████████████████████████████████████████████████████████████████████████████████████████
	
	local function repeat_sfx_fc (x)
		local sf = CC:PlaySceneSound(Head_String_Position,x,{Player_Style=true;ReturnSound=true}) 
		local TimeLength = sf.TimeLength * sf.PlaybackSpeed
		sf.PlayOnRemove = true 
		sf:Destroy()
		return TimeLength
	end
	
	--████████████████████████████████████████████████████████████████████████████████████████████
	--████████████████████████████████████████████████████████████████████████████████████████████
	--████████████████████████████████████████████████████████████████████████████████████████████
	
	SCENE_CONFIG.Especial_Animation_Events={
		["Loop_1_a"]=function()
			CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Slosh_003")
			if ticker1 - tick() < 0 then
				ticker1 = tick() + repeat_sfx_fc({"MMMMM_001","Ahhh_002","Moan_Light_007","Moan_Light_009"})
			end
		end,
		["Loop_2_a"]=function()
			if ticker1 - tick() < 0 then
				ticker1 = tick() + repeat_sfx_fc({"Ahhh_009","Ahhh_003"})
			end
			CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Slosh_003")
			CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Slap_002")
		end,
		
		["Loop_3_a"]=function()
			if ticker1 - tick() < 0 then
				ticker1 = tick() + repeat_sfx_fc({"Moan_003","Moan_001"})
			end
			CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Slosh_003")
			CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Slap_002")
			CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Slosh_007")
		end,
	}
	
	--████████████████████████████████████████████████████████████████████████████████████████████
	--████████████████████████████████████████████████████████████████████████████████████████████
	--████████████████████████████████████████████████████████████████████████████████████████████
	
	function SCENE_CONFIG:Loop_Scene_Process()
		if oldtick_start_scene_2 and oldtick_start_scene_2 - tick() < 0 then
			oldtick_start_scene_2 = nil
			SCENE_CONFIG.Looped_Function=function()
				SCENE_CONFIG.Looped_Function = nil
				CC:PlaySceneAnimation("EP1_Loop_2",.35)
				oldtick_start_scene_3 = tick()+5
				CC:PlaySceneSound(Head_String_Position,"Moan_001",{Player_Style=true})
				Face_Event_String.Value = "25"
			end
		elseif oldtick_start_scene_3 and oldtick_start_scene_3 - tick() < 0 then
			oldtick_start_scene_3 = nil
			SCENE_CONFIG.Looped_Function=function()
				SCENE_CONFIG.Looped_Function = nil
				CC:PlaySceneAnimation("EP1_Loop_3",.35)
				Face_Event_String.Value = "26"
				speed_up=.1
				oldtick_start_scene_4 = true
				CC:PlaySceneSound(Head_String_Position,"Moan_006",{Player_Style=true})
			end
		elseif speed_up and oldtick_start_scene_4 then
			speed_up+= 0.012
			CC.CurrentAnimation:AdjustSpeed(1+speed_up)
			if speed_up > 3 then
				oldtick_start_scene_4 = nil
				SCENE_CONFIG.Looped_Function=function()
					SCENE_CONFIG.Looped_Function = nil
					oldtick_start_scene_5 = tick()+5
					Breath_1:Play()
					Face_Event_String.Value = "27"
					CC:PlaySceneSound(Head_String_Position,"Moan_After_Session_001",{Player_Style=true})
					CC:PlaySceneAnimation("EP1_Cum")
					CC:Transparency_Parts("FacialCumPartPlayer",.05)
					spawn(function()
						for i=1,4 do
							if CC.Model:IsDescendantOf(game) and oldtick_start_scene_5 then
								CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Slide_001")
								CC:PlaySceneSound(Noob_HEAD_DICk_ENT2,"Smack_001")
								CC:Cum_Event(CC.Model.Rig_Entity_2,"CumPart","CUM_ORIGIN_PART",{Segments=9,offset_angle=CFrame.Angles(0,math.rad(-15),0),Velocity=math.random(800,1100)/100,Size=.15,Ballsocket_mag=.25,SpreadX=15,SpreadY=0,SpreadZ=10,Tick_start_touching=.21})
								wait(math.random(200,1200)/4000)
							else
								break
							end
						end
					end)
				end
			end
		elseif oldtick_start_scene_5 and oldtick_start_scene_5 - tick() < 0 then
			oldtick_start_scene_5=nil
			CC:FinishScene()
			Breath_1:Destroy()
		end
	end
end]=]
