local modulo = {}

--████
--████
--████

function modulo:CLEAN_TOOL_MODEL(model,mainpart)
	for i,v in pairs (model:GetDescendants()) do
		if v:IsA("BasePart") then
			if mainpart ~= v then
				modulo:Weld(mainpart,v).Parent = mainpart
			end
			v.CanCollide = false
			v.Anchored = false
			v.CanTouch = false
			local Propiedades = PHYSIPRO (0, 0, 0, 0, 0)
			v.CustomPhysicalProperties = Propiedades
		end
	end
end

function modulo:ACCESORY_SETUP(Model,AttachPart)
	local MainPart = Model:FindFirstChild("MainPart")
	for i,v in pairs (Model:GetDescendants()) do
		if v:IsA("BasePart") then
			if MainPart ~= v then
				local w = modulo:Weld(MainPart,v)
				w.Parent = MainPart
				w.Name = "Weld_" .. v.Name
			end
			v.CanCollide = false
			v.Anchored = false
			v.CanTouch = false
			local Propiedades = PHYSIPRO (0, 0, 0, 0, 0)
			v.CustomPhysicalProperties = Propiedades
		end
	end
	
	MainPart.CFrame = AttachPart.CFrame
	local w = modulo:Weld(MainPart,AttachPart)
	w.Parent = MainPart
	w.Name = "Main_Weld_"
	
	return MainPart
end


--████
--████
--████

function modulo.Save_UI_PROPIERTIES(TABLE,UI)
	if UI:IsA("ScrollingFrame") or  UI:IsA("Frame") or  UI:IsA("ImageLabel") or UI:IsA("TextBox") or UI:IsA("TextButton") or UI:IsA("TextLabel") or UI:IsA("ImageButton")  then
		TABLE[UI]={
			Size=UI.Size;
			Position=UI.Position;
			BackgroundColor3=UI.BackgroundColor3;
			Rotation=UI.Rotation;
		}
		if UI:IsA("TextBox") or UI:IsA("TextButton") or UI:IsA("TextLabel")  then
			TABLE[UI].TextColor3=UI.TextColor3
			TABLE[UI].TextStrokeColor3=UI.TextStrokeColor3
		end
	end
end

--████
--████
--████

function modulo:Random_Choose(Tabla)
	local chance_maximo = 0
	for _,ItemData in pairs(Tabla) do 
		chance_maximo = chance_maximo + M_CL(ItemData.__CHANCE,0,50000)
	end

	local Counter = 0
	local Chance = M_RAN(0,(chance_maximo))

	for _,ItemData in pairs(Tabla) do 
		Counter = Counter + M_CL(ItemData.__CHANCE,0,50000)
		if Chance <= Counter then
			return ItemData
		end
	end
	return false
end

--████
--████
--████

function modulo:GetDotFrom(Part : part,main_vector : vector_for_dot)
	local cf=Part.CFrame
	local sz=Part.Size
	local RETURN_VECTOR = cf.LookVector
	local RETURN_SIZE="Z"
	local function GetDotFromVector(vector) return vector:Dot(main_vector) end
	local function GetDotFromVectorName(vectorname,x,y) local vector = cf[vectorname] * x return GetDotFromVector(vector),vector,sz[y] end
	local function RepeatDotComparation(new_dot_,new_vector_,new_size_) if GetDotFromVector(RETURN_VECTOR) < new_dot_ then RETURN_VECTOR = new_vector_ RETURN_SIZE = new_size_ end end
	local new_dot_,new_vector_,new_size_=GetDotFromVectorName("LookVector"		,-1	,"Z") 		RepeatDotComparation(new_dot_,new_vector_,new_size_)
	local new_dot_,new_vector_,new_size_=GetDotFromVectorName("UpVector"		,1	,"Y") 		RepeatDotComparation(new_dot_,new_vector_,new_size_)
	local new_dot_,new_vector_,new_size_=GetDotFromVectorName("UpVector"		,-1	,"Y") 		RepeatDotComparation(new_dot_,new_vector_,new_size_)
	local new_dot_,new_vector_,new_size_=GetDotFromVectorName("RightVector"		,1	,"X") 		RepeatDotComparation(new_dot_,new_vector_,new_size_)
	local new_dot_,new_vector_,new_size_=GetDotFromVectorName("RightVector"		,-1	,"X") 		RepeatDotComparation(new_dot_,new_vector_,new_size_)
	return RETURN_VECTOR,RETURN_SIZE
end

--████
--████
--████

function modulo:FlipToVector(Part: part, Vector: vector)
	local function DOT_GET(vectorname,x,s) local x=x or 1 local vec = Part.CFrame[vectorname] * x return {vector=vec;s=s;dot=vec:Dot(Vector)} end
	local Dots_ = {LO_DOT=DOT_GET("LookVector",1,"Z"),BA_DOT=DOT_GET("LookVector",-1,"Z"),UP_DOT=DOT_GET("UpVector",1,"Y"),BO_DOT=DOT_GET("UpVector",-1,"Y"),RI_DOT=DOT_GET("RightVector",1,"X"),LE_DOT=DOT_GET("RightVector",-1,"X")}
	local Sort_Table_Get,n = {},0 for i,v in pairs (Dots_) do n+=1 table.insert(Sort_Table_Get,{dot=v.dot+math.rad(.1*n);vector=v.vector;name=i;s=v.s}) end table.sort(Sort_Table_Get, function(a, b) return a.dot>b.dot end)
	local cframe = CFrame.fromMatrix(Part.CFrame.p, Sort_Table_Get[3].vector, Sort_Table_Get[1].vector, Sort_Table_Get[2].vector)
	local size = Vector3.new(Part.Size[Sort_Table_Get[3].s],Part.Size[Sort_Table_Get[1].s],Part.Size[Sort_Table_Get[2].s])
	return cframe,size
end

--████
--████
--████

function modulo:SafeRemove(object)
	if object and object:IsDescendantOf(game) then
		for i,v in pairs (object:GetDescendants()) do
			if v:IsA("Trail") then
				v.Parent = _Services.Workspace.Terrain
				_Services.Debris:AddItem(v,v.Lifetime+2)
			elseif v:IsA("ParticleEmitter") then
				v.Parent = _Services.Workspace.Terrain
				v.Enabled = false
				_Services.Debris:AddItem(v,4)
			end
		end
		object:Destroy()
	end
end

--████
--████
--████

-- To damage Target
function modulo:WeakValue______(C)
	local WeakPointEntity,Damage,EntityTableID,Team,MyCharacter = C.WeakPointEntity,C.Damage,C.EntityTableID,C.Team,C.MyCharacter
	if WeakPointEntity:GetAttribute("Team") == Team or WeakPointEntity:IsDescendantOf(MyCharacter) then return end
	WeakPointEntity:SetAttribute("EntityTableID",EntityTableID)
	WeakPointEntity:SetAttribute("DamageAmount",Damage)
	WeakPointEntity.Value = true
	return true
end

-- Create Bullet

local Bullet_Style={
	["Default"]=function(C)
		local __st = {}
		function __st:get_bullet()
			local Bullet =  _Services.RepliStorage.Objects:FindFirstChild("Bullet_1"):Clone()
			Bullet.Name = "Bullet"
			Bullet.Anchored = false
			Bullet.CanCollide = false
