			BulletForce.Velocity = BulletMainPart.CFrame.lookVector*C.bullet_speed
			BulletForce.Parent = BulletMainPart
			
			BulletMainPart.Velocity = BulletMainPart.CFrame.lookVector*C.bullet_speed
			BulletMainPart.CanCollide = true
