			BulletMainPart.CustomPhysicalProperties = Propiedades
			
			local antiGravity = INST("BodyForce")
			antiGravity.Force = Vector3.new(0, BulletMainPart:GetMass() * _Services.Workspace.Gravity * 1, 0)
			antiGravity.Parent = BulletMainPart
