}

local Bullet_Detect = {
	["Raycast"] = function (C,__st)
		local origin,direction,bullet_speed,ignore_descendant,damage,EntityTableID,Team,Style = C.origin,C.direction,C.bullet_speed,C.ignore_descendant,C.damage,C.EntityTableID,C.Team,C.Style
		
		local Bullet = __st.Bullet
		local BulletMainPart = __st.BulletMainPart
		
		local LastPosition = BulletMainPart.Position
		
		local RayParams = RAPM()
		RayParams.FilterType = Enum.RaycastFilterType.Blacklist
		RayParams.FilterDescendantsInstances = {ignore_descendant,Bullet}
		
		spawn(function()
			local already_hit = {}
			while _Services.Run.RenderStepped:wait() and Bullet and Bullet:IsDescendantOf(game) do
				local raycastResult = modulo:CastUntilHitSimple(LastPosition,BulletMainPart.Position,RayParams)
				LastPosition = BulletMainPart.Position
				if raycastResult and raycastResult.Instance then
					local customhitbox = {
						CFrame=CFN(raycastResult.Position);
						Size=BulletMainPart.Size*VE3(3.5,3.5,3.5) ;
					}
					local erase
					for i,v in pairs (modulo:hitbox_detector(customhitbox,1,false)) do
						if v:FindFirstChild("WeakPointEntity") and not already_hit[v.WeakPointEntity.Value] then
							already_hit[v.WeakPointEntity.Value] = true
							if modulo:WeakValue______({WeakPointEntity=v.WeakPointEntity.Value,Damage=damage,EntityTableID=EntityTableID,Team=Team,MyCharacter=ignore_descendant}) then
								erase = true
							end
						end
					end
					if raycastResult.Instance.CanCollide or raycastResult.Instance:FindFirstChild("cast_tag") or erase then
						if (raycastResult.Instance:FindFirstChild("Ignore_RayCast_Value") == nil and raycastResult.Instance.Parent:FindFirstChildOfClass("Humanoid") == nil) or erase then
							modulo:SafeRemove(Bullet)
						end
					end
				end
			end
		end)

	end,
	["Physics"] = function (C,__st)
		local origin,direction,bullet_speed,ignore_descendant,damage,EntityTableID,Team,Style,Required_Velocity = C.origin,C.direction,C.bullet_speed,C.ignore_descendant,C.damage,C.EntityTableID,C.Team,C.Style,C.Required_Velocity

		local Bullet = __st.Bullet
		local BulletMainPart = __st.BulletMainPart
		BulletMainPart.CanTouch=true
		
		Required_Velocity = Required_Velocity or 45
		local TouchedBefore = {}

		local Debouncfe
		BulletMainPart.Touched:connect(function(Hit)
			if not TouchedBefore[Hit] and not Hit:IsDescendantOf(ignore_descendant) and not Hit:IsDescendantOf(Bullet) and Required_Velocity <= modulo:Get_Velocity(BulletMainPart) and not Debouncfe then
				TouchedBefore[Hit]=true
				Debouncfe = true
				local customhitbox = {
					CFrame=CFN(BulletMainPart.Position);
					Size=BulletMainPart.Size*VE3(3.5,3.5,3.5) ;
				}
				local erase
				for i,v in pairs (modulo:hitbox_detector(customhitbox,1,false)) do
					if v:FindFirstChild("WeakPointEntity") and not TouchedBefore[v.WeakPointEntity.Value] then
						TouchedBefore[v.WeakPointEntity.Value] = true
						if modulo:WeakValue______({WeakPointEntity=v.WeakPointEntity.Value,Damage=damage,EntityTableID=EntityTableID,Team=Team,MyCharacter=ignore_descendant}) then
							erase = true
						end
					end
