function modulo:Damage_Events(Bot_Character,Bot_Humanoid,Team)
	local Trigger_Damage = INST("BoolValue",Bot_Humanoid)
	Trigger_Damage.Name="Trigger_Damage"
	Trigger_Damage.Value=false
	Trigger_Damage:SetAttribute("Team",Team)
	
	local Trigger_GetBack = INST("BoolValue",Bot_Humanoid)
	Trigger_GetBack.Name="Trigger_GetBack"
	Trigger_GetBack.Value=false
	Trigger_GetBack:SetAttribute("Team",Team)
	
	for i,v in pairs (Bot_Character:GetDescendants()) do
		if v:IsA("Part") then
			if v:FindFirstChild("WeakPoint") then
				v:FindFirstChild("WeakPoint"):Destroy()
				local WeakPointEntity = INST("ObjectValue",v)
				WeakPointEntity.Name="WeakPointEntity"
				WeakPointEntity.Value=Trigger_Damage

				local GetBackPointEntity = INST("ObjectValue",v)
				GetBackPointEntity.Name="GetBackPointEntity"
				GetBackPointEntity.Value=Trigger_GetBack
				
				if v:FindFirstChild("cast_tag") == nil then
					local cast_tag = INST("IntValue",v)
					cast_tag.Name="cast_tag"
				end

				v.CanTouch = true
			else
				local Ignore_RayCast_Value = INST("IntValue",v)
				Ignore_RayCast_Value.Name="Ignore_RayCast_Value"
				v.CanTouch = false
			end

		end	
	end
	return Trigger_Damage,Trigger_GetBack
end
