function modulo:CastUntilHitWithHumanoid(Start, End, Params)
	local RayResult = _Services.Workspace:Raycast(Start, End - Start, Params)
	if RayResult then
		if RayResult.Instance.CanCollide or RayResult.Instance:FindFirstChild("cast_tag") then
			if RayResult.Instance:FindFirstChild("Ignore_RayCast_Value") == nil and RayResult.Instance.Parent:FindFirstChildOfClass("Humanoid") == nil then
				return RayResult
			end
		end
		local Filtered = Params.FilterDescendantsInstances
		Filtered[#Filtered + 1] = RayResult.Instance
		Params.FilterDescendantsInstances = Filtered

		return modulo:CastUntilHitWithHumanoid(Start, End, Params)
	else
		return {Position=End}
	end
end
function modulo:CastUntilHitSimple(Start, End, Params)
	local RayResult = _Services.Workspace:Raycast(Start, End - Start, Params)
	if RayResult then
		if ((RayResult.Instance.CanCollide) or RayResult.Instance:FindFirstChild("cast_tag")) and  RayResult.Instance:FindFirstChild("Ignore_RayCast_Value") == nil then
			return RayResult
		end
		local Filtered = Params.FilterDescendantsInstances
		Filtered[#Filtered + 1] = RayResult.Instance
		Params.FilterDescendantsInstances = Filtered

		return modulo:CastUntilHitSimple(Start, End, Params)
	else
		return {Position=End}
	end
end
function modulo:CastUntilHitWhiteList(Start, End, Params)
	local RayResult = _Services.Workspace:Raycast(Start, End - Start, Params)
	if RayResult then
		return RayResult
	else
		return {Position=End}
	end
end
