function modulo:getRandomItem(lootTable)
	-- returns a random number based on total weight of given lootTable
	local randomNumber = M_RAN(returnSumOfWeight(lootTable))

	for _, entry in ipairs(lootTable) do
		if  randomNumber <= entry.Chance then
			return entry
		else
			randomNumber = randomNumber - entry.Chance
		end
	end
end
