function modulo:Get_Velocity(Object,No_Y_Velocity)
	local Velocity = Object.Velocity
	if No_Y_Velocity then
		Velocity = VE3(Velocity.X,0,Velocity.Z)
	end
	return M_SQRT(Velocity.X^2+Velocity.Y^2+Velocity.Z^2)
end
