function modulo:CreatedParticle(ParticleName,Position,C)
	local C = C or {}
	--
	local base_location
	if C.BASE_PART then
		base_location = INST("Part")
		base_location.Anchored = true
		base_location.Transparency=1
		base_location.Size = C.BASE_SIZE or VE3()
		base_location.CanCollide = false
		base_location.Parent = _Services.Workspace.Terrain
		base_location.Velocity = C.VelocityReference or base_location.Velocity
		base_location.CFrame = C.BASE_CFRAME or CFrame.new(Position)
	else
		base_location = INST("Attachment")
		base_location.Parent = _Services.Workspace.Terrain
		base_location.WorldPosition = Position
	end
	local function _phase1(particles)
		particles.Enabled = true
		delay(C.ParticleTime or .2,function()
			particles.Enabled = false
		end)
	end
	
	local ParticlesCLone = _Services.RepliStorage.Objects.Particles:FindFirstChild(ParticleName):Clone()
	if C.CustomParent then
		ParticlesCLone.Parent = C.CustomParent
	else
		ParticlesCLone.Parent = base_location
	end
	
	if ParticlesCLone:IsA("Folder") then
		for _,particles in pairs (ParticlesCLone:GetDescendants()) do
			if particles:IsA("ParticleEmitter") then
				particles.Parent = ParticlesCLone.Parent
				_phase1(particles)
			end
		end
	elseif ParticlesCLone:IsA("ParticleEmitter") then
		_phase1(ParticlesCLone)
	end
	
	_Services.Debris:AddItem(base_location,C.DebrisTime or 2)
end
