function modulo:PlaySound(ParentSound,SoundName,C)
	local C = C or {}
	
	if typeof(SoundName) == "table" then SoundName = SoundName[math.random(1,#SoundName)] end
	local SearchSound = (C.Search_Sound and C.Search_Sound:FindFirstChild(SoundName)) or _Services.RepliStorage.Sounds:FindFirstChild(SoundName)
	if SearchSound then
		local Sound = SearchSound:Clone()
		Sound.Parent = ParentSound
		Sound.Name = "PLAYING_SOUND___" .. Sound.Name
		if C.PlaybackSpeed then
			Sound.PlaybackSpeed = C.PlaybackSpeed
		end
		if C.Volume then
			Sound.Volume*=C.Volume
		end
		if C.PlayOnRemove then
			Sound.PlayOnRemove = true
			Sound:Destroy()
		else
			if not C.NotPlaying then
				Sound:Play()
			end
			if not C.Save then
				_Services.Debris:AddItem(Sound,Sound.TimeLength/Sound.PlaybackSpeed)
			end
		end
		return Sound
	else
		warn(SoundName," Dosent Exist!! ")
	end
	return false
end
