		__self.Left_main = {pos_x=0;pos_y=0;size_x=0;size_y=0;pos_x_max=0;pos_x_min=0;pos_y_max=0;pos_y_min=0;tracker_mode=nil,offset_Y_tracker=0}
		__self.Right_main = {pos_x=0;pos_y=0;size_x=0;size_y=0;pos_x_max=0;pos_x_min=0;pos_y_max=0;pos_y_min=0;tracker_mode=nil,offset_Y_tracker=0}
	end set_ch_default()
	
