	__self.sp_={}
	__self.sp_b1={}
	__self.tween_player={}
	__self._restart_propierties={}
	
	-- global other instances
	for _,folder in pairs (__self.Main_Display.Parent:GetDescendants()) do
		if folder.Name == "other_folder" then
			for i,v in pairs (folder:GetChildren()) do
				table.insert(__self.other_table,v)
			end
		end
	end

