	function __self:get_all_functions_from()
		local function eyes_move(...) return self:eyes_move(...) end
		local function tween_Adder(...) return self:tween_Adder(...) end
		local function update_mouth(...) return self:update_mouth(...) end
		local function update_eyebrow(...) return self:update_eyebrow(...) end
		local function update_blurry(...) return self:update_blurry(...) end
		local function update_other(...) return self:update_other(...) end
		local function update_pup(...) return self:update_pup(...) end
		local function ch_eye(...) return self:ch_eye(...) end
		local sp_ = self.sp_;
		local CJA = self.eye_CJA;
		local blurry_folder = self.blurry_folder
		local other_table = self.other_table
		return eyes_move,tween_Adder,update_mouth,update_eyebrow,sp_,CJA,update_other,update_blurry,blurry_folder,other_table,update_pup,ch_eye,sp_b1
	end

