	function __self:tween_Adder(obj,tweeninfo,info) -- V1
		if not sp_[obj] then return end
		tween_player[obj] = tween_player[obj] or {}
		for i,v in pairs (tween_player[obj]) do v:Cancel() tween_player[obj][i]=nil end -- stop other animation
		for i,v in pairs (sp_[obj]) do if not info[i] then info[i] = v end end -- fill other propierties
		local TW = _Services.Tween:Create(obj,tweeninfo,info)
		table.insert(tween_player[obj],TW) 
		return TW 
	end
	
