	function __self:eyes_move(C) -- V1
		__self.random_seed = math.random()
		
		local __style,__state,__unique_ui,__nocjmove,__noyemove=C.Style,C.State,C.UniqueUI,C.NoCJMove,C.NoEYMove
		if typeof(__style) == "table" then __style = __style[math.random(1,#__style)] end
		if not __nocjmove then __FACE__CONF.__EYES_MOVEMENT_STYLE[__style].f1(__state) end 
		
		local function action_ui(eye)
			local UI = eye.ui
			local cega,wht,pup_frame = UI.cega,UI.wht,UI.wht.pup_frame
			local pup = pup_frame.pup
			eye.ui_pos = eye.ui_pos or eye.ui.Position
			__FACE__CONF.__EYES_MOVEMENT_STYLE[__style].f2(__state,eye)
		end
		if not __noyemove then
			for _,eye in pairs (OJITOS) do 
				if not __unique_ui or (__unique_ui and __unique_ui == eye.ui) then 
					action_ui(eye) 
				end
			end
		end
		eye_State=__state
	end
	
	function __self:update_eyebrow(side,__style,transition_choosed) -- V1
		local search = (side == "Left" and __self.eye_CJA.ll) or (side == "Right" and __self.eye_CJA.rr)
		for _,v in pairs (search:GetChildren()) do
			if transition_choosed and v.Name == __style then transition_choosed(side,v) end
			v.Visible = v.Name == __style
		end
	end
	
	local function changeeyesidexddgriffinpeter(custom_side,val_name,val) __self[custom_side][val_name]=val end
	function __self:ch_eye(val_name,val,custom_side,update_eyes) -- suppose to be call "M_E_G " AJAJajajajAJAJAJAJA
		if custom_side then
			changeeyesidexddgriffinpeter(custom_side,val_name,val)
		else
			changeeyesidexddgriffinpeter("Left_main",val_name,val)
			changeeyesidexddgriffinpeter("Right_main",val_name,val)
		end
		--
		if update_eyes then -- actualizar ojitos 
			__self:x_eye_pos_changer(l_pup,"Left_main")
			__self:x_eye_pos_changer(r_pup,"Right_main")
		end
		__self.update_eyes = true
	end
	
	function __self:update_pup(side,style,transition_choosed) -- V1
		side = (side == "Left" and l_pup) or (side == "Right" and r_pup)
		for _,v in pairs (side:GetChildren()) do
			if transition_choosed and v.Name == style then transition_choosed(v) end
			v.Visible = v.Name == style
		end
	end

