	local function UPDATE_EYE_TRACKER(ui,TARGET_PART,x_min,x_max,y_min,y_max,eye)
		local Rotation = get_look_vector()
		local Origin = BasePart.Position
		local TARGET_OFFSET = TARGET_PART:FindFirstChild("TARGET_OFFSET")  
		local offset = CFrame.new() if TARGET_OFFSET then offset = TARGET_OFFSET.Value end
		local Target = TARGET_PART.Value.CFrame * offset
		--MD_.FF:fake_part_detail(Color3.fromRGB(213, 0, 255),CFrame.new(Target.p),Vector3.new(1,1,1),.2)
		--
		local LookDiff = BasePart.CFrame:VectorToObjectSpace(Origin - Target.p)
		local mag = (Origin - Target.p).magnitude -- Get Difference/LookAt
		--
		local ____XZ_part1 = (LookDiff.X^2)+(LookDiff.Z^2)
		local ____XZ_part2 = (-____XZ_part1^0.5)/(mag*2)
		--
		local _3D_POINT_X = ((LookDiff.Z/mag))
		local _3D_POINT_Y = LookDiff.Y*____XZ_part2
		local Y = (((LookDiff.Y/2))+_3D_POINT_Y) --  
		local X = (_3D_POINT_X)
		--
		sp_[ui].Position = UDim2.new(math.clamp(sp_b1[ui].Position.X.Scale-X,x_min,x_max),0,math.clamp(sp_b1[ui].Position.Y.Scale+Y+__self[eye].offset_Y_tracker,y_min,y_max),0)
	end
	
	--█▀▄▀█ █▀▀█ █░░█ ▀▀█▀▀ █░░█ 　 █▀▄▀█ █▀▀█ ▀█░█▀ █▀▀ █▀▄▀█ █▀▀ █▀▀▄ ▀▀█▀▀ 
	--█░▀░█ █░░█ █░░█ ░░█░░ █▀▀█ 　 █░▀░█ █░░█ ░█▄█░ █▀▀ █░▀░█ █▀▀ █░░█ ░░█░░ 
	--▀░░░▀ ▀▀▀▀ ░▀▀▀ ░░▀░░ ▀░░▀ 　 ▀░░░▀ ▀▀▀▀ ░░▀░░ ▀▀▀ ▀░░░▀ ▀▀▀ ▀░░▀ ░░▀░░
	
	function __self:update_mouth(style,UI) -- V1
		__self.CURRENT_MOUTH_UI = UI
		if typeof(UI) == "table" then UI = UI[math.random(1,#UI)] end
		for _,v in pairs (__self.__MOUTH) do
			if v == UI then
				__FACE__CONF.__MOUTH_MOVEMENT_STYLE[style].open(v,UI)
				__self.__ACTUAL__MOUTH = UI
			else
				__FACE__CONF.__MOUTH_MOVEMENT_STYLE[style].close(v,UI)
			end
		end
	end
	
