	function __self:x_eye_pos_changer(ui,eye) -- V1	
		local x_scaler,y_scaler = sp_[ui].Size.X.Scale/2,sp_[ui].Size.Y.Scale/1.5
		local x_min,x_max = 0+x_scaler+__self[eye].pos_x_min,1-x_scaler+__self[eye].pos_x_max
		local y_min,y_max = 0+y_scaler+__self[eye].pos_y_min,1-y_scaler+__self[eye].pos_y_max
		local TARGET_PART = Face_Event_String:FindFirstChild("TARGET_OBJECT")
		if y_min > y_max then local y_o = y_min y_min = y_max y_max = y_o end 
		if x_min > x_max then local x_o = x_min x_min = x_max x_max = x_o end 
		if __self[eye].tracker_mode and TARGET_PART and TARGET_PART.Value then
			UPDATE_EYE_TRACKER(ui,TARGET_PART,x_min,x_max,y_min,y_max,eye)
		else
			sp_[ui].Position = UDim2.new(math.clamp(sp_b1[ui].Position.X.Scale + __self[eye].pos_x,x_min,x_max),0,math.clamp(sp_b1[ui].Position.Y.Scale + __self[eye].pos_y,y_min,y_max),0)
		end
