		__self.actual_face_string=nil
	end
	
	function __self:Loop() -- V1
		if MD_.FACE_ANIMATED or __self.update_eyes then
			__self.update_eyes = false
			__self:x_eye_pos_changer(l_pup,"Left_main")
			__self:x_eye_pos_changer(r_pup,"Right_main")
			__FACE__CONF:__Loop()
			
			-- restart some instances propierties
			if __self.actual_face_string ~= Face_Event_String.Value then
				for instance,propierties in pairs (__self._restart_propierties) do
					local propierties = sp_[instance]
					if tween_player[instance] then
						for i,v in pairs (tween_player[instance]) do v:Cancel() tween_player[instance][i]=nil end -- stop other animation
					end
					--for properties,value in pairs (v) do
					--	instance[properties] = value
					--end
					local TW = _Services.Tween:Create(instance,tweeninfo_default,propierties)
					TW:Play()
				end
				
				
				if __self.Recall_end_event then __self.Recall_end_event() __self.Recall_end_event=nil end	
				set_ch_default()
				--set default values--
				__self:update_pup("Right","_1")
				__self:update_pup("Left","_1")
				--
			end
			
		
			local FOLLOW_ACTION_EVENT = gameplay_expressions[Face_Event_String.Value] or __FACE__CONF.__ACTIONS_FACE_STRING[Face_Event_String.Value]
			if FOLLOW_ACTION_EVENT then FOLLOW_ACTION_EVENT(Face_Event_String.Value) else __FACE__CONF.__ACTIONS_FACE_STRING.Default() end
			
			__self.actual_face_string = Face_Event_String.Value
		end
	end
	
	return __self
end

