					local tween = tween_Adder(CJA.ll,tweeninfo1,{Rotation=-0})tween:Play()
				else
					local tween = tween_Adder(CJA,tweeninfo1,sp_[CJA]) tween:Play()
					local tween = tween_Adder(CJA.rr,tweeninfo1,{Rotation=-15;Position=sp_[CJA.rr].Position+UDim2.fromScale(-.025,0)})tween:Play()
					local tween = tween_Adder(CJA.ll,tweeninfo1,{Rotation=15;Position=sp_[CJA.ll].Position+UDim2.fromScale(.025,0)})tween:Play()
				end
			end;
			--█▀▀   ▀█
			--█▀░   █▄
			f2=function(style,eye_info)
				local UI = eye_info.ui
				local dir = eye_info.dir
				local cega,wht,pup_frame = UI.cega,UI.wht,UI.wht.pup_frame
				local pup = pup_frame.pup
				if style=="Close" then
					local tween = tween_Adder(UI,tweeninfo1,			{Position=eye_info.ui_pos+UDim2.fromScale(0,.015)}) tween:Play()
					local tween = tween_Adder(cega,tweeninfo1,			{Position=sp_[cega].Position+UDim2.fromScale(0,.3);Size=UDim2.fromScale(1,0.25)}) tween:Play()
					local tween = tween_Adder(wht,tweeninfo1,			{Position=sp_[wht].Position+UDim2.fromScale(dir=="Left" and .1 or -.1,-.1),Size=UDim2.fromScale(0.6,0)}) tween:Play()
					local tween = tween_Adder(pup,tweeninfo1,			{Position=sp_[pup].Position+UDim2.fromScale(0,-0.1),Size=sp_[pup].Size+UDim2.fromScale(0,-.5)}) tween:Play()
				else
					local tween = tween_Adder(UI,tweeninfo1,sp_[UI]) tween:Play()
					local tween = tween_Adder(cega,tweeninfo1,sp_[cega]) tween:Play()
					local tween = tween_Adder(wht,tweeninfo1,sp_[wht]) tween:Play()
					local tween = tween_Adder(pup,tweeninfo1,sp_[pup]) tween:Play()
				end
			end
		};
