SRC[3336]=[==[
-- EXAMPLES OF USING THE SCRIPT
--[[

local Poof_Manage = require(game.ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Poof_Manager"))
while wait() do
	Poof_Manage({CF=script.Parent.CFrame,SIZE=script.Parent.Size,AMOUNT=35;RANGE=1;STYLE="Normal";TIME=2;NEXT_CF_RANGE=5;SIZE_MULTIER=1.5;TRANSPARENCY_FUNC=function() return 0 end;EASINGSTYLE=Enum.EasingStyle.Circular,EASINGDIRECTION=Enum.EasingDirection.Out;SIZE_REVERSE=true})
	wait(1)
	Poof_Manage({CF=script.Parent.CFrame,SIZE=script.Parent.Size,AMOUNT=35;RANGE=1;STYLE="Normal";TIME=1;NEXT_CF_RANGE=5;SIZE_MULTIER=1.5;TRANSPARENCY_FUNC=function() return 0 end;EASINGSTYLE=Enum.EasingStyle.Exponential,EASINGDIRECTION=Enum.EasingDirection.Out})
	wait(1)
	Poof_Manage({CF=script.Parent.CFrame,SIZE=script.Parent.Size,AMOUNT=15;RANGE=1;STYLE="Circle";TIME=.85;NEXT_CF_RANGE=5;SIZE_MULTIER=1.5;TRANSPARENCY_FUNC=function() return 0 end;SIZE_REVERSE=true})
	wait(.5)
	Poof_Manage({CF=script.Parent.CFrame*CFrame.Angles(math.rad(90),0,0),SIZE=script.Parent.Size,AMOUNT=15;RANGE=1;STYLE="Circle";TIME=.85;NEXT_CF_RANGE=5;SIZE_MULTIER=1.5;TRANSPARENCY_FUNC=function() return 0 end;SIZE_REVERSE=false})
	wait(.5)
	Poof_Manage({CF=script.Parent.CFrame*CFrame.Angles(math.rad(90),0,math.rad(90)),SIZE=script.Parent.Size,AMOUNT=15;RANGE=1;STYLE="Circle";TIME=.85;NEXT_CF_RANGE=5;SIZE_MULTIER=1.5;TRANSPARENCY_FUNC=function() return 0 end;SIZE_REVERSE=true})
	wait(.5)
end

]]

local _Services = {
	["Workspace"] = game:GetService("Workspace");
	["Lighting"] = game:GetService("Lighting");
	["Player"] = game:GetService("Players");
	["Run"] = game:GetService("RunService");
	["Debris"] = game:GetService("Debris");
	["UserInput"] = __VUIS();
	["Tween"] = game:GetService("TweenService");
	["Physics"] = game:GetService("PhysicsService");
	["StarterGui"] = game:GetService("StarterGui");
	["StarterPlayer"] = game:GetService("StarterPlayer");
	["RepliStorage"] = game:GetService("ReplicatedStorage");
	["ServerStorage"] = game:GetService("ServerStorage");
	["Chat"] = game:GetService("Chat");
	["Teleport"] = game:GetService("TeleportService");
	["HttpService"] = game:GetService("HttpService");
	["ContentProvider"] = game:GetService("ContentProvider");
}

local PoofEffectsParts = {}
for i,v in pairs (script:WaitForChild("Poof_Instances"):GetChildren()) do 
	v.Color = Color3.fromRGB(255,255,255)
	v.Material = Enum.Material.SmoothPlastic
	v.Reflectance = -1
	v.CanCollide = false
	v.CastShadow = false
	v.CanTouch = false
	v.Anchored = true
	v.CanQuery = false
	table.insert(PoofEffectsParts,v) 
end

local function get_ran_() return math.random()-.5 end
local function get_ran_angle() return math.random()*math.rad(360) end
local function get_by_b(current_size,reverse) return (reverse and current_size) or Vector3.new()  end
local function get_by_t(current_tran,reverse) return (reverse and 1) or current_tran end

local Anim_Style = {
	["Normal"]=function(C,Poof,i,NextSize,NextTransparency)
		local CF,SIZE,AMOUNT,RANGE,STYLE,TIME,NEXT_CF_RANGE,SIZE_MULTIER,SIZE_REVERSE,TRANSPARENCY_FUNC,EASINGSTYLE,EASINGDIRECTION = C.CF,C.SIZE,C.AMOUNT,C.RANGE,C.STYLE,C.TIME,C.NEXT_CF_RANGE,C.SIZE_MULTIER,C.SIZE_REVERSE,C.TRANSPARENCY_FUNC,C.EASINGSTYLE,C.EASINGDIRECTION
		Poof.CFrame = CF * CFrame.new(get_ran_()*SIZE.X*RANGE,get_ran_()*SIZE.Y*RANGE,get_ran_()*SIZE.Z*RANGE)	* CFrame.Angles(get_ran_angle(),get_ran_angle(),get_ran_angle())
		local Unit = (Poof.CFrame.p-CF.p).Unit
		_Services.Tween:Create(Poof,TweenInfo.new(TIME,EASINGSTYLE,EASINGDIRECTION,0,false,0),{Size=get_by_b(NextSize,SIZE_REVERSE);CFrame=Poof.CFrame+(Unit*NEXT_CF_RANGE);Transparency=NextTransparency}) :Play()
	end,
	["Style2"]=function(C,Poof,i,NextSize,NextTransparency)
		local CF,SIZE,AMOUNT,RANGE,STYLE,TIME,NEXT_CF_RANGE,SIZE_MULTIER,SIZE_REVERSE,TRANSPARENCY_FUNC,EASINGSTYLE,EASINGDIRECTION = C.CF,C.SIZE,C.AMOUNT,C.RANGE,C.STYLE,C.TIME,C.NEXT_CF_RANGE,C.SIZE_MULTIER,C.SIZE_REVERSE,C.TRANSPARENCY_FUNC,C.EASINGSTYLE,C.EASINGDIRECTION
		Poof.CFrame = CF * CFrame.new(get_ran_()*SIZE.X*RANGE,get_ran_()*SIZE.Y*RANGE,get_ran_()*SIZE.Z*RANGE)	* CFrame.Angles(get_ran_angle(),get_ran_angle(),get_ran_angle())
		local Unit = (Poof.CFrame.p-CF.p).Unit
		_Services.Tween:Create(Poof,TweenInfo.new(TIME,EASINGSTYLE,EASINGDIRECTION,0,false,0),{Size=Poof.Size*-.25;CFrame=Poof.CFrame+(Unit*NEXT_CF_RANGE);Transparency=NextTransparency}) :Play()
	end,
	["Circle"]=function(C,Poof,i,NextSize,NextTransparency)
		local CF,SIZE,AMOUNT,RANGE,STYLE,TIME,NEXT_CF_RANGE,SIZE_MULTIER,SIZE_REVERSE,TRANSPARENCY_FUNC,EASINGSTYLE,EASINGDIRECTION = C.CF,C.SIZE,C.AMOUNT,C.RANGE,C.STYLE,C.TIME,C.NEXT_CF_RANGE,C.SIZE_MULTIER,C.SIZE_REVERSE,C.TRANSPARENCY_FUNC,C.EASINGSTYLE,C.EASINGDIRECTION
		local radial_order = math.rad((i*360)/AMOUNT)
		local CFAN = CF * CFrame.Angles(0,radial_order,0)
		Poof.CFrame = CF * CFrame.Angles(get_ran_angle(),get_ran_angle(),get_ran_angle())
		_Services.Tween:Create(Poof,TweenInfo.new(TIME/2,EASINGSTYLE,EASINGDIRECTION,0,false,0),{Size=get_by_b(NextSize,SIZE_REVERSE);CFrame=CF+((CFAN.lookVector*NEXT_CF_RANGE));Transparency=NextTransparency}) :Play()
	end,
}
return function (C)
	local CF,SIZE,AMOUNT,RANGE,STYLE,TIME,NEXT_CF_RANGE,SIZE_MULTIER,SIZE_REVERSE,TRANSPARENCY_FUNC,EASINGSTYLE,EASINGDIRECTION = C.CF,C.SIZE,C.AMOUNT,C.RANGE,C.STYLE,C.TIME,C.NEXT_CF_RANGE,C.SIZE_MULTIER,C.SIZE_REVERSE,C.TRANSPARENCY_FUNC,C.EASINGSTYLE,C.EASINGDIRECTION
	C.EASINGSTYLE,C.EASINGDIRECTION = EASINGSTYLE or Enum.EasingStyle.Sine,EASINGDIRECTION or Enum.EasingDirection.Out
	for i=1,AMOUNT do
		local Poof = PoofEffectsParts[math.random(1,#PoofEffectsParts)]:Clone() Poof.Parent = _Services.Workspace.Terrain
		local NextTransparency = TRANSPARENCY_FUNC() Poof.Transparency = NextTransparency if SIZE_REVERSE then NextTransparency = 1 end
		local NextSize = Poof.Size*SIZE_MULTIER Poof.Size = (SIZE_REVERSE and Vector3.new()) or NextSize
		_Services.Debris:AddItem(Poof,TIME)
		Anim_Style[STYLE](C,Poof,i,NextSize,NextTransparency)
	end
end
]==]
