	["StarterPlayer"] = game:GetService("StarterPlayer");
	["RepliStorage"] = game:GetService("ReplicatedStorage");
	["ServerStorage"] = game:GetService("ServerStorage");
	["Chat"] = game:GetService("Chat");
	["Teleport"] = game:GetService("TeleportService");
	["HttpService"] = game:GetService("HttpService");
	["ContentProvider"] = game:GetService("ContentProvider");
}

local effect_model = script.Parent
local MAIN  = effect_model.Main
local GL_Weld = MAIN.GL_Weld
local GR_Weld = MAIN.GR_Weld
local GL_FOLDER = effect_model.GL_FOLDER
local GR_FOLDER = effect_model.GR_FOLDER
local folder_meshes = {}
local time_multiplier = .5

local function add (mesh) if mesh:IsA("BasePart") then table.insert(folder_meshes,{Mesh=mesh,Size=mesh.Size})  end end
for _,mesh in pairs (GR_FOLDER:GetDescendants()) do add(mesh) end
for _,mesh in pairs (GL_FOLDER:GetDescendants()) do add(mesh) end


local function state_trails (state)
	for _,v in pairs (effect_model:GetDescendants()) do
		if not v:IsA("Trail") then continue end
		v.Enabled = state
	end
end state_trails(false)

local function change(TweenInfos,size_mult)
	for _,v in pairs (folder_meshes) do
		_Services.Tween:Create(v.Mesh,TweenInfos,{Size=v.Size*size_mult}) :Play()
	end
end

spawn(function()
	_Services.Debris:AddItem(effect_model,3*time_multiplier)
	state_trails(true)
	change(TweenInfo.new(.0,Enum.EasingStyle.Linear,Enum.EasingDirection.Out,0,false,0),0)
	GL_Weld.C0=GL_Weld.C0*CFrame.Angles(math.rad(-40),math.rad(-50),0)
	GR_Weld.C0=GR_Weld.C0*CFrame.Angles(math.rad(40),math.rad(50),0)
	wait(.1*time_multiplier)
	change(TweenInfo.new(.95*time_multiplier,Enum.EasingStyle.Elastic,Enum.EasingDirection.Out,0,false,0),1)
	_Services.Tween:Create(GL_Weld,TweenInfo.new(.95*time_multiplier,Enum.EasingStyle.Back,Enum.EasingDirection.Out,0,false,0),{C0=(GL_Weld.C0*CFrame.new(2,0,1))*CFrame.Angles(math.rad(10),math.rad(120),0)}) :Play()
	_Services.Tween:Create(GR_Weld,TweenInfo.new(.95*time_multiplier,Enum.EasingStyle.Back,Enum.EasingDirection.Out,0,false,0),{C0=(GR_Weld.C0*CFrame.new(2,0,-1))*CFrame.Angles(math.rad(-10),math.rad(-120),0)}) :Play()
	wait(.5*time_multiplier)
	change(TweenInfo.new(.75*time_multiplier,Enum.EasingStyle.Sine,Enum.EasingDirection.In,0,false,0),0)
	state_trails(false)
	_Services.Tween:Create(GL_Weld,TweenInfo.new(.75*time_multiplier,Enum.EasingStyle.Sine,Enum.EasingDirection.In,0,false,0),{C0=(GL_Weld.C0*CFrame.new(0,0,-2))*CFrame.Angles(math.rad(10),math.rad(-70),0)}) :Play()
	_Services.Tween:Create(GR_Weld,TweenInfo.new(.75*time_multiplier,Enum.EasingStyle.Sine,Enum.EasingDirection.In,0,false,0),{C0=(GR_Weld.C0*CFrame.new(0,0,2))*CFrame.Angles(math.rad(-10),math.rad(70),0)}) :Play()
end)
return true
]=]
