local splash_main2_weld = splash_main2.weld
local splash_main1_weldC0 = splash_main1_weld.C0
local splash_main2_weldC0 = splash_main2_weld.C0

local time_multiplier = .5

local function particulon ()  
	local max = math.random(7,12)
	for i=1,max do
		local cf = CFrame.new() * CFrame.Angles(0,math.rad(math.random(-180,180)),0)
		local elperas = math.random(150,250)/10
		local par = particulitas:Clone()
		par.Parent = effect_model
		par.CFrame = MainPart.CFrame + (cf.LookVector*.1)
		par.Anchored = false
		
		par.Velocity = Vector3.new(0,math.random(250,350)/10,0) + (cf.LookVector*elperas)
		_Services.Debris:AddItem(par,2*time_multiplier)
	end
end

local function add (mesh) if mesh:IsA("BasePart") then folder_meshes[mesh]={CFrame=mesh.CFrame,Size=mesh.Size;Transparency=mesh.Transparency}  end end

add(splash_main)
add(splash_main2)

spawn(function()
	_Services.Tween:Create(splash_main2,TweenInfo.new(.0,Enum.EasingStyle.Linear,Enum.EasingDirection.Out,0,false,0),folder_meshes[splash_main2]) :Play()
	_Services.Tween:Create(splash_main,	TweenInfo.new(.0,Enum.EasingStyle.Linear,Enum.EasingDirection.Out,0,false,0),folder_meshes[splash_main]) :Play()
	_Services.Tween:Create(splash_main1_weld,TweenInfo.new(.0,Enum.EasingStyle.Linear,Enum.EasingDirection.Out,0,false,0),{C0=splash_main1_weldC0}) :Play()
	_Services.Tween:Create(splash_main2_weld,TweenInfo.new(.0,Enum.EasingStyle.Linear,Enum.EasingDirection.Out,0,false,0),{C0=splash_main2_weldC0}) :Play()
	wait()
	_Services.Tween:Create(splash_main,TweenInfo.new(1*time_multiplier,Enum.EasingStyle.Elastic,Enum.EasingDirection.Out,0,false,0),{Size=Vector3.new(1,4,1)}) :Play()
	_Services.Tween:Create(splash_main2,TweenInfo.new(1*time_multiplier,Enum.EasingStyle.Elastic,Enum.EasingDirection.Out,0,false,0),{Size=Vector3.new(3,2,3)}) :Play()
	_Services.Tween:Create(splash_main1_weld,TweenInfo.new(1*time_multiplier,Enum.EasingStyle.Elastic,Enum.EasingDirection.Out,0,false,0),{C0=splash_main1_weldC0*CFrame.new(0,.45,0)*CFrame.Angles(0,math.rad(80),0)}) :Play()
	_Services.Tween:Create(splash_main2_weld,TweenInfo.new(1*time_multiplier,Enum.EasingStyle.Elastic,Enum.EasingDirection.Out,0,false,0),{C0=splash_main2_weldC0*CFrame.new(0,-.3,0)*CFrame.Angles(0,math.rad(80),0)}) :Play()
	
	spawn(function()
		particulon () 
	end)
	wait(.25*time_multiplier)
	local santiagocum2 = TweenInfo.new(.5*time_multiplier,Enum.EasingStyle.Sine,Enum.EasingDirection.Out,0,false,0)
	local santiagocum1 = TweenInfo.new(.85*time_multiplier,Enum.EasingStyle.Sine,Enum.EasingDirection.Out,0,false,0)
	_Services.Tween:Create(splash_main2,santiagocum2,{CFrame=splash_main2.CFrame*CFrame.Angles(0,math.rad(-160),0)*CFrame.new(0,-.5,0); Size=Vector3.new(6,0,6);Transparency=1}) :Play()
	_Services.Tween:Create(splash_main,santiagocum1,{CFrame=splash_main.CFrame*CFrame.Angles(0,math.rad(-160),0)*CFrame.new(0,-.5,0); Size=Vector3.new(5,0,5);Transparency=1}) :Play()
	_Services.Tween:Create(splash_main1_weld,santiagocum2,{C0=splash_main1_weldC0*CFrame.new(0,-.45,0)*CFrame.Angles(0,math.rad(150),0)}) :Play()
	_Services.Tween:Create(splash_main2_weld,santiagocum1,{C0=splash_main2_weldC0*CFrame.new(0,-.5,0)*CFrame.Angles(0,math.rad(150),0)}) :Play()
	
	_Services.Debris:AddItem(effect_model,2*time_multiplier)
end)

return true
]=]
