--=== anim_engine.lua ===
--[[====================================================================
  ANIMATION ENGINE  —  thay the KeyframeSequenceProvider (server-only)
  ------------------------------------------------------------------
  Du lieu keyframe nhung san trong ANIMD (base64, tools/export_anim.py).
  Moi Animation instance duoc gan attribute "_anim" = ten sequence;
  engine sample va ghi Motor6D.Transform moi frame  ->  animation phat
  duoc tren CLIENT, khong can server.

  Ho tro: Play/Stop/AdjustSpeed/AdjustWeight/TimePosition/Length,
  GetMarkerReachedSignal, KeyframeReached, Stopped, DidLoop, blend
  theo Priority + weight (nlerp quaternion).
====================================================================]]--

local ANIM = {}
_G.__ANIM = ANIM

local FLIP_ROT = false         -- = true neu animation bi lat nguoc

local RunService = game:GetService("RunService")

--==================== base64 ====================
local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64I = {}
for i = 1, 64 do B64I[string.byte(B64, i)] = i - 1 end

local function b64decode(s)
	local out, o = {}, 0
	local n = #s
	local i = 1
	while i <= n do
		local a = B64I[string.byte(s, i)] or 0
		local b = B64I[string.byte(s, i + 1)] or 0
		local c = B64I[string.byte(s, i + 2)] or 0
		local d = B64I[string.byte(s, i + 3)] or 0
		i = i + 4
		local v = a * 262144 + b * 4096 + c * 64 + d
		o = o + 1; out[o] = string.char(math.floor(v / 65536) % 256)
		o = o + 1; out[o] = string.char(math.floor(v / 256) % 256)
		o = o + 1; out[o] = string.char(v % 256)
	end
	return table.concat(out)
end

--==================== decode 1 sequence (lazy) ====================
local SEQ = {}

local function getSeq(name)
	local s = SEQ[name]
	if s then return s end
	local raw = ANIMD[name]
	if not raw then return nil end
	local ok, res = pcall(function()
		local b = b64decode(raw)
		if string.sub(b, 1, 3) ~= "AV1" then error("bad blob") end
		local p = 4
		local loop, prio, nbones = string.unpack("<BHB", b, p); p = p + 4
		local bones = table.create(nbones)
		for i = 1, nbones do
			local l; l, p = string.unpack("<B", b, p)
			bones[i] = string.sub(b, p, p + l - 1); p = p + l
		end
		local nk; nk, p = string.unpack("<H", b, p)
		local keys = table.create(nk)
		local maxT = 0
		for k = 1, nk do
			local t; t, p = string.unpack("<f", b, p)
			local np; np, p = string.unpack("<H", b, p)
			local poses = table.create(np)
			for i = 1, np do
				local bi, px, py, pz, qx, qy, qz, qw
				bi, px, py, pz, qx, qy, qz, qw = string.unpack("<Bhhhhhhh", b, p)
				p = p + 15
				local qn = math.sqrt(qx * qx + qy * qy + qz * qz + qw * qw)
				if qn < 1 then qn = 1 end
				poses[i] = { bones[bi + 1], px / 32, py / 32, pz / 32,
					qx / 32767, qy / 32767, qz / 32767, qw / 32767 }
			end
			local nm; nm, p = string.unpack("<B", b, p)
			local marks
			if nm > 0 then
				marks = table.create(nm)
				for i = 1, nm do
					local l; l, p = string.unpack("<B", b, p)
					local mn = string.sub(b, p, p + l - 1); p = p + l
					l, p = string.unpack("<B", b, p)
					local mv = string.sub(b, p, p + l - 1); p = p + l
					marks[i] = { mn, mv }
				end
			end
			keys[k] = { t = t, p = poses, m = marks }
			if t > maxT then maxT = t end
		end
		return { loop = loop == 1, prio = prio, bones = bones, keys = keys, length = maxT }
	end)
	if not ok then
		warn("[ANIM] decode loi " .. tostring(name) .. ": " .. tostring(res))
		return nil
	end
	SEQ[name] = res
	return res
end
ANIM.getSeq = getSeq

--==================== Signal ====================
local Signal = {}
Signal.__index = Signal
function Signal.new()
	return setmetatable({ _h = {} }, Signal)
end
function Signal:Connect(fn)
	local c = { Connected = true, _fn = fn }
	self._h[c] = true
	return c
end
Signal.connect = Signal.Connect
Signal.ConnectParallel = Signal.Connect
function Signal:Fire(...)
	for c in pairs(self._h) do
		if c.Connected then
			local ok, err = pcall(c._fn, ...)
			if not ok then warn("[ANIM] handler loi: " .. tostring(err)) end
		end
	end
end
Signal.Fire = Signal.Fire
function Signal:DisconnectAll()
	for c in pairs(self._h) do c.Connected = false end
	self._h = {}
end

--==================== rig helpers ====================
local RIGMOTOR = setmetatable({}, { __mode = "k" })

local function motorsOf(rig)
	local m = RIGMOTOR[rig]
	if m and next(m) ~= nil then return m end
	m = {}
	for _, d in ipairs(rig:GetDescendants()) do
		if d:IsA("Motor6D") then
			local p1 = d.Part1
			if p1 then m[p1.Name] = d end
		end
	end
	RIGMOTOR[rig] = m
	return m
end
ANIM.motorsOf = motorsOf

local function rigOf(animator)
	if not animator then return nil end
	local ok, isA = pcall(function() return animator:IsA("Animator") end)
	if ok and isA then
		local h = animator.Parent
		if h then return h.Parent end
		return nil
	end
	local ok2, isH = pcall(function()
		return animator:IsA("Humanoid") or animator:IsA("AnimationController")
	end)
	if ok2 and isH then return animator.Parent end
	return nil
end

--==================== quaternion -> CFrame ====================
local function qCF(px, py, pz, qx, qy, qz, qw)
	local x2, y2, z2 = qx + qx, qy + qy, qz + qz
	local xx, yy, zz = qx * x2, qy * y2, qz * z2
	local xy, xz, yz = qx * y2, qx * z2, qy * z2
	local wx, wy, wz = qw * x2, qw * y2, qw * z2
	local m1, m2, m3 = 1 - (yy + zz), xy - wz, xz + wy
	local m4, m5, m6 = xy + wz, 1 - (xx + zz), yz - wx
	local m7, m8, m9 = xz - wy, yz + wx, 1 - (xx + yy)
	if FLIP_ROT then
		m2, m4 = m4, m2; m3, m7 = m7, m3; m6, m8 = m8, m6
	end
	local rot = CFrame.fromMatrix(Vector3.new(0, 0, 0),
		Vector3.new(m1, m4, m7),
		Vector3.new(m2, m5, m8),
		Vector3.new(m3, m6, m9))
	return CFrame.new(px, py, pz) * rot
end
ANIM.qCF = qCF

--==================== Track ====================
local Track = {}

local ACTIVE = {}
local RENDER_CONN
local ALLTRACKS = setmetatable({}, { __mode = "k" })   -- animator -> {track...}

local TMP = {}
local TMPK = {}
local ACC = {}
local ACCK = {}
local ACCN = 0

local function sortKeys(seq)
	if seq._sorted then return end
	table.sort(seq.keys, function(a, b) return a.t < b.t end)
	seq._sorted = true
end

local function bracket(seq, t)
	local keys = seq.keys
	local n = #keys
	if n == 0 then return nil, nil, 0 end
	if t <= keys[1].t then return keys[1], keys[1], 0 end
	if t >= keys[n].t then return keys[n], keys[n], 0 end
	local lo, hi = 1, n
	while hi - lo > 1 do
		local mid = math.floor((lo + hi) / 2)
		if keys[mid].t <= t then lo = mid else hi = mid end
	end
	local a, b = keys[lo], keys[hi]
	local span = b.t - a.t
	local al = span > 0 and ((t - a.t) / span) or 0
	return a, b, al
end

function Track:_tick(dt)
	local st = self._s
	-- fade
	if st.weight ~= st.target then
		local rate = st.fade > 0 and (dt / st.fade) or 1
		if st.weight < st.target then
			st.weight = math.min(st.target, st.weight + rate)
		else
			st.weight = math.max(st.target, st.weight - rate)
		end
		if st.weight <= 0.0001 and st.target == 0 then
			st.weight = 0
			st.playing = false
			return 0
		end
	end
	if not st.playing then return st.weight end
	local seq = st.seq
	if not seq then return 0 end
	local dur = seq.length
	if dur <= 0 then dur = 0.0001 end
	local newT = st.time + dt * st.speed
	local last = st.lastT
	if newT > last then self:_fireEvents(last, newT) end
	if seq.loop then
		if newT > dur then
			local loops = math.floor(newT / dur)
			newT = newT - loops * dur
			st.lastT = 0
			st.didLoop:Fire()
		else
			st.lastT = newT
		end
	else
		if newT >= dur then
			newT = dur
			st.lastT = dur
			st.playing = false
			st.target = 0
			st.fade = 0.1
			st.stopped:Fire("Finished")
		else
			st.lastT = newT
		end
	end
	st.time = newT
	return st.weight
end

function Track:_fireEvents(t0, t1)
	local st = self._s
	local keys = st.seq.keys
	for i = 1, #keys do
		local k = keys[i]
		if k.t > t0 and k.t <= t1 then
			if k.m then
				for _, mk in ipairs(k.m) do
					local sig = st.msig[mk[1]]
					if sig then sig:Fire(mk[2]) end
				end
			end
			st.keyreached:Fire("Keyframe")
		end
	end
end

function Track:_sample()
	local st = self._s
	local seq = st.seq
	local a, b, al = bracket(seq, st.time)
	if not a then return end
	local pa, pb = a.p, b.p
	local tn = 0
	for i = 1, #pa do
		local p = pa[i]
		TMP[p[1]] = { p[2], p[3], p[4], p[5], p[6], p[7], p[8] }
		tn = tn + 1; TMPK[tn] = p[1]
	end
	if b ~= a and al > 0 then
		local i0 = 1 - al
		for i = 1, #pb do
			local p = pb[i]
			local t = TMP[p[1]]
			if t then
				t[1] = t[1] * i0 + p[2] * al
				t[2] = t[2] * i0 + p[3] * al
				t[3] = t[3] * i0 + p[4] * al
				local ax, ay, az, aw = t[4], t[5], t[6], t[7]
				local bx, by, bz, bw = p[5], p[6], p[7], p[8]
				if ax * bx + ay * by + az * bz + aw * bw < 0 then
					bx, by, bz, bw = -bx, -by, -bz, -bw
				end
				t[4] = ax * i0 + bx * al
				t[5] = ay * i0 + by * al
				t[6] = az * i0 + bz * al
				t[7] = aw * i0 + bw * al
			else
				TMP[p[1]] = { p[2] * al, p[3] * al, p[4] * al,
					p[5] * al, p[6] * al, p[7] * al, (1 - al) + p[8] * al }
				tn = tn + 1; TMPK[tn] = p[1]
			end
		end
	end
	self._tn = tn
end

function Track:_accumulate(acc)
	self:_sample()
	local st = self._s
	local w = st.weight
	local tn = self._tn
	for i = 1, tn do
		local name = TMPK[i]
		local v = TMP[name]
		local e = acc[name]
		if e then
			e[1] = e[1] + v[1] * w; e[2] = e[2] + v[2] * w; e[3] = e[3] + v[3] * w
			e[4] = e[4] + v[4] * w; e[5] = e[5] + v[5] * w; e[6] = e[6] + v[6] * w
			e[7] = e[7] + v[7] * w; e[8] = e[8] + w
		else
			local e2 = { v[1] * w, v[2] * w, v[3] * w, v[4] * w,
				v[5] * w, v[6] * w, v[7] * w, w }
			acc[name] = e2
			ACCN = ACCN + 1; ACCK[ACCN] = name
		end
		TMP[name] = nil
	end
end

--==================== step ====================
function ANIM.step(dt)
	local n = #ACTIVE
	if n == 0 then
		return
	end
	local rigs, order = {}, {}
	for i = n, 1, -1 do
		local tr = ACTIVE[i]
		local st = tr._s
		local rig = st.rig
		if not st.playing and st.weight <= 0.0001 then
			table.remove(ACTIVE, i)
		elseif rig == nil or rig.Parent == nil then
			st.playing = false; st.weight = 0
			table.remove(ACTIVE, i)
		else
			local list = rigs[rig]
			if not list then list = {}; rigs[rig] = list; order[#order + 1] = rig end
			list[#list + 1] = tr
		end
	end
	for _, rig in ipairs(order) do
		local list = rigs[rig]
		local topPri = -1
		for _, tr in ipairs(list) do
			local w = tr:_tick(dt)
			if w > 0.001 and tr._s.prio > topPri then topPri = tr._s.prio end
		end
		if topPri >= 0 then
			for i = 1, ACCN do ACC[ACCK[i]] = nil end
			ACCN = 0
			for _, tr in ipairs(list) do
				if tr._s.prio == topPri and tr._s.weight > 0.001 then
					tr:_accumulate(ACC)
				end
			end
			local motors = motorsOf(rig)
			for bone, v in pairs(ACC) do
				local motor = motors[bone]
				if motor then
					local w = v[8]
					if w > 0.0001 then
						local qx, qy, qz, qw = v[4], v[5], v[6], v[7]
						local qn = math.sqrt(qx * qx + qy * qy + qz * qz + qw * qw)
						if qn < 1e-6 then qx, qy, qz, qw = 0, 0, 0, 1
						else qx, qy, qz, qw = qx / qn, qy / qn, qz / qn, qw / qn end
						local cf = qCF(v[1] / w, v[2] / w, v[3] / w, qx, qy, qz, qw)
						pcall(function() motor.Transform = cf end)
					end
				end
			end
			ACCN = ACCN
		end
	end
end

--==================== public API ====================
local function ensureRender()
	if RENDER_CONN then return end
	RENDER_CONN = RunService.RenderStepped:Connect(function(dt)
		local ok, err = pcall(ANIM.step, dt)
		if not ok then warn("[ANIM] step loi: " .. tostring(err)) end
	end)
end

local function seqNameOf(animation)
	if not animation then return nil end
	local ok, v = pcall(function() return animation:GetAttribute("_anim") end)
	if ok and v then return v end
	ok, v = pcall(function() return animation.AnimationId end)
	if ok and type(v) == "string" and string.sub(v, 1, 3) == "ef!" then
		return nil
	end
	if animation.Name and ANIMD[animation.Name] then return animation.Name end
	return nil
end

local function newTrack(animator, animation, seq, name)
	local st = {
		rig = rigOf(animator),
		seq = seq,
		prio = seq and seq.prio or 1000,
		time = 0,
		lastT = 0,
		speed = 1,
		weight = 0,
		target = 0,
		fade = 0.1,
		playing = false,
		msig = {},
	}
	local self = setmetatable({
		_s = st,
		Animation = animation,
		Name = name,
		keyreached = Signal.new(),
		stopped = Signal.new(),
		didLoop = Signal.new(),
		played = Signal.new(),
		_tn = 0,
	}, Track)
	st.keyreached = self.keyreached
	st.stopped = self.stopped
	st.didLoop = self.didLoop
	st.track = self
	-- expose signals theo dung ten Roblox
	self.KeyframeReached = self.keyreached
	self.Stopped = self.stopped
	self.DidLoop = self.didLoop
	self.Played = self.played
	if seq then sortKeys(seq) end
	return self
end

function Track:Play(fade, weight, speed)
	local st = self._s
	if not st.seq then return end
	st.playing = true
	st.fade = fade or 0.1
	if fade and fade > 0 then
		st.weight = st.weight > 0 and st.weight or 0
	else
		st.weight = 1
	end
	st.target = weight or 1
	if speed then st.speed = speed end
	st.time = 0
	st.lastT = 0
	ensureRender()
	local found = false
	for i = 1, #ACTIVE do if ACTIVE[i] == self then found = true break end end
	if not found then ACTIVE[#ACTIVE + 1] = self end
	self.played:Fire()
end

function Track:Stop(fade, reason)
	local st = self._s
	fade = fade or 0
	if fade <= 0 then
		st.playing = false
		st.weight = 0
		st.target = 0
	else
		st.target = 0
		st.fade = fade
	end
	st.stopped:Fire(reason or "Stopped")
end

function Track:AdjustSpeed(s)
	self._s.speed = s or 1
end

function Track:AdjustWeight(w, fade)
	local st = self._s
	st.target = w or 1
	if fade and fade > 0 then
		st.fade = fade
		if st.target > 0 and st.weight <= 0.001 then
			st.weight = 0
			local found = false
			for i = 1, #ACTIVE do if ACTIVE[i] == self then found = true break end end
			if not found then ACTIVE[#ACTIVE + 1] = self end
			ensureRender()
		end
	else
		st.weight = st.target
	end
end

function Track:GetMarkerReachedSignal(name)
	local st = self._s
	local sig = st.msig[name]
	if not sig then
		sig = Signal.new()
		st.msig[name] = sig
	end
	return sig
end

function Track:GetTimeOfKeyframe(name)
	local st = self._s
	if not st.seq then return 0 end
	for _, k in ipairs(st.seq.keys) do
		if k.name == name then return k.t end
	end
	return 0
end

function Track:Destroy()
	self:Stop(0, "Destroyed")
end

-- property access (read)
local TPROPS = {
	Length = function(t) return t._s.seq and t._s.seq.length or 0 end,
	IsPlaying = function(t) return t._s.playing end,
	Looped = function(t) return t._s.seq and t._s.seq.loop or false end,
	Priority = function(t) return t._s.prio end,
	Speed = function(t) return t._s.speed end,
	WeightCurrent = function(t) return t._s.weight end,
	WeightTarget = function(t) return t._s.target end,
	TimePosition = function(t) return t._s.time end,
}
Track.__index = function(t, k)
	local f = rawget(Track, k)
	if f ~= nil then return f end
	local p = TPROPS[k]
	if p then return p(t) end
	return nil
end
Track.__newindex = function(t, k, v)
	if k == "TimePosition" then
		t._s.time = v; t._s.lastT = v; return
	end
	if k == "Speed" then t._s.speed = v; return end
	if k == "Looped" then
		-- khong doi duoc sequence goc; chi ghi nhan
		return
	end
	rawset(t, k, v)
end

function ANIM.LoadAnimation(animator, animation)
	local name = seqNameOf(animation)
	local seq = name and getSeq(name)
	local tr = newTrack(animator, animation, seq, name or (animation and animation.Name) or "Animation")
	if not seq then
		tr._s.seq = nil
	end
	-- luu de GetPlayingAnimationTracks
	local rig = tr._s.rig
	if rig then
		local list = ALLTRACKS[rig]
		if not list then list = {}; ALLTRACKS[rig] = list end
		list[#list + 1] = tr
	end
	return tr
end

local function hashRig(x)
	if not x then return nil end
	return x
end

function ANIM.playingTracks(humanoidOrAnimator)
	local rig = rigOf(humanoidOrAnimator) or humanoidOrAnimator
	local out = {}
	local list = ALLTRACKS[hashRig(rig)]
	if list then
		for _, tr in ipairs(list) do
			if tr._s.playing and tr._s.weight > 0.001 then out[#out + 1] = tr end
		end
	end
	return out
end

function ANIM.register(inst, name)
	pcall(function() inst:SetAttribute("_anim", name) end)
	inst:SetAttribute("_anim", name)
end

function ANIM.seqList()
	local t = {}
	for k in pairs(ANIMD) do t[#t + 1] = k end
	table.sort(t)
	return t
end

-- thay the method cua game: Humanoid:GetPlayingAnimationTracks()
_G.__GAT = function(humanoid)
	return ANIM.playingTracks(humanoid)
end


