--[[====================================================================
  PLAYER CONTROLLER  (thay PlayerModule cua Roblox + ho tro cam ung)
  ------------------------------------------------------------------
  * __VUIS()   : UserInputService ao  — gop input that (ban phim/chuot)
                 + input ao (nut cam ung) -> moi script cua game doc duoc
  * __VMOUSE() : Mouse ao cho Player:GetMouse()
  * Camera quanh nhan vat (keo de xoay, pinch/scroll de zoom)
  * Di chuyen: ban phim WASD hoac joystick cam ung -> Humanoid:Move
  * UI cam ung: joystick + nut Tan cong/Nhay/Chay/Doi vu khi/Nem/...
====================================================================]]--

local CTRL = {}
_G.__CTRL = CTRL

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local REAL_UIS = game:GetService("UserInputService")
local LP = Players.LocalPlayer

--==================== Signal ====================
local Signal = {}
Signal.__index = Signal
local function newSignal()
	return setmetatable({ _h = {} }, Signal)
end
function Signal:Connect(fn)
	local c = { Connected = true, _fn = fn }
	self._h[c] = true
	return c
end
Signal.connect = Signal.Connect
Signal.ConnectParallel = Signal.Connect
function Signal:Fire(...)
	for c in pairs(self._h) do
		if c.Connected then
			local ok, err = pcall(c._fn, ...)
			if not ok then warn("[CTRL] handler: " .. tostring(err)) end
		end
	end
end
CTRL.newSignal = newSignal

--==================== state ====================
local IsA = function(x, t)
	local ok, r = pcall(function() return x:IsA(t) end)
	return ok and r
end

local KEY = {}                -- [KeyCode] = true
local BTN = {}                -- [UserInputType] = true
local HELD = {}               -- real keys held (device)
local MOUSEPOS = Vector2.new(0, 0)
local MOUSEDELTA = Vector2.new(0, 0)
local LOOKZONE_ACTIVE = false

local V = {
	InputBegan = newSignal(),
	InputEnded = newSignal(),
	InputChanged = newSignal(),
	TouchTapInWorld = newSignal(),
	TouchStarted = newSignal(),
	TouchEnded = newSignal(),
	JumpRequest = newSignal(),
	TouchEnabled = false,
	KeyboardEnabled = true,
	MouseEnabled = true,
	GamepadEnabled = false,
	AccelerometerEnabled = false,
	GyroEnabled = false,
	VREnabled = false,
	ModalEnabled = false,
	MouseIconEnabled = true,
	MouseBehavior = Enum.MouseBehavior.Default,
	MouseDeltaSensitivity = 1,
}
V.TouchEnabled = (function()
	local ok, r = pcall(function() return REAL_UIS.TouchEnabled end)
	return ok and r or false
end)()
CTRL.TouchEnabled = V.TouchEnabled

function V:IsKeyDown(k) return KEY[k] == true or HELD[k] == true end
function V:IsMouseButtonPressed(b) return BTN[b] == true end
function V:GetFocusedTextBox() return nil end
function V:GetLastInputType() return V._lastType or Enum.UserInputType.Touch end
function V:GetMouseDelta() return MOUSEDELTA end
function V:GetMouseLocation() return MOUSEPOS end
function V:GetKeysPressed()
	local out = {}
	for k in pairs(KEY) do out[#out + 1] = { KeyCode = k, UserInputType = Enum.UserInputType.Keyboard } end
	for k in pairs(HELD) do out[#out + 1] = { KeyCode = k, UserInputType = Enum.UserInputType.Keyboard } end
	return out
end
function V:GetNavigationGamepad() return nil end
function V:GetConnectedGamepads() return {} end
function V:SetModalEnabled() end
function V:SetMouseIconEnabled() end
function V:SetMouseBehavior() end
CTRL.VUIS = V

local function mkInput(t, extra)
	local inp = {
		UserInputType = t,
		KeyCode = Enum.KeyCode.Unknown,
		Position = Vector3.new(MOUSEPOS.X, MOUSEPOS.Y, 0),
		Delta = Vector3.new(0, 0, 0),
	}
	if extra then
		for k, v in pairs(extra) do inp[k] = v end
	end
	return inp
end

local function fireInput(kind, input, gameProcessed)
	V._lastType = input.UserInputType
	local sig = V[kind]
	if sig then sig:Fire(input, gameProcessed or false) end
end

--==================== virtual key / button API ====================
local function vkey(kc, down)
	if down then
		if KEY[kc] then return end
		KEY[kc] = true
		fireInput("InputBegan", mkInput(Enum.UserInputType.Keyboard, { KeyCode = kc }), false)
	else
		if not KEY[kc] then return end
		KEY[kc] = nil
		fireInput("InputEnded", mkInput(Enum.UserInputType.Keyboard, { KeyCode = kc }), false)
	end
end
CTRL.vkey = vkey

local function vbutton(uit, down)
	if down then
		if BTN[uit] then return end
		BTN[uit] = true
		fireInput("InputBegan", mkInput(uit), false)
	else
		if not BTN[uit] then return end
		BTN[uit] = nil
		fireInput("InputEnded", mkInput(uit), false)
	end
end
CTRL.vbutton = vbutton

local function vmousemove(dx, dy)
	MOUSEDELTA = Vector2.new(dx, dy)
	fireInput("InputChanged", mkInput(Enum.UserInputType.MouseMovement, {
		Delta = Vector3.new(dx, dy, 0),
	}), false)
	MOUSEDELTA = Vector2.new(0, 0)
end
CTRL.vmousemove = vmousemove

local function conn(sig, fn)
	pcall(function() sig:Connect(fn) end)
end
CTRL.conn = conn

--==================== forward input that ====================
conn(REAL_UIS.InputBegan, function(input, gp)
	MOUSEPOS = Vector2.new(input.Position.X, input.Position.Y)
	if input.UserInputType == Enum.UserInputType.Keyboard then
		HELD[input.KeyCode] = true
	elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
		BTN[Enum.UserInputType.MouseButton1] = true
	elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
		BTN[Enum.UserInputType.MouseButton2] = true
	end
	fireInput("InputBegan", input, gp)
end)

conn(REAL_UIS.InputEnded, function(input, gp)
	if input.UserInputType == Enum.UserInputType.Keyboard then
		HELD[input.KeyCode] = nil
	elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
		BTN[Enum.UserInputType.MouseButton1] = nil
	elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
		BTN[Enum.UserInputType.MouseButton2] = nil
	end
	fireInput("InputEnded", input, gp)
end)

conn(REAL_UIS.InputChanged, function(input, gp)
	if input.UserInputType == Enum.UserInputType.MouseMovement then
		MOUSEPOS = Vector2.new(input.Position.X, input.Position.Y)
	end
	fireInput("InputChanged", input, gp)
end)

--==================== virtual mouse ====================
local VM = {
	Button1Down = newSignal(),
	Button1Up = newSignal(),
	Button2Down = newSignal(),
	Button2Up = newSignal(),
	Move = newSignal(),
	KeyDown = newSignal(),
	KeyUp = newSignal(),
	WheelForward = newSignal(),
	WheelBackward = newSignal(),
	Target = nil,
	Hit = CFrame.new(),
	X = 0,
	Y = 0,
	ViewSizeX = 0,
	ViewSizeY = 0,
}
function VM:GetHit()
	return VM.Hit, VM.Target
end

-- cap nhat Hit/Target theo camera + vi tri chuot
local function raycastMouse()
	local cam = workspace.CurrentCamera
	if not cam then return end
	local vp = cam.ViewportSize
	VM.ViewSizeX, VM.ViewSizeY = vp.X, vp.Y
	local x = math.clamp(VM.X, 0, vp.X)
	local y = math.clamp(VM.Y, 0, vp.Y)
	local ray = cam:ViewportPointToRay(x, y)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local char = CTRL.rig
	params.FilterDescendantsInstances = char and { char } or {}
	local res = workspace:Raycast(ray.Origin, ray.Direction * 2000, params)
	if res then
		VM.Hit = CFrame.new(res.Position)
		VM.Target = res.Instance
	else
		VM.Hit = CFrame.new(ray.Origin + ray.Direction * 1000)
		VM.Target = nil
	end
	VM.UnitRay = ray
end

function CTRL.setMousePos(x, y)
	VM.X, VM.Y = x, y
	MOUSEPOS = Vector2.new(x, y)
	raycastMouse()
end

_G.__VMOUSE = function()
	return VM
end

--==================== camera ====================
local cam = workspace.CurrentCamera
local yaw, pitch = 0, math.rad(-12)
local dist = 9
local fp = false
CTRL.yaw, CTRL.pitch, CTRL.dist = yaw, pitch, dist

function CTRL.setRig(rig)
	CTRL.rig = rig
	CTRL.humanoid = rig and rig:FindFirstChildOfClass("Humanoid") or nil
	CTRL.root = rig and (rig:FindFirstChild("HumanoidRootPart") or rig.PrimaryPart) or nil
	CTRL.pivot = rig and (rig:FindFirstChild("CameraPart", true) or rig:FindFirstChild("Head", true)) or nil
	if CTRL.humanoid then pcall(function() CTRL.humanoid.AutoRotate = true end) end
end

local function getPivot()
	if CTRL.rig and CTRL.rig.Parent then
		if CTRL.pivot and CTRL.pivot.Parent then return CTRL.pivot.Position end
		local head = CTRL.rig:FindFirstChild("Head", true)
		if head then return head.Position end
		local root = CTRL.rig:FindFirstChild("HumanoidRootPart")
		if root then return root.Position end
	end
	return nil
end

local function updateCamera(dt)
	if not cam then cam = workspace.CurrentCamera end
	if not cam then return end
	if _G.__VFREE then return end   -- game dang dung free camera cua no
	local pv = getPivot()
	if not pv then return end
	if LP.CameraMode == Enum.CameraMode.LockFirstPerson then fp = true end
	if fp then
		local cf = CFrame.new(pv) * CFrame.fromEulerAnglesYXZ(pitch, yaw, 0)
		cam.CameraType = Enum.CameraType.Scriptable
		cam.CFrame = cf
		if CTRL.rig then
			for _, d in ipairs(CTRL.rig:GetDescendants()) do
				if d:IsA("BasePart") and (d.Name == "Head" or d:GetAttribute("FirstPersonTag")) then
					d.LocalTransparencyModifier = 1
				end
			end
		end
		return
	end
	local focus = pv + Vector3.new(0, 0.6, 0)
	local off = Vector3.new(
		math.sin(yaw) * math.cos(pitch),
		-math.sin(pitch),
		math.cos(yaw) * math.cos(pitch)
	) * dist
	local pos = focus + off
	-- tranh xuyen tuong
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = CTRL.rig and { CTRL.rig } or {}
	local res = workspace:Raycast(focus, off, params)
	if res then
		pos = res.Position + res.Normal * 0.4
	end
	cam.CameraType = Enum.CameraType.Scriptable
	cam.CFrame = CFrame.lookAt(pos, focus)
end

--==================== movement ====================
-- {tien, ngang}: tien + = di toi truoc, ngang + = sang phai
local MOVEKEYS = {
	[Enum.KeyCode.W] = { 1, 0 },
	[Enum.KeyCode.S] = { -1, 0 },
	[Enum.KeyCode.A] = { 0, -1 },
	[Enum.KeyCode.D] = { 0, 1 },
	[Enum.KeyCode.Up] = { 1, 0 },
	[Enum.KeyCode.Down] = { -1, 0 },
	[Enum.KeyCode.Left] = { 0, -1 },
	[Enum.KeyCode.Right] = { 0, 1 },
}
CTRL.joy = Vector2.new(0, 0)     -- -1..1 (x = phai, y = tien)
CTRL.sprint = false

local function updateMove(dt)
	local hum = CTRL.humanoid
	local rig = CTRL.rig
	if not hum or not rig or not rig.Parent then return end
	local f, s = 0, 0
	for k, v in pairs(MOVEKEYS) do
		if V:IsKeyDown(k) then
			f = f + v[1]
			s = s + v[2]
		end
	end
	f = f + CTRL.joy.Y
	s = s + CTRL.joy.X
	local mag = math.sqrt(f * f + s * s)
	if mag > 1 then f, s = f / mag, s / mag; mag = 1 end
	if mag > 0.02 then
		local look = cam.CFrame.LookVector
		local flat = Vector3.new(look.X, 0, look.Z)
		if flat.Magnitude < 0.01 then flat = Vector3.new(0, 0, -1) end
		flat = flat.Unit
		local right = Vector3.new(-flat.Z, 0, flat.X)
		local dir = (flat * f + right * s)
		if dir.Magnitude > 0.01 then
			hum:Move(dir.Unit * math.min(1, mag))
		else
			hum:Move(Vector3.new())
		end
	else
		hum:Move(Vector3.new())
	end

	-- huong xoay: binh thuong Humanoid tu xoay theo huong di,
	-- khi giu Tan cong (MouseButton1) thi xoay theo huong camera de ngam dung
	local firing = V:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
	if firing then
		hum.AutoRotate = false
		local root = CTRL.root
		if root and root.Parent then
			pcall(function()
				local look = cam.CFrame.LookVector
				local fx, fz = look.X, look.Z
				if (fx * fx + fz * fz) > 0.0001 then
					local want = math.atan2(-fx, -fz)
					local cur = root.CFrame
					local cy = select(1, cur:ToEulerAnglesYXZ())
					local d = want - cy
					while d > math.pi do d = d - math.pi * 2 end
					while d < -math.pi do d = d + math.pi * 2 end
					root.CFrame = CFrame.new(cur.Position) * CFrame.fromEulerAnglesYXZ(0, cy + d * 0.3, 0)
				end
			end)
		end
	else
		hum.AutoRotate = true
	end
end

