local gui
local function mk(parent, cls, props)
	local o = Instance.new(cls)
	for k, v in pairs(props or {}) do o[k] = v end
	if parent then o.Parent = parent end
	return o
end

local function buildUI()
	local pg = LP:FindFirstChildOfClass("PlayerGui") or LP:WaitForChild("PlayerGui")
	gui = mk(pg, "ScreenGui", { Name = "V_Controls", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 999 })
	local function round(o, r)
		local c = Instance.new("UICorner")
		c.CornerRadius = UDim.new(1, 0)
		c.Parent = o
	end
	-- vung cam ung trai: joystick
	local stickArea = mk(gui, "Frame", {
		Name = "StickArea", BackgroundTransparency = 1,
		Position = UDim2.new(0, 0, 0.55, 0), Size = UDim2.new(0.45, 0, 0.45, 0), Active = true,
	})
	local stickBase = mk(stickArea, "Frame", {
		Name = "Base", BackgroundColor3 = Color3.fromRGB(25, 25, 30), BackgroundTransparency = 0.55,
		AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.6, 0), Size = UDim2.new(0, 150, 0, 150),
	})
	round(stickBase)
	local knob = mk(stickBase, "Frame", {
		Name = "Knob", BackgroundColor3 = Color3.fromRGB(235, 235, 245), BackgroundTransparency = 0.15,
		AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(0, 62, 0, 62),
	})
	round(knob)
	local dragging, dragStart, baseCenter = false, nil, nil

	local function stickMove(pos)
		if not dragging then return end
		local d = Vector2.new(pos.X, pos.Y) - baseCenter
		local r = 60
		local mag = d.Magnitude
		if mag > r then d = d.Unit * r; mag = r end
		knob.Position = UDim2.new(0.5, d.X, 0.5, d.Y)
		CTRL.joy = Vector2.new(d.X / r, -d.Y / r)
	end

	stickArea.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
			local abs = stickBase.AbsolutePosition + stickBase.AbsoluteSize / 2
			baseCenter = Vector2.new(abs.X, abs.Y)
			dragging = true
			stickMove(input.Position)
		end
	end)
	stickArea.InputChanged:Connect(function(input)
		if dragging then stickMove(input.Position) end
	end)
	stickArea.InputEnded:Connect(function(input)
		if dragging then
			dragging = false
			CTRL.joy = Vector2.new(0, 0)
			knob.Position = UDim2.new(0.5, 0, 0.5, 0)
		end
	end)

	-- nut
	local btnRoot = mk(gui, "Frame", {
		Name = "Buttons", BackgroundTransparency = 1,
		Position = UDim2.new(1, -240, 1, -300), Size = UDim2.new(0, 230, 0, 290),
	})
	local function button(name, label, cx, cy, size, keyOrBtn)
		local b = mk(btnRoot, "TextButton", {
			Name = name, Text = label,
			BackgroundColor3 = Color3.fromRGB(30, 30, 36), BackgroundTransparency = 0.25,
			TextColor3 = Color3.fromRGB(240, 240, 250), TextScaled = true, Font = Enum.Font.GothamBold,
			Position = UDim2.new(0, cx, 0, cy), Size = UDim2.new(0, size, 0, size),
			AutoButtonColor = false, Active = true,
		})
		round(b)
		local stroke = mk(b, "UIStroke", { Color = Color3.fromRGB(120, 120, 140), Thickness = 2 })
		local function down()
			if type(keyOrBtn) == "number" then
				vbutton(keyOrBtn, true)
			else
				vkey(keyOrBtn, true)
			end
			b.BackgroundColor3 = Color3.fromRGB(90, 120, 220)
		end
		local function up()
			if type(keyOrBtn) == "number" then
				vbutton(keyOrBtn, false)
			else
				vkey(keyOrBtn, false)
			end
			b.BackgroundColor3 = Color3.fromRGB(30, 30, 36)
		end
		b.InputBegan:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then down() end
		end)
		b.InputEnded:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then up() end
		end)
		return b
	end

	CTRL.attackBtn = button("Attack", "TAN CONG", 140, 190, 90, Enum.UserInputType.MouseButton1)
	button("Jump", "NHAY", 130, 100, 74, Enum.KeyCode.Space)
	button("Sprint", "CHAY", 60, 190, 64, Enum.KeyCode.LeftShift)
	button("SwitchWeapon", "DOI VK", 60, 100, 64, Enum.KeyCode.R)
	button("Throw", "NEM", 130, 20, 64, Enum.KeyCode.C)
	button("FirstPerson", "NGUOI 1", 60, 20, 64, Enum.KeyCode.T)

	-- nut thu gon
	local toggle = mk(gui, "TextButton", {
		Name = "Toggle", Text = "THU GON", TextScaled = true, Font = Enum.Font.GothamBold,
		BackgroundColor3 = Color3.fromRGB(30, 30, 36), BackgroundTransparency = 0.35,
		TextColor3 = Color3.fromRGB(240, 240, 240),
		Position = UDim2.new(1, -110, 0, 10), Size = UDim2.new(0, 100, 0, 34),
	})
	round(toggle)
	toggle.MouseButton1Click:Connect(function()
		btnRoot.Visible = not btnRoot.Visible
		stickArea.Visible = btnRoot.Visible
	end)
end

--==================== look drag (nua phai man hinh) ====================
local touches = {}
local function lookZone(pos)
	local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
	return pos.X > vp.X * 0.42 and pos.Y < vp.Y * 0.9
end

conn(REAL_UIS.InputBegan, function(input, gp)
	if input.UserInputType ~= Enum.UserInputType.Touch then return end
	if gp then return end
	if not lookZone(input.Position) then return end
	touches[input] = { last = input.Position }
end)
conn(REAL_UIS.InputChanged, function(input, gp)
	if input.UserInputType ~= Enum.UserInputType.Touch then return end
	local t = touches[input]
	if not t then return end
	local d = input.Position - t.last
	t.last = input.Position
	CTRL.setMousePos(input.Position.X, input.Position.Y)
	yaw = yaw - d.X * 0.0065
	pitch = math.clamp(pitch - d.Y * 0.0055, math.rad(-75), math.rad(75))
	CTRL.yaw, CTRL.pitch = yaw, pitch
	vmousemove(d.X, d.Y)
end)
conn(REAL_UIS.InputEnded, function(input)
	touches[input] = nil
end)

-- chuot that (PC)
conn(REAL_UIS.InputChanged, function(input)
	if input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
	if V:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) or LP.CameraMode == Enum.CameraMode.LockFirstPerson then
		yaw = yaw - input.Delta.X * 0.0065
		pitch = math.clamp(pitch - input.Delta.Y * 0.0055, math.rad(-75), math.rad(75))
		CTRL.yaw, CTRL.pitch = yaw, pitch
	end
	CTRL.setMousePos(input.Position.X, input.Position.Y)
end)
conn(REAL_UIS.InputChanged, function(input)
	if input.UserInputType ~= Enum.UserInputType.MouseWheel then return end
	dist = math.clamp(dist - input.Position.Z * 1.2, 2.5, 22)
	CTRL.dist = dist
end)

