--=====================================================================
--  3.1 helper: tao instance tu pack
--=====================================================================
local NODEOF = {}          -- instance -> node index (ke ca ban clone)
local BUILT = {}           -- node index -> instance
local PENDING = {}         -- {inst, prop, nodeIdx}
local SRCSRC = SRC         -- node index -> source text
local errors = 0

local function num(x) return tonumber(x) or 0 end

local function mkCFrame(v)
	-- v = {x,y,z} hoac {x,y,z,m0..m8}
	if v[4] == nil then
		return CFrame.new(num(v[1]), num(v[2]), num(v[3]))
	end
	return CFrame.new(num(v[1]), num(v[2]), num(v[3]),
		num(v[4]), num(v[5]), num(v[6]),
		num(v[7]), num(v[8]), num(v[9]),
		num(v[10]), num(v[11]), num(v[12]))
end

local function setEnumItem(inst, prop, value)
	local cur
	local ok = pcall(function() cur = inst[prop] end)
	if not ok or typeof(cur) ~= "EnumItem" then return false end
	local items = cur.EnumType:GetEnumItems()
	for _, item in ipairs(items) do
		if item.Value == value then
			inst[prop] = item
			return true
		end
	end
	return false
end

local ALIAS = {
	size = "Size", Color3uint8 = "Color", formFactorRaw = "FormFactor",
	Health_XML = "Health", style = "Shape", Texture = "Texture",
	MeshID = "MeshId",      -- ten cu -> ten hien dai (giu nguyen chuoi rbxasset://)
	TextureID = "TextureID", TextureId = "TextureID",
}

local SETT = {
	s  = function(i, p, v) i[p] = v end,
	b  = function(i, p, v) i[p] = v end,
	i  = function(i, p, v) i[p] = v end,
	i6 = function(i, p, v) i[p] = v end,
	f  = function(i, p, v) i[p] = v end,
	d  = function(i, p, v) i[p] = v end,
	u  = function(i, p, v) i[p] = UDim.new(num(v[1]), v[2]) end,
	u2 = function(i, p, v) i[p] = UDim2.new(num(v[1]), v[2], num(v[3]), v[4]) end,
	bk = function(i, p, v) i[p] = BrickColor.new(v) end,
	c3 = function(i, p, v) i[p] = Color3.new(num(v[1]), num(v[2]), num(v[3])) end,
	c8 = function(i, p, v) i[p] = Color3.fromRGB(bit32.band(bit32.rshift(v, 16), 255), bit32.band(bit32.rshift(v, 8), 255), bit32.band(v, 255)) end,
	v2 = function(i, p, v) i[p] = Vector2.new(num(v[1]), num(v[2])) end,
	v3 = function(i, p, v) i[p] = Vector3.new(num(v[1]), num(v[2]), num(v[3])) end,
	cf = function(i, p, v) i[p] = mkCFrame(v) end,
	en = function(i, p, v) setEnumItem(i, p, v) end,
	ns = function(i, p, v)
		local kps = {}
		for k = 2, #v, 2 do
			table.insert(kps, NumberSequenceKeypoint.new(num(v[k]), num(v[k + 1])))
		end
		if #kps == 1 then kps[2] = kps[1] end
		i[p] = NumberSequence.new(kps)
	end,
	cs = function(i, p, v)
		local kps = {}
		for k = 2, #v, 2 do
			local c = v[k + 1]
			table.insert(kps, ColorSequenceKeypoint.new(num(v[k]),
				Color3.fromRGB(bit32.band(bit32.rshift(c, 16), 255), bit32.band(bit32.rshift(c, 8), 255), bit32.band(c, 255))))
		end
		if #kps == 1 then kps[2] = kps[1] end
		i[p] = ColorSequence.new(kps)
	end,
	nr = function(i, p, v) i[p] = NumberRange.new(num(v[1]), num(v[2])) end,
	rc = function(i, p, v) i[p] = Rect.new(num(v[1]), num(v[2]), num(v[3]), num(v[4])) end,
	pp = function(i, p, v)
		if v == nil then return end
		i[p] = PhysicalProperties.new(num(v[1]), num(v[2]), num(v[3]), num(v[4]), num(v[5]))
	end,
	oc = function() end,
	ss = function() end,
}

local function applyProp(inst, prop, typ, value)
	if value == nil then return end
	local fn = SETT[typ]
	if not fn then return end
	local ok, err = pcall(fn, inst, prop, value)
	if not ok then
		local alt = ALIAS[prop]
		if alt and alt ~= prop then
			ok = pcall(fn, inst, alt, value)
		end
		if not ok then
			errors = errors + 1
			if errors < 25 then LOG("prop loi " .. inst.ClassName .. "." .. prop .. ": " .. tostring(err)) end
		end
	end
end

local function buildAll()
	local schemas = {}
	for cls, s in pairs(SCH) do
		local list = {}
		for entry in string.gmatch(s, "[^;]+") do
			local p, t = string.match(entry, "^(.-):(.+)$")
			if p then table.insert(list, {p, t}) end
		end
		schemas[cls] = list
	end

	for nid = 1, #N do
		local d = N[nid]
		local cls = CLS[d[1]]
		local inst
		local ok = pcall(function() inst = Instance.new(cls) end)
		if not ok then
			-- class khong ton tai / bi khoa -> thay bang Folder de giu cay
			inst = Instance.new("Folder")
			errors = errors + 1
		end
		pcall(function() inst.Name = d[2] end)
		local aname = ANIMN and ANIMN[nid]
		if aname then pcall(function() inst:SetAttribute("_anim", aname) end) end
		BUILT[nid] = inst
		NODEOF[inst] = nid
		local vals = d[3]
		local list = schemas[cls] or {}
		for k = 1, #list do
			local v = vals[k]
			if v ~= nil then
				local prop, typ = list[k][1], list[k][2]
				if typ == "rf" then
					table.insert(PENDING, {inst, prop, v})
				else
					applyProp(inst, prop, typ, v)
				end
			end
		end
		local parent = d[4]
		if parent == 0 then
			local target = d[5]
			local host
			if target == "Lighting" then host = game:GetService("Lighting")
			elseif target == "Workspace" then host = WS
			elseif target == "Server_Modules" or target == "Player_Data" then host = RS
			else host = RS end
			pcall(function() inst.Parent = host end)
		else
			pcall(function() inst.Parent = BUILT[parent] end)
		end
	end

	-- pass 2: referent props
	for _, p in ipairs(PENDING) do
		local inst, prop, tgt = p[1], p[2], p[3]
		local target = (tgt ~= 0) and BUILT[tgt] or nil
		if target then
			local ok = pcall(function() inst[prop] = target end)
			if not ok then
				local alt = ALIAS[prop]
				if alt then pcall(function() inst[alt] = target end) end
			end
		end
	end
	LOG(("da tao %d instance (%d prop loi)"):format(#N, errors))
end

-- Animator:LoadAnimation -> engine animation rieng (tools/anim_engine.lua)
local DummyAnim = {}
DummyAnim.__index = function(_, k)
	if k == "Length" or k == "TimePosition" or k == "Speed" or k == "WeightCurrent" then return 0 end
	if k == "IsPlaying" then return false end
	return function() end
end
_G.__LA = function(receiver, anim)
	local ok, res = pcall(function()
		return _G.__ANIM.LoadAnimation(receiver, anim)
	end)
	if ok and res then return res end
	return setmetatable({ Animation = anim, Name = anim and anim.Name }, DummyAnim)
end

--=====================================================================
--  3.2 module loader (require ao)
--=====================================================================
local CACHE = {}
local COMPILED = {}

local function compile(src, chunkname)
	local code = "return function(script, require)\n" .. src .. "\nend"
	local chunk, err = LS(code, chunkname)
	if not chunk then
		return nil, err
	end
	local ok, fn = pcall(chunk)
	if not ok then return nil, fn end
	return fn
end

local function vrequire(inst)
	if type(inst) ~= "userdata" and type(inst) ~= "table" then
		error("require: can instance", 2)
	end
	local nid = NODEOF[inst]
	if not nid then error("require: instance ngoai pack: " .. tostring(inst), 2) end
	local cached = CACHE[nid]
	if cached ~= nil then return cached end
	local src = SRCSRC[nid]
	if not src then error("require: khong co source cho " .. inst:GetFullName(), 2) end
	local fn, err = compile(src, "=" .. inst.Name)
	if not fn then
		error("require loi compile " .. inst.Name .. ": " .. tostring(err), 2)
	end
	local ok, res = pcall(fn, inst, vrequire)
	if not ok then
		error("require loi chay " .. inst.Name .. ": " .. tostring(res), 2)
	end
	CACHE[nid] = res
	return res
end

local function runScript(inst)
	local nid = NODEOF[inst]
	local src = nid and SRCSRC[nid]
	if not src then return end
	local fn, err = compile(src, "=" .. inst.Name)
	if not fn then LOG("compile loi " .. inst.Name .. ": " .. tostring(err)); return end
	local co = coroutine.create(fn)
	local ok, res = coroutine.resume(co, inst, vrequire)
	if not ok then LOG("script loi " .. inst.Name .. ": " .. tostring(res)) end
end

local function cloneMapped(inst)
	local clone = inst:Clone()
	local function rec(a, b)
		local nid = NODEOF[a]
		if nid then NODEOF[b] = nid end
		local ka, kb = a:GetChildren(), b:GetChildren()
		for i = 1, math.min(#ka, #kb) do rec(ka[i], kb[i]) end
	end
	rec(inst, clone)
	return clone
end

