			PHYS:SetPartCollisionGroup(v, "Sticky_Cum")
		end
	end
end)

-- weld Guns/Melee items (port tu MainScript)
pcall(function()
	local function Weld(A, B)
		local w = Instance.new("Weld", A)
		w.C0 = A.CFrame:inverse() * B.CFrame
		w.Part0 = A
		w.Part1 = B
		return w
	end
	local function WeldGroup(model)
		local mainpart = model:FindFirstChild("MainPart")
		if not mainpart then return end
		model.PrimaryPart = mainpart
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") then
				part.CanCollide = false
				part.Anchored = false
				part.CanTouch = false
				if part ~= mainpart then
					Weld(mainpart, part).Parent = model
				end
			end
		end
	end
	local objects = RS:FindFirstChild("Objects")
	if objects then
		for _, folder in ipairs({ "Guns_Items", "Melee_Items" }) do
			local f = objects:FindFirstChild(folder)
			if f then
				for _, m in ipairs(f:GetChildren()) do pcall(WeldGroup, m) end
			end
		end
	end
end)

-- attribute cho Head trong Characters
pcall(function()
	local chars = RS:FindFirstChild("Characters")
	if not chars then return end
	for _, v in ipairs(chars:GetDescendants()) do
		if v.Name == "Head" and v:IsA("BasePart") and v.Parent.Name == "Rig"
			and v.Parent:FindFirstChildOfClass("Humanoid") then
			v:SetAttribute("Part_Category", "Head")
		end
	end
end)

-- face rig: weld cac part con + bo collision
pcall(function()
	local function search(pa)
		for _, V in ipairs(pa:GetDescendants()) do
			local fe = V:FindFirstChild("FacialExpresions")
			if fe and fe:FindFirstChild("Rig") and fe.Rig:FindFirstChild("AnimationController") then
				for _, v in ipairs(V:GetDescendants()) do
					if v:IsA("BasePart") then
						v.CanCollide = false
						v.CanTouch = false
						v.Anchored = false
						if v.Parent:IsA("BasePart") then
							local w = Instance.new("Weld", v.Parent)
							w.C0 = v.CFrame:inverse() * v.Parent.CFrame
							w.Part0 = v
							w.Part1 = v.Parent
						end
					end
				end
			end
		end
	end
	search(RS)
end)

-- _G.Player : proxy (de .Character tro ve rig cua client)
local character
local PlayerProxy = setmetatable({}, {
	__index = function(_, k)
		if k == "Character" then return character end
		local v = LP[k]
		if type(v) == "function" then
			return function(_, ...) return v(LP, ...) end
		end
		return v
	end,
})
_G.Player = PlayerProxy

local currentBody
local function LoadChar(_, pos)
	local chars = RS:FindFirstChild("Characters")
	local rig = chars and chars:FindFirstChild("Rig")
	if not rig then LOG("khong tim thay Characters.Rig"); return end
	pos = pos or Vector3.new(0, 50, 0)
	local body = cloneMapped(rig)
	body.Name = LP.Name
	body.Parent = WS
	pcall(function() body:SetPrimaryPartCFrame(CFrame.new(pos)) end)
	if currentBody and currentBody.Parent then pcall(function() currentBody:Destroy() end) end
	currentBody = body
	character = body
	pcall(function() LP.Character = body end)
	if not body:FindFirstChildOfClass("Humanoid"):FindFirstChildOfClass("Animator") then
		local a = Instance.new("Animator")
		a.Parent = body:FindFirstChildOfClass("Humanoid")
	end
	if _G.__CTRL then
		pcall(function() _G.__CTRL.setRig(body) end)
	end
	local csSrc = Player_Scripts:FindFirstChild("Character_Script")
	if csSrc then
		local cs = cloneMapped(csSrc)
		cs.Parent = body
		cs.Disabled = false
		runScript(cs)
	end
end

